TURATH_CHUNK(74,[{"num":14800,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ غُفِرَ لَكُمْ مَا تَأْتُونَ إِلَى الْبَهَائِمِ لَغُفِرَ لَكُمْ كَثِيرًا."],"takhrij":"حسن: رواه أحمد (27486)، والبيهقي في الشعب (5188) كلاهما من حديث هيثم بن خارجة قال: أخبرنا أبو الربيع سليمان بن عتبة السلمي، عن يونس بن ميسرة بن حلبس، عن أبي إدريس، عن أبي الدرداء فذكره مرفوعا.","grade":"حسن","chapter_ar":"باب الرفق بالبهائم والعناية بها في الحضر والسفر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27486) and al-Bayhaqī in Shuʿab al-Īmān (5188).","chapter_en":"Kindness toward Animals and Caring for Them at Home and during Travel","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":3,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Prophet ﷺ said: “If you were forgiven for what you do to animals, much would indeed be forgiven for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27486)، والبيهقي في الشعب (5188)."},{"num":14801,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: كُنَّا إِذَا نَزَلْنَا مَنْزِلاً لاَ نُسَبِّحُ حَتَّى تحل الرِّحَالَ."],"takhrij":"حسن: رواه أبو داود (2551) عن محمد بن المثنى، حدثني محمد بن جعفر، حدثنا شعبة، عن حمزة الضبي قال: سمعت أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب الرفق بالبهائم والعناية بها في الحضر والسفر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2551).","chapter_en":"Kindness toward Animals and Caring for Them at Home and during Travel","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":3,"content":{"translation":{"en":["Anas narrated: “Whenever we stopped at a place during a journey, we would not perform voluntary prayer until the loads had first been removed from the animals.”"]},"buhuth":{"en":["The phrase “we would not perform voluntary prayer until the loads had been removed” means that they would not pray the Duḥā voluntary prayer until the baggage had been taken off and the riding animals had settled down.","Some scholars also considered it recommended that when a rider stops at a resting place, he should not eat until he has first fed his animal.","Al-Khaṭṭābī stated this in al-Maʿālim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2551)."},{"num":14802,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِيَّاكُمْ أَنْ تَتَّخِذُوا ظُهُورَ دَوَابِّكُمْ مَنَابِرَ، فَإِنَّ اللَّهَ إِنَّمَا سَخَّرَهَا لَكُمْ لِتُبَلِّغَكُمْ إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلاَّ بِشِقِّ الأَنْفُسِ، وَجَعَلَ لَكُمُ الأَرْضَ فَعَلَيْهَا فَاقْضُوا حَاجَتَكُمْ."],"takhrij":"حسن: رواه أبو داود (2567) –ومن طريقه البيهقي (10335)- عن عبدالوهاب بن نجدة، حدثنا ابن عياش، عن يحيى بن أبى عمرو السيبانى، عن ابن أبى مريم، عن أبى هريرة فذكره.","grade":"حسن","chapter_ar":"باب كراهية الوقوف على الدابة لغير حاجة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2567), and through him by al-Bayhaqī (5/255).","chapter_en":"The Dislike of Remaining Stationary on an Animal without a Need","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Beware of taking the backs of your riding animals as pulpits. Allah has only subjected them to you so that they may carry you to lands you could not otherwise reach except with great hardship. And He has made the earth for you, so fulfill your needs upon it.”"]},"buhuth":{"en":["Al-Khaṭṭābī said in al-Maʿālim (3/394–395):","It is authentically established that the Prophet ﷺ delivered a sermon while standing upon his mount.","This shows that remaining upon an animal’s back is permissible when there is a genuine need or some objective that cannot be achieved by dismounting.","The prohibition therefore applies only to remaining on an animal unnecessarily, such as treating it as a permanent seat, thereby tiring and harming the animal without any benefit."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2567)، ومن طريقه البيهقي (10335)."},{"num":14803,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بن أَنَسٍ -وكانت لَهُ صُحْبَةٌ- قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْكَبُوا هَذِهِ الدَّوَابَّ سَالِمَةً، وَايْتَدِعُوهَا سَالِمَةً، وَلَا تَتَّخِذُوهَا كَرَاسِيَّ."],"takhrij":"حسن: رواه أحمد (15641، 15639)، وصحّحه ابن خزيمة (2544)، وابن حبان (5619) كلهم من طرق عن الليث بن سعد، عن يزيد بن أبي حبيب، عن سهل بن معاذ بن أنس، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب كراهية الوقوف على الدابة لغير حاجة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15639, 15641), and authenticated by Ibn Khuzaymah (2544) and Ibn Ḥibbān (5619).","chapter_en":"The Dislike of Remaining Stationary on an Animal without a Need","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":4,"content":{"translation":{"en":["Muʿādh ibn Anas, who was a Companion, narrated that the Messenger of Allah ﷺ said: “Ride these animals while they are healthy, and leave them while they are healthy. Do not use them as chairs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15639، 15641)، وصححه ابن خزيمة (2544)، وابن حبان (5619)."},{"num":14804,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَدِمَ مِنْ سَفَرٍ تُلقّي بِصِبْيَانِ مِنْ أَهْلِ بَيْتِهِ قَالَ: وَإِنَّهُ قَدِمَ مرة مِنْ سَفَرٍ، قَالَ: فَسُبِقَ بِي إِلَيْهِ، قَالَ: فَحَمَلَنِي بَيْنَ يَدَيْهِ، قَالَ: ثُمَّ جِيءَ بِأَحَدِ ابْنَيْ فَاطِمَةَ، إما حسن وإما حسين، فَأَرْدَفَهُ خَلْفَهُ قَالَ: فَدَخَلْنَا الْمَدِينَةَ ثَلَاثَةً عَلَى دَابَّةٍ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2428: 66) من طرق عن أبي معاوية، حدثنا عاصم، عن مورق العجلي، عن عبد الله بن جعفر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ركوب ثلاثة على دابة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2428:66).","chapter_en":"Three People Riding on One Animal","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Jaʿfar narrated: Whenever the Messenger of Allah ﷺ returned from a journey, the children of his household would go out to meet him. On one occasion when he returned from a journey, I was the first to reach him. He placed me in front of him on his mount. Then one of the two sons of Fāṭimah—either al-Ḥasan or al-Ḥusayn—was brought, and the Prophet ﷺ seated him behind himself. Thus we entered Madinah with three people riding on a single animal."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2428: 66)."},{"num":14805,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: نُهِيَ عَنْ رُكُوبِ الْجَلاَّلَةِ."],"takhrij":"صحيح: رواه أبو داود (2557) –ومن طريقه البيهقي (10330) عن مسدد، قال: حدثنا عبد الوارث، عن أيوب، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ركوب الجلالة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2557), and through him by al-Bayhaqī (5/254).","chapter_en":"The Prohibition of Riding an Animal That Feeds on Filth","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated: “Riding al-jallālah was prohibited.”"]},"buhuth":{"en":["Al-Khaṭṭābī said:","Al-jallālah refers to camels that feed upon excrement, while al-jillah means dung.","The Prophet ﷺ disliked riding such animals just as he prohibited eating their meat.","It is said that when camels habitually feed upon filth, their odor becomes foul when they sweat, just as their meat develops an unpleasant odor."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2557)، ومن طريقه البيهقي (10330)."},{"num":14806,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب، يَقُولُ: بَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي إِذْ جَاءَهُ رَجُلٌ وَمَعَهُ حِمَارٌ فَقَالَ: يَا رَسُولَ اللَّهِ ارْكَبْ، وَتَأَخَّرَ الرَّجُلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لأَنْتَ أَحَقُّ بِصَدْرِ دَابَّتِكَ، إِلاَّ أَنْ تَجْعَلَهُ لِي قَالَ: قَدْ جَعَلْتُهُ لَكَ، قَالَ: فَرَكِبَ."],"takhrij":"حسن: رواه الترمذي (2773)، وأبو داود (2572)، وأحمد (22992)، وصحّحه ابن حبان (4735)، والحاكم (2/64) كلهم من حديث حسين بن واقد قال: حدثني عبد الله بن بريدة، عن ابيه فذكره.","grade":"حسن","chapter_ar":"باب صاحب المركب أولى بصدره إلا أن يجعله صاحبه لغيره","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2773), Abū Dāwūd (2572), Aḥmad (22992), and authenticated by Ibn Ḥibbān (4735).","chapter_en":"The Owner of a Mount Has the Greatest Right to Its Front Seat Unless He Gives It to Someone Else","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb narrated: While the Prophet ﷺ was walking, a man came to him with a donkey and said: “O Messenger of Allah, ride.” The man then moved backward to give him the front position. The Messenger of Allah ﷺ said: “You have more right to the front of your own animal unless you give that place to me.” The man replied: “I have given it to you.” So the Prophet ﷺ mounted."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2773)، وأبو داود (2572)، وأحمد (22992)، وصححه ابن حبان (4735)."},{"num":14807,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ: قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ صَاحِبَ الدَّابَّةِ أَحَقُّ بِصَدْرِهَا."],"takhrij":"حسن: رواه أحمد (119) عن الحكم بن نافع، حدثنا ابن عياش، عن أبي سبأ عتبة بن تميم، عن الوليد بن عامر اليزني، عن عروة بن مغيث الأنصاري، عن عمر بن الخطاب فذكره.","grade":"حسن","chapter_ar":"باب صاحب المركب أولى بصدره إلا أن يجعله صاحبه لغيره","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (119).","chapter_en":"The Owner of a Mount Has the Greatest Right to Its Front Seat Unless He Gives It to Someone Else","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated: “The Prophet ﷺ ruled that the owner of an animal has the greatest right to its front seat.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (119)."},{"num":14808,"demo":false,"sanad":"","matn":["حَبِيبَ بْنَ مَسْلَمَةَ، أَتَى قَيْسَ بْنَ سَعْدِ بْنِ عُبَادَةَ فِي الْفِتْنَةِ الْأُولَى، وَهُوَ عَلَى فَرَسٍ، فَأَخَّرَ عَنِ السَّرْجِ، وَقَالَ: ارْكَبْ، فَأَبَى، فَقَالَ لَهُ قَيْسُ بْنُ سَعْدٍ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: صَاحِبُ الدَّابَّةِ أَوْلَى بِصَدْرِهَا فَقَالَ لَهُ حَبِيبٌ: إِنِّي لَسْتُ أَجْهَلُ مَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنِّي أَخْشَى عَلَيْكَ."],"takhrij":"حسن: رواه أحمد (15478)، والطبراني في الكبير (4/25)، وفي الأوسط (1948)، وابن أبي عاصم في الآحاد والمثاني (853) كلهم من طريق حيوة قال: أخبرني عبد العزيز بن عبد الملك بن مُليل، عن عبد الرحمن بن أبي أمية، أن حبيب بن مسلمة أتى قيس بن سعد بن عبادة فذكره.","grade":"حسن","chapter_ar":"باب صاحب المركب أولى بصدره إلا أن يجعله صاحبه لغيره","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15478), al-Ṭabarānī in al-Muʿjam al-Kabīr (4/25), and in al-Muʿjam al-Awsaṭ (1948).","chapter_en":"The Owner of a Mount Has the Greatest Right to Its Front Seat Unless He Gives It to Someone Else","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Ḥabīb ibn Maslamah came to Qays ibn Saʿd ibn ʿUbādah during the first fitnah while Qays was riding a horse. Qays moved backward from the front of the saddle and said: “Ride.” Ḥabīb refused. Qays ibn Saʿd said to him: “I heard the Messenger of Allah ﷺ say: ‘The owner of an animal has the greatest right to its front seat.’” Ḥabīb replied: “I am not unaware of what the Messenger of Allah ﷺ said, but I am concerned for your safety.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15478)، والطبراني في الكبير (4/25)، وفي الأوسط (1948)."},{"num":14809,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ:  بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، وَامْرَأَةٌ مِنَ الْأَنْصَارِ عَلَى نَاقَةٍ، فَضَجِرَتْ فَلَعَنَتْهَا، فَسَمِعَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: خُذُوا مَا عَلَيْهَا، وَدَعُوهَا، فَإِنَّهَا مَلْعُونَةٌ. قَالَ عِمْرَانُ: فَكَأَنِّي أَرَاهَا الْآنَ تَمْشِي فِي النَّاسِ، مَا يَعْرِضُ لَهَا أَحَدٌ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2595) من طرق عن أيوب، عن أبي قلابة، عن أبي المهلب، عن عمران بن حصين، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2595).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated: While the Messenger of Allah ﷺ was on one of his journeys, a woman from the Anṣār was riding a she-camel. The camel annoyed her, so she cursed it. The Messenger of Allah ﷺ heard this and said: “Take whatever is loaded upon it and leave it, for it has been cursed.” ʿImrān said: “It is as though I can still see that she-camel now, walking among the people while no one approached it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2595)."},{"num":14810,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ قَالَ:  بَيْنَمَا جَارِيَةٌ عَلَى نَاقَةٍ، عَلَيْهَا بَعْضُ مَتَاعِ الْقَوْمِ، إِذْ بَصُرَتْ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَتَضَايَقَ بِهِمُ الْجَبَلُ، فَقَالَتْ: حَلْ، اللَّهُمَّ الْعَنْهَا، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُصَاحِبُنَا نَاقَةٌ عَلَيْهَا لَعْنَةٌ.","وفي لفظ: لا أيم الله لا تصاحبنا راحلة عليها لعنة من الله."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2596) من طرق عن سليمان التيمي، عن أبي عثمان، عن أبي برزة الأسلمي، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2596).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Abū Barzah al-Aslamī narrated: A young woman was riding a she-camel that was carrying some of the people’s belongings. She saw the Prophet ﷺ while the mountain path had become narrow for the group, so she said to the camel: “Ḥal! O Allah, curse it.” The Prophet ﷺ said: “A she-camel that has been cursed must not accompany us.” In another wording: “No, by Allah, a riding animal upon which the curse of Allah has been invoked must not accompany us.”"]},"buhuth":{"en":["Her word “ḥal,” with the lām still, is an expression used to urge camels forward."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2596)."},{"num":14811,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَطْنِ بُوَاطٍ، وَهُوَ يَطْلُبُ الْمَجْدِيَّ بْنَ عَمْرٍو الْجُهَنِيَّ، وَكَانَ النَّاضِحُ يَعْتَقِبُهُ مِنَّا الْخَمْسَةُ وَالسِّتَّةُ وَالسَّبْعَةُ، فَدَارَتْ عُقْبَةُ رَجُلٍ مِنَ الْأَنْصَارِ عَلَى نَاضِحٍ لَهُ، فَأَنَاخَهُ فَرَكِبَهُ، ثُمَّ بَعَثَهُ فَتَلَدَّنَ عَلَيْهِ بَعْضَ التَّلَدُّنِ، فَقَالَ لَهُ: شَأْ، لَعَنَكَ اللهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ هَذَا اللَّاعِنُ بَعِيرَهُ؟. قَالَ: أَنَا، يَا رَسُولَ اللَّهِ. قَالَ: انْزِلْ عَنْهُ، فَلَا تَصْحَبْنَا بِمَلْعُونٍ، لَا تَدْعُوا عَلَى أَنْفُسِكُمْ، وَلَا تَدْعُوا عَلَى أَوْلَادِكُمْ، وَلَا تَدْعُوا عَلَى أَمْوَالِكُمْ، لَا تُوَافِقُوا مِنَ اللَّهِ سَاعَةً يُسْأَلُ فِيهَا عَطَاءٌ، فَيَسْتَجِيبُ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (3009) من طرق حاتم بن إسماعيل، عن يعقوب بن مجاهد، عن عبادة بن الوليد بن عبادة بن الصامت، عن جابر بن عبد الله فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3009).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: We traveled with the Messenger of Allah ﷺ during the expedition of Baṭn Buwāṭ while he was seeking al-Majdī ibn ʿAmr al-Juhanī. Five, six, or seven of us would take turns riding a single water-carrying camel. When the turn of a man from the Anṣār came, he made his camel kneel, mounted it, and urged it forward. The camel hesitated somewhat, so he said: “Move! May Allah curse you.” The Messenger of Allah ﷺ asked: “Who is this cursing his camel?” The man replied: “It is I, O Messenger of Allah.” He said: “Get down from it, for a cursed animal must not accompany us. Do not supplicate against yourselves, do not supplicate against your children, and do not supplicate against your wealth, lest you coincide with an hour in which Allah is asked for something and He responds to you.”"]}},"tuhfa":{},"full":1,"rep":[10951,12642,14671],"tks":"صحيح: رواه مسلم (3009)."},{"num":14812,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ يَسِيرُ، فَلَعَنَ رَجُلٌ نَاقَةً، فَقَالَ: أَيْنَ صَاحِبُ النَّاقَةِ؟ فَقَالَ الرَّجُلُ: أَنَا، قَالَ: أَخِّرْهَا فَقَدْ أُجِبْتَ فِيهَا."],"takhrij":"حسن: رواه أحمد (9522) والسياق له، والنسائي في الكبرى (8764) كلاهما من طريق ابن عجلان، قال: سمعت أبي، يحدث عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (9522), and this is his wording, and al-Nasā’ī in al-Sunan al-Kubrā (8764).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated: The Prophet ﷺ was traveling on a journey when a man cursed a she-camel. The Prophet ﷺ asked: “Where is the owner of the she-camel?” The man replied: “I am.” He said: “Move it to the rear, for your supplication concerning it has been answered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9522) والسياق له، والنسائي في الكبرى (8764)."},{"num":14813,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا كَانَتْ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَلَعَنَتْ بَعِيرًا لَهَا، فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُرَدَّ، وَقَالَ: لَا يَصْحَبُنِي شَيْءٌ مَلْعُونٌ."],"takhrij":"حسن: رواه أحمد (24434) عن عارم، حدثنا سعيد بن زيد، عن عمرو بن مالك، عن أبي الجوزاء، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (24434).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["ʿĀ’ishah narrated that she was with the Prophet ﷺ on a journey and cursed one of her camels. The Prophet ﷺ ordered that it be sent back and said: “Nothing that has been cursed is to accompany me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24434)."},{"num":14814,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: سَارَ رَجُلٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَعَنَ بَعِيرَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَبْدَ اللَّهِ، لَا تَسِرْ مَعَنَا عَلَى بَعِيرٍ مَلْعُونٍ."],"takhrij":"حسن: رواه أبو يعلى (3622)، وابن أبي الدنيا في الصمت (387)، والطبراني في الدعاء (2088)، والضياء في المختارة (2179) كلهم من طريق إسماعيل بن أويس قال: حدثني أبي، عن شريك بن عبد الله بن أبي نمر، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن لعن الدواب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (3622), Ibn Abī al-Dunyā in al-Ṣamt (387), and al-Ṭabarānī in al-Duʿāʾ (2088).","chapter_en":"The Prohibition of Cursing Animals","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik narrated: A man was traveling with the Prophet ﷺ and cursed his camel. The Prophet ﷺ said: “O servant of Allah, do not travel with us on a cursed camel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (3622)، وابن أبي الدنيا في الصمت (387)، والطبراني في الدعاء (2088)."},{"num":14815,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَخَلَتِ امْرَأَةٌ النَّارَ مِنْ جَرَّاءِ هِرَّةٍ لَهَا، أَوْ هِرٍّ، رَبَطَتْهَا فَلَا هِيَ أَطْعَمَتْهَا، وَلَا هِيَ أَرْسَلَتْهَا ترمرم مِنْ خَشَاشِ الْأَرْضِ حَتَّى مَاتَتْ هَزْلًا."],"takhrij":"متفق عليه: رواه مسلم في البر والصلة (2619) عن محمد بن رافع، حدثنا عبد الرزاق، حدثنا معمر، عن همام بن منبه، قال: هذا ما حدثنا أبو هريرة، عن رسول الله صلى الله عليه وسلم، فذكر أحاديث منها، وقال رسول الله صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من تعذيب الحيوان الذي لا يؤذي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2619) and al-Bukhārī (3318).","chapter_en":"Warning against Tormenting an Animal That Causes No Harm","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A woman entered the Fire because of a cat that belonged to her. She tied it up, neither feeding it nor releasing it to eat from the small creatures of the earth, until it died from emaciation.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2619)، والبخاري (3318)."},{"num":14816,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ سَجَنَتْهَا حَتَّى مَاتَتْ، فَدَخَلَتْ فِيهَا النَّارَ، لاَ هِيَ أَطْعَمَتْهَا وَلاَ سَقَتْهَا، إِذْ حَبَسَتْهَا، وَلاَ هِيَ تَرَكَتْهَا تَأْكُلُ مِنْ خَشَاشِ الأَرْضِ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3482)، ومسلم في البر والصلة (2242: 151) كلاهما عن عبد الله بن محمد بن أسماء الضُّبعي، حدثنا جويرية بن أسماء، عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من تعذيب الحيوان الذي لا يؤذي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3482) and Muslim (2242:151).","chapter_en":"Warning against Tormenting an Animal That Causes No Harm","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “A woman was punished because of a cat that she confined until it died, and because of it she entered the Fire. She neither fed it nor gave it water while she kept it confined, nor did she release it so that it could eat from the creatures of the earth.”"]}},"tuhfa":{},"full":1,"rep":[13924,16496],"tks":"متفق عليه: رواه البخاري (3482)، ومسلم (2242: 151)."},{"num":14817,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَرَصَتْ نَمْلَةٌ نَبِيًّا مِنَ الأَنْبِيَاءِ، فَأَمَرَ بِقَرْيَةِ النَّمْلِ فَأُحْرِقَتْ، فَأَوْحَى اللَّهُ إِلَيْهِ: أَنْ قَرَصَتْكَ نَمْلَةٌ أَحْرَقْتَ أُمَّةً مِنَ الأُمَمِ تُسَبِّحُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3019)، ومسلم في السلام (2241: 151) كلاهما من طريق يونس، عن ابن شهاب، عن سعيد بن المسيب، أن أبا هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3019) and Muslim (2241:151).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “An ant bit one of the Prophets, so he ordered the entire colony of ants to be burned. Allah then revealed to him: ‘Because one ant bit you, you burned an entire nation among the nations that glorify Allah?’”"]}},"tuhfa":{},"full":1,"rep":[8489],"tks":"متفق عليه: رواه البخاري (3019)، ومسلم (2241: 151)."},{"num":14818,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَزَلَ نَبِيٌّ مِنَ الأَنْبِيَاءِ تَحْتَ شَجَرَةٍ، فَلَدَغَتْهُ نَمْلَةٌ، فَأَمَرَ بِجَهَازِهِ فَأُخْرِجَ مِنْ تَحْتِهَا، ثُمَّ أَمَرَ بِبَيْتِهَا فَأُحْرِقَ بِالنَّارِ، فَأَوْحَى اللَّهُ إِلَيْهِ: فَهَلاَّ نَمْلَةً وَاحِدَةً."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3319)، ومسلم في السلام (2241: 149) كلاهما عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3319) and Muslim (2241:149).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “One of the Prophets stopped beneath a tree, and an ant bit him. He ordered that his belongings be removed from beneath it, then ordered the ant colony to be burned with fire. Allah revealed to him: ‘Why not only the one ant?’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8490],"tks":"متفق عليه: رواه البخاري (3319)، ومسلم (2241: 149)."},{"num":14819,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَتْلِ أَرْبَعٍ مِنَ الدَّوَابِّ: النَّمْلَةُ، وَالنَّحْلَةُ، وَالْهُدْهُدُ، وَالصُّرَدُ."],"takhrij":"صحيح: رواه أبو داود (5267)، وابن ماجه (3224)، وأحمد (3066) كلهم من طريق عبد الرزاق –وهو في مصنفه (8415)، حدثنا معمر، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5267), Ibn Mājah (3224), and Aḥmad (3066).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ prohibited killing four creatures: the ant, the bee, the hoopoe, and the ṣurad bird."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5267)، وابن ماجه (3224)، وأحمد (3066)."},{"num":14820,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الذُّبَابُ كُلُّهُ فِي النَّارِ إِلَّا النَّحْلَةَ وَكَانَ يَنْهَى عَنْ قَتْلِهِنَّ، وَعَنْ إِحْرَاقِ الطَّعَامِ.","قَالَ سُفْيَانُ : يُشْبِهُ أَنْ يَكُونَ إِحْرَاقُ الطَّعَامِ فِي أَرْضِ الْعَدُوِّ ."],"takhrij":"صحيح: رواه الطبراني في الكبير (13436) وفي الأوسط (1575) من طريق محمد بن عمار الموصلي، ثنا القاسم بن يزيد الجرمي، ثنا سفيان الثوري، عن منصور، عن مجاهد، عن عبيد بن عمير الليثي، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (12/389) and al-Muʿjam al-Awsaṭ (1575).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “All flies are in the Fire except the bee.” He would prohibit killing them and prohibit burning food. Sufyān said: “It appears that the reference to burning food concerns food in enemy territory.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (13436)، وفي الأوسط (1575)."},{"num":14821,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الذُّبَابُ كُلُّهُ فِي النَّارِ إِلَّا النَّحْلَةَ."],"takhrij":"حسن: رواه الطبراني في الكبير (11058) عن الحضرمي، ثنا إبراهيم بن أبي معاوية، ثنا أبي، عن الأعمش، عن مجاهد، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (11058).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Prophet ﷺ said: “All flies are in the Fire except the bee.”"]},"buhuth":{"en":["Regarding the words “all flies are in the Fire,” some scholars said that their being in the Fire is not as a punishment for them; rather, they are there as a means of tormenting the inhabitants of the Fire.","See: Fatḥ al-Bārī (10/250)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11058)."},{"num":14822,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ، أَنَّ طَبِيبًا، سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ضِفْدَعٍ يَجْعَلُهَا فِي دَوَاءٍ، فَنَهَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا."],"takhrij":"حسن: رواه أبو داود (3871)، والنسائي (4355)، وأحمد (15757)، والحاكم (4/410-411)، والبيهقي (19004) كلهم من طريق ابن أبي ذئب، عن سعيد بن خالد، عن سعيد بن المسيب، عن عبد الرحمن بن عثمان فذكره.","grade":"حسن","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3871), al-Nasā’ī (4355), Aḥmad (15757), and al-Ḥākim (4/410–411).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿUthmān narrated: A physician asked the Prophet ﷺ about using a frog in medicine, so the Prophet ﷺ prohibited him from killing it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11548],"tks":"حسن: رواه أبو داود (3871)، والنسائي (4355)، وأحمد (15757)، والحاكم (4/410-411)."},{"num":14823,"demo":false,"sanad":"","matn":["عَنْ أَبِي زُهَيْرٍ النَّمِيرِيِّ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَقْتُلُوا الْجَرَادَ؛ فَإِنَّهُ جُنْدُ من جنود اللَّهِ تَعَالَى."],"takhrij":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (1440)، والطبراني في الكبير (22/297)، وفي الأوسط (9277)، ومسند الشاميين (1656)، وأبو نعيم في معرفة الصحابة (6804) كلهم من طرق عن إسماعيل بن عياش، حدثني ضمضم بن زرعة، عن شريح بن عبيد، عن أبي زهير النميري فذكره.","grade":"حسن","chapter_ar":"باب في الحيوانات التي نهي عن قتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Āḥād wa-al-Mathānī (1440), al-Ṭabarānī in al-Muʿjam al-Kabīr (22/297), and al-Muʿjam al-Awsaṭ (9277).","chapter_en":"Animals Whose Killing Has Been Prohibited","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Abū Zuhayr al-Numayrī narrated that the Messenger of Allah ﷺ said: “Do not kill frogs, for their croaking is glorification of Allah, and do not kill bats; for when Bayt al-Maqdis was destroyed, the bat said: ‘My Lord, give me power over the sea so that I may drown them.’” In a shorter wording: “Do not kill frogs, for they are among the soldiers of Allah, the Exalted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (1440)، والطبراني في الكبير (22/297)، وفي الأوسط (9277)."},{"num":14824,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ ـ رَضِيَ اللَّهُ عَنْهَا ـ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ خَمْسٌ فَوَاسِقُ، يُقْتَلْنَ فِي الْحَرَمِ: الْفَأْرَةُ، وَالْعَقْرَبُ، وَالْحُدَيَّا، وَالْغُرَابُ، وَالْكَلْبُ الْعَقُورُ.","وفي رواية: الحيّة بدل العقرب."],"takhrij":"متفق عليه: رواه البخاري في بد الخلق (3314)، ومسلم في الحج (1198: 69) كلاهما من طريق يزيد بن زريع، حدثنا معمر، عن الزهري، عن عروة، عن عائشة فذكرته. والرواية الأخرى لمسلم (67) من طريق قتادة، عن سعيد بن المسيب، عن عائشة.","grade":"متفق عليه","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3314) and Muslim (1198:69).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Five harmful creatures may be killed even within the Sacred Precinct: the mouse, the scorpion, the crow, the kite, and the vicious dog.” In another narration, “the snake” appears in place of “the scorpion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3314)، ومسلم (1198: 69)."},{"num":14825,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ: إِنِّي لأَعْجَبُ مِمَّنْ يَأْكُلُ الْغُرَابَ، فَقَدْ أَذِنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قَتْلِهِ، وَسَمَّاهُ فَاسِقًا، وَاللَّهِ مَا هُوَ مِنَ الطَّيِّبَاتِ."],"takhrij":"حسن: رواه البزار –كشف الأستار (1214)، والبيهقي (19369) كلاهما من طريق إسماعيل بن أبي أويس، حدثني أبي، عن يحيى بن سعيد، عن عمرة بنت عبد الرحمن، وعن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (1214), and al-Bayhaqī (9/317).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah said: “I am truly amazed at whoever eats crow, for the Prophet ﷺ permitted its killing and called it a fāsiq. By Allah, it is not among the wholesome things.”"]},"buhuth":{"en":["The statement of ʿĀ’ishah, Mother of the Believers, “I am truly amazed at whoever eats crow,” followed by her reasoning that the Prophet ﷺ permitted its killing, clearly indicates that she held the view that animals whose killing has been commanded are unlawful to eat.","This is one of the scholarly positions. According to those scholars, the same principle applies to animals whose killing has been prohibited.","Al-Ḥāfiẓ al-Bayhaqī said in al-Sunan al-Kubrā (9/318):","“Whatever has been commanded to be killed both outside and within the Sacred Precinct is unlawful to eat. If it were lawful, its killing would not have been commanded in the Sacred Precinct or while in iḥrām, when Allah has prohibited killing game. Likewise, whatever has been prohibited from being killed is unlawful to eat. If it were lawful, its slaughter would have been commanded and its killing would not have been prohibited, just as killing those animals whose slaughter and consumption are lawful has not been prohibited. And Allah knows best.”","Al-Khaṭṭābī said in Maʿālim al-Sunan (8/113):","“As for the hoopoe and the ṣurad bird, the prohibition against killing them indicates that their flesh is unlawful. This is because when the killing of an animal is prohibited, and that prohibition is not due to its sanctity or because it causes harm, then it indicates the unlawfulness of its flesh.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار - كشف الأستار (1214)، والبيهقي (19369)."},{"num":14826,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْحَيَّةُ فَاسِقَةٌ، وَالْعَقْرَبُ فَاسِقَةٌ، وَالْفَأْرَةُ فَاسِقَةٌ، وَالْغُرَابُ فَاسِقٌ. فَقِيلَ لِلْقَاسِمِ أَيُؤْكَلُ الْغُرَابُ؟ قَالَ: مَنْ يَأْكُلُهُ بَعْدَ قَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه ابن ماجه (3249) عن محمد بن بشار، حدثنا الأنصاري، حدثنا المسعودي، حدثنا عبد الرحمن بن القاسم بن محمد بن أبي بكر الصديق، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3249).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “The snake is a harmful creature, the scorpion is a harmful creature, the mouse is a harmful creature, and the crow is a harmful creature.” Al-Qāsim was asked: “May crow be eaten?” He replied: “Who would eat it after the Messenger of Allah ﷺ called it a fāsiq?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3249)."},{"num":14827,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ ـ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلْوَزَغِ: الْفُوَيْسِقُ. وَلَمْ أَسْمَعْهُ أَمَرَ بِقَتْلِهِ. وَزَعَمَ سَعْدُ بْنُ أَبِي وَقَّاصٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلِهِ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3306)، ومسلم في السلام (2239) كلاهما من طريق ابن وهب، اخبرني يونس، عن الزهري، عن عروة، عن عائشة فذكرته. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3306) and Muslim (2239). The wording is that of al-Bukhārī.","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ called the gecko: “The little harmful creature.” She said: “I did not personally hear him command that it be killed, but Saʿd ibn Abī Waqqāṣ stated that the Prophet ﷺ did command its killing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3306)، ومسلم (2239)، والسياق للبخاري."},{"num":14828,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص، أن النبي صلى الله عليه وسلم أمر بقتل الوزغ، وسماه فويسقا."],"takhrij":"صحيح: رواه مسلم في السلام (2238) من طرق عن عبد الرزاق، أخبرنا معمر، عن الزهري، عن عامر بن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2238).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated: The Prophet ﷺ ordered that geckos be killed and called the gecko: “a little harmful creature.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2238)."},{"num":14829,"demo":false,"sanad":"","matn":["عَنْ أُمِّ شَرِيكٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم أَمَرَهَا بِقَتْلِ الْأَوْزَاغِ.","وزاد في رواية: وقال: كان ينفخ على إبراهيم عليه السلام."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3307)، ومسلم في السلام (2237: 142) كلاهما من طريق سفيان بن عيينة، حدثنا عبد الحميد بن جبير بن شيبة، عن سعيد بن المسيب، أن أم شريك أخبرته فذكرته. والزيادة للبخاري في الأنبياء (3359) من طريق ابن جريج، عن عبد الحميد بن جبير به.","grade":"متفق عليه","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3307) and Muslim (2237:142).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Umm Sharīk narrated: The Prophet ﷺ ordered her to kill geckos. Another narration adds that he said: “It used to blow upon Ibrāhīm, peace be upon him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3307)، ومسلم (2237: 142)."},{"num":14830,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ قَتَلَ وَزَغَةً فِي أَوَّلِ ضَرْبَةٍ فَلَهُ كَذَا وَكَذَا حَسَنَةً، وَمَنْ قَتَلَهَا فِي الضَّرْبَةِ الثَّانِيَةِ فَلَهُ كَذَا وَكَذَا حَسَنَةً، - لِدُونِ الْأُولَى، - وَإِنْ قَتَلَهَا فِي الضَّرْبَةِ الثَّالِثَةِ فَلَهُ كَذَا وَكَذَا حَسَنَةً، - لِدُونِ الثَّانِيَةِ.","وفي لفظ: مَنْ قَتَلَ وَزَغًا فِي أَوَّلِ ضَرْبَةٍ كُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَفِي الثَّانِيَةِ دُونَ ذَلِكَ، وَفِي الثَّالِثَةِ دُونَ ذَلِكَ.","وفي لفظ: في أول ضربة سبعين حسنة."],"takhrij":"صحيح: رواه مسلم في السلام (2240) من طرق عن سهيل، عن أبيه، عن أبي هريرة فذكره. ورواه جرير، عن سهيل به باللفظ الثاني.","grade":"صحيح","chapter_ar":"باب في الحيوانات التي أمر بقتلها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2240).","chapter_en":"Animals Whose Killing Has Been Commanded","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever kills a gecko with the first strike will receive such-and-such a number of good deeds. Whoever kills it with the second strike will receive such-and-such a number of good deeds, fewer than the first. And whoever kills it with the third strike will receive such-and-such a number of good deeds, fewer than the second.” In another wording: “Whoever kills a gecko with the first strike will have one hundred good deeds recorded for him; for the second, less than that; and for the third, less than that.” And in another wording: “For the first strike, seventy good deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2240)."},{"num":14831,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ: لَعَنَ رَجُلٌ دِيكًا صَاحَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَلْعَنْهُ، فَإِنَّهُ يَدْعُو إِلَى الصَّلَاةِ.","وفي رواية: فإنه يوقظ للصلاة."],"takhrij":"صحيح: رواه أبو داود (5101)، وعبد الرزاق (20498) وعنه أحمد (17034) كلهم من طرق عن صالح بن كيسان، عن عبيد الله بن عبد الله بن عتبة عن زيد بن خالد الجهني قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن لعن الديك","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5101), ʿAbd al-Razzāq (20498), and through him Aḥmad (17034).","chapter_en":"The Prohibition of Cursing the Rooster","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["Zayd ibn Khālid al-Juhanī narrated: A man cursed a rooster that crowed in the presence of the Prophet ﷺ. The Prophet ﷺ said: “Do not curse it, for it calls people to prayer.” In another narration: “For it awakens people for prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5101)، وعبد الرزاق (20498)، وعنه أحمد (17034)."},{"num":14832,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الضَّرْبِ فِي الْوَجْهِ، وَعَنِ الْوَسْمِ فِي الْوَجْهِ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2116) من طرق عن ابن جريج، عن أبي الزبير، عن جابر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الضرب في الوجه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2116).","chapter_en":"The Prohibition of Striking the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":13,"content":{"translation":{"en":["Jābir narrated: The Messenger of Allah ﷺ prohibited striking the face and branding the face."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2116)."},{"num":14833,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ كَرِهَ أَنْ تُعْلَمَ الصُّورَةُ،. وَقَالَ ابْنُ عُمَرَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُضْرَبَ."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5541) عن عبيد الله بن موسى، عن حنظلة، عن سالم، عن ابن عمر أنه كره أن تُعلم الصورة.","grade":"صحيح","chapter_ar":"باب النهي عن الضرب في الوجه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5541).","chapter_en":"The Prohibition of Striking the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Prophet ﷺ prohibited striking the face."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5541)."},{"num":14834,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَيْهِ حِمَارٌ قَدْ وُسِمَ فِي وَجْهِهِ فَقَالَ: لَعَنَ اللَّهُ الَّذِي وَسَمَهُ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2117: 107) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الوسم في الحيوان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2117:107).","chapter_en":"The Prohibition of Branding an Animal on the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh al-Anṣārī narrated: The Prophet ﷺ passed by a donkey that had been branded on its face and said: “May Allah curse the one who branded it.”"]},"buhuth":{"en":["Abū Dāwūd (2564) also narrated from Jābir that the Prophet ﷺ passed by a donkey whose face had been branded and said:","“Has it not reached you that I have cursed whoever brands an animal on its face or strikes it on its face?”","He therefore prohibited that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2117: 107)."},{"num":14835,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَعَنَ مَنْ يَسِمُ فِي الْوَجْهُ."],"takhrij":"صحيح: رواه الطبراني في الكبير (11926) عن أحمد بن سليمان بن أيوب المديني الأصبهاني، ثنا محمد بن علي بن الحسن بن شقيق، ثنا أبي، ثنا أبو حمزة (هو محمد بن ميمون السكري)، عن عبد الكريم (هو ابن مالك الجزري)، عن عكرمة، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الوسم في الحيوان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (11/335).","chapter_en":"The Prohibition of Branding an Animal on the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Messenger of Allah ﷺ cursed the one who brands an animal on the face."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (11926)."},{"num":14836,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَ الْعَبَّاسُ يَسِيرُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عَلَى بَعِيرٍ قَدْ وَسَمَهُ فِي وَجْهِهِ بِالنَّارِ، فَقَالَ: مَا هَذَا الْمِيسَمُ يَا عَبَّاسُ؟ قَالَ: مِيسَمٌ كُنَّا نَسِمُهُ فِي الْجَاهِلِيَّةِ فَقَالَ: لَا تَسِمُوا بِالْحَريقِ."],"takhrij":"حسن: رواه الطبراني (11928) عن زكريا بن يحيى الساجي، ثنا محمد بن المثنى، ثنا عثمان بن عمر، ثنا عثمان بن مرة، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الوسم في الحيوان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī (11/350).","chapter_en":"The Prohibition of Branding an Animal on the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: Al-ʿAbbās was traveling with the Prophet ﷺ on a camel whose face he had branded with fire. The Prophet ﷺ asked: “What is this brand, O ʿAbbās?” He replied: “It is a brand that we used in the pre-Islamic period.” The Prophet ﷺ said: “Do not brand with burning.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (11928)."},{"num":14837,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَارًا مَوْسُومًا فِي وَجْهِهِ فَقَالَ: لَعَنَ اللَّهُ مَنْ فَعَلَ هَذَا."],"takhrij":"حسن: رواه البزار (7342)، والطبراني في الأوسط (4304) كلاهما من طريق عبد الله بن المثنى، عن ثمامة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الوسم في الحيوان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (7342) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4292).","chapter_en":"The Prohibition of Branding an Animal on the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":14,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ saw a donkey that had been branded on its face and said: “May Allah curse whoever did this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (7342)، والطبراني في الأوسط (4304)."},{"num":14838,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَخٍ لِي يُحَنِّكُهُ، وَهْوَ فِي مِرْبَدٍ لَهُ، فَرَأَيْتُهُ يَسِمُ شَاةً ـ حَسِبْتُهُ قَالَ: ـ فِي آذَانِهَا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح (5542)، ومسلم في اللباس والزينة (2119: 110) كلاهما من حديث شعبة، عن هشام بن زيد، قال: سمعت أنسا يحدث فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الوسم في غير الوجه للعلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5542) and Muslim (2119:110).","chapter_en":"The Permissibility of Branding Away from the Face for Identification","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Mālik narrated: I came to the Prophet ﷺ with a brother of mine so that he could perform taḥnīk for him. The Prophet ﷺ was in an enclosure belonging to him, and I saw him branding sheep—I think he said—on their ears."]}},"tuhfa":{},"full":1,"rep":[3967],"tks":"متفق عليه: رواه البخاري (5542)، ومسلم (2119: 110)."},{"num":14839,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ:  وَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَارًا مَوْسُومَ الْوَجْهِ، فَأَنْكَرَ ذَلِكَ، قَالَ: فَوَاللهِ لَا أَسِمُهُ إِلَّا فِي أَقْصَى شَيْءٍ مِنَ الْوَجْهِ، فَأَمَرَ بِحِمَارٍ لَهُ فَكُوِيَ فِي جَاعِرَتَيْهِ، فَهُوَ أَوَّلُ مَنْ كَوَى الْجَاعِرَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2118) عن أحمد بن عيسى، أخبرنا ابن وهب، أخبرني عمرو بن الحارث، عن يزيد بن أبي حبيب، أن ناعما أبا عبدالله، مولى أم سلمة حدثه أنه، سمع ابن عباس، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب جواز الوسم في غير الوجه للعلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2118).","chapter_en":"The Permissibility of Branding Away from the Face for Identification","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The Messenger of Allah ﷺ saw a donkey that had been branded on its face and objected to it. A man said: “By Allah, I will only brand it at the part farthest from the face.” He then ordered that one of his donkeys be branded on the two fleshy areas beside the base of its tail. Thus, he was the first to brand in that location."]},"buhuth":{"en":["The “two jāʿirahs” are the two fleshy areas surrounding the base of the tail."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2118)."},{"num":14840,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بْنِ عبيد اللَّهِ قَالَ: مُرَّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبَعِيرٍ قَدْ وُسِمَ فِي وَجْهِهِ فَقَالَ: لَوْ أَنَّ أَهْلَ هَذَا الْبَعِيرِ عَزَلُوا النَّارَ عَنْ هَذِهِ الدَّابَّةِ؟ قَالَ: فَقُلْتُ: لَأَسِمَنَّ فِي أَبْعَدِ مَكَانٍ مِنْ وَجْهِهَا، قَالَ: فَوَسَمْتُ فِي عَجْبِ الذَّنَبِ."],"takhrij":"حسن: رواه أبو يعلى (651) –ومن طريقه الضياء في المختارة (838)- عن يونس بن بكير، عن طلحة بن يحيى، عن يحيى، وعيسى ابني طلحة، عن أبيهما، قال: فذكره.","grade":"حسن","chapter_ar":"باب جواز الوسم في غير الوجه للعلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (651), and through him by al-Ḍiyāʾ in al-Mukhtārah (838).","chapter_en":"The Permissibility of Branding Away from the Face for Identification","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":15,"content":{"translation":{"en":["Ṭalḥah ibn ʿUbaydillāh narrated: A camel that had been branded on its face passed by the Messenger of Allah ﷺ. He said: “If only the owners of this camel had kept the fire away from this animal’s face.” Ṭalḥah said: “I then said, ‘I will certainly brand only at the place farthest from its face.’” So I branded it at the coccyx, near the base of the tail."]},"buhuth":{"en":["The expression “ʿajab al-dhanab” refers to the bone at the very bottom of the spine near the buttocks.","See: al-Nihāyah (3/184)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (651)، ومن طريقه الضياء في المختارة (838)."},{"num":14841,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدًا مَأْمُورًا مَا اخْتَصَّنَا دُونَ النَّاسِ بِشَيْءٍ إِلاَّ بِثَلاَثٍ: أَمَرَنَا أَنْ نُسْبِغَ الْوُضُوءَ، وَأَنْ لاَ نَأْكُلَ الصَّدَقَةَ، وَأَنْ لاَ نُنْزِيَ حِمَارًا عَلَى فَرَسٍ."],"takhrij":"حسن: رواه الترمذي (1701)، وأبوداود (808) مطولا، والنسائي (141، 3581)، وابن ماجه (426) مختصرا، وأحمد (1977)، وصحّحه ابن خزيمة (175) كلهم من طرق عن أبي جضهم موسى بن سالم، عن عبد الله بن عبيد الله بن عباس، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية أن ينزى الحمر على الخيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1701), Abū Dāwūd (808) in a longer narration, al-Nasā’ī (141, 3581), and Ibn Mājah (426).","chapter_en":"The Dislike of Breeding Donkeys with Horses","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbās narrated: “The Messenger of Allah ﷺ was a servant who was commanded. He did not single us out over the rest of the people with anything except three matters: he commanded us to perform wuḍūʾ thoroughly, not to consume charity, and not to breed a donkey with a mare.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1701)، وأبو داود (808) مطولا، والنسائي (141، 3581)، وابن ماجه (426)."},{"num":14842,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةٌ فَرَكِبَهَا. فَقَالَ عَلِيٌّ: لَوْ حَمَلْنَا الْحَمِيرَ عَلَى الْخَيْلِ فَكَانَتْ لَنَا مِثْلُ هَذِهِ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا يَفْعَلُ ذَلِكَ الَّذِينَ لاَ يَعْلَمُونَ."],"takhrij":"صحيح: رواه أبو داود (2565)، والنسائي (3580)، وأحمد (785)، وصحّحه ابن حبان (4682)، والبيهقي (19784) كلهم من طريق الليث، عن يزيد بن ابي حبيب، عن أبي الخير (هو مرثد بن عبد الله)، عن عبد الله بن زرير، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أن ينزى الحمر على الخيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2565), al-Nasā’ī (3580), Aḥmad (785), and authenticated by Ibn Ḥibbān (4682).","chapter_en":"The Dislike of Breeding Donkeys with Horses","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":16,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: A mule was presented as a gift to the Messenger of Allah ﷺ, and he rode it. ʿAlī said: “If only we bred donkeys with horses, then we too could have animals like this.” The Messenger of Allah ﷺ said: “Only those who do not know do that.”"]},"buhuth":{"en":["Al-Khaṭṭābī said in Maʿālim al-Sunan (2/251):","“It appears—and Allah knows best—that the meaning is that when donkeys are bred with horses, the benefits of horses are diminished, their number decreases, and their reproduction is interrupted. Horses are needed for riding, speed, pursuit, fighting the enemy, and securing spoils. Their meat is lawful, and a share is assigned for the horse just as a share is assigned for the rider. None of these virtues belong to the mule. Therefore, the Prophet ﷺ desired that the number of horses increase and their offspring multiply because of the benefit and good they contain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2565)، والنسائي (3580)، وأحمد (785)، وصححه ابن حبان (4682)."},{"num":14843,"demo":false,"sanad":"","matn":["عَنْ أَبِي بشير الأنصاري أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، قَالَ: فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَسُولاً، قَالَ عَبْدُ اللَّهِ بن أَبِي بَكْرٍ: حَسِبْتُ أَنَّهُ قَالَ: وَالنَّاسُ فِي مقيلهم: لاَ تبقين فِي رَقَبَةِ بَعِيرٍ قِلاَدَةٌ مِنْ وَتَرٍ، أَوْ قِلاَدَةٌ، إِلاَّ قُطِعَتْ.","قَالَ يَحْيَى: سَمِعْتُ مَالِكًا يَقُولُ: أُرَى ذلِكَ مِنَ الْعَيْنِ."],"takhrij":"متفق عليه: رواه مالك في كتاب صفة النبي صلى الله عليه وسلم (41) عن عبد الله بن أبي بكر، عن عباد بن تميم، أن أبا بشير الأنصاري أخبره فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهة قلادة الوتر في رقبة البعير","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ṣifat al-Nabī ﷺ (41), al-Bukhārī (3005), and Muslim (2115:105).","chapter_en":"The Dislike of Hanging a Bowstring around a Camel’s Neck","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":17,"content":{"translation":{"en":["Abū Bashīr al-Anṣārī narrated: He was with the Messenger of Allah ﷺ on one of his journeys when the Messenger of Allah ﷺ sent a messenger. ʿAbdullāh ibn Abī Bakr said: “I think he said this while the people were resting at midday.” The messenger was instructed to announce: “No necklace made from a bowstring—or any such necklace—is to remain around the neck of a camel except that it must be cut off.” Yaḥyā said: “I heard Mālik say: ‘I think this was because of the evil eye.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (41)، والبخاري (3005)، ومسلم (2115: 105)."},{"num":14844,"demo":false,"sanad":"","matn":["عن أَبِي بن عَبَّاسٍ بن سهل، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَائِطِنَا فَرَسٌ يُقَالُ لَهُ: اللُّحَيْفُ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2855) عن علي بن عبد الله بن جعفر، حدثنا معن بن عيسى، حدثنا أبي بن عباس بن سهل، عن أبيه، عن جده، قال: فذكره.","grade":"صحيح","chapter_ar":"باب في الرجل يسمي دابته","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2855).","chapter_en":"A Man Giving His Riding Animal a Name","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":18,"content":{"translation":{"en":["Ubayy ibn ʿAbbās ibn Sahl narrated from his father, from his grandfather: “The Prophet ﷺ had a horse in our garden called al-Luḥayf.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2855)."},{"num":14845,"demo":false,"sanad":"","matn":["عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ رِدْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى حِمَارٍ يُقَالُ لَهُ: عُفَيْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2856)، ومسلم في الإيمان (30: 49) كلاهما من طريق أبي الأحوص سلام بن سليم، عن أبي إسحاق، عن عمرو بن ميمون، عن معاذ بن جبل فذكره.","grade":"متفق عليه","chapter_ar":"باب في الرجل يسمي دابته","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2856) and Muslim (30:49).","chapter_en":"A Man Giving His Riding Animal a Name","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":18,"content":{"translation":{"en":["Muʿādh ibn Jabal narrated: “I was riding behind the Prophet ﷺ on a donkey called ʿUfayr.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2856)، ومسلم (30: 49)."},{"num":14846,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ فَزَعٌ بِالْمَدِينَةِ، فَاسْتَعَارَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَسًا لَنَا يُقَالُ لَهُ: مَنْدُوبٌ. فَقَالَ: مَا رَأَيْنَا مِنْ فَزَعٍ، وَإِنْ وَجَدْنَاهُ لَبَحْرًا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2857)، ومسلم في الفضائل (2307: 49) كلاهما من طرق عن شعبة، عن قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب في الرجل يسمي دابته","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2857) and Muslim (2307:49).","chapter_en":"A Man Giving His Riding Animal a Name","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":18,"content":{"translation":{"en":["Anas narrated: There was a sudden alarm in Madinah, so the Prophet ﷺ borrowed a horse belonging to us called Mandūb. He later said: “We found nothing to be afraid of, and indeed we found the horse to be like a sea.” That is, extremely fast and smooth in its running."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2857)، ومسلم (2307: 49)."},{"num":14847,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلَابِ، حَتَّى إِنَّ الْمَرْأَةَ تَقْدَمُ مِنَ الْبَادِيَةِ بِكَلْبِهَا فَنَقْتُلُهُ، ثُمَّ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا، وَقَالَ: عَلَيْكُمْ بِالْأَسْوَدِ الْبَهِيمِ ذِي النُّقْطَتَيْنِ، فَإِنَّهُ شَيْطَانٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة والمزارعة (1572) من طريق روح بن عبادة، حدثنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الكلاب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1572).","chapter_en":"What Has Been Narrated Concerning Killing Dogs","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ ordered us to kill dogs, to the extent that a woman would come from the desert with her dog and we would kill it. Then the Prophet ﷺ prohibited killing them and said: “You should kill the completely black dog with two spots, for it is a devil.”"]}},"tuhfa":{},"full":1,"rep":[8235],"tks":"صحيح: رواه مسلم (1572)."},{"num":14848,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْلاَ أَنَّ الْكِلاَبَ أُمَّةٌ مِنَ الأُمَمِ لأَمَرْتُ بِقَتْلِهَا، فَاقْتُلُوا مِنْهَا الأَسْوَدَ الْبَهِيمَ."],"takhrij":"صحيح: رواه أبو داود (2845)، والترمذي (1486)، والنسائي (4280)، وابن ماجه (3205)، وأحمد (6788)، وابن حبان (5657) كلهم من طريق يونس بن عبيد، عن الحسن، عن عبد الله بن مغفل فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الكلاب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2845), al-Tirmidhī (1486), al-Nasā’ī (4280), Ibn Mājah (3205), and Aḥmad (6788).","chapter_en":"What Has Been Narrated Concerning Killing Dogs","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn Mughaffal narrated that the Messenger of Allah ﷺ said: “Were it not that dogs are a community among the communities, I would have ordered that they all be killed. So kill from among them the completely black dog.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2845)، والترمذي (1486)، والنسائي (4280)، وابن ماجه (3205)، وأحمد (6788)."},{"num":14849,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلِ الْكِلاَبِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (14) عن نافع، عن عبد الله بن عمر فذكره. ورواه البخاري في بدء الخلق (3323)، ومسلم في المساقاة (1570: 43) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الكلاب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Istiʾdhān (14), al-Bukhārī (3323), and Muslim (1570:43).","chapter_en":"What Has Been Narrated Concerning Killing Dogs","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated: The Messenger of Allah ﷺ ordered that dogs be killed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14)، والبخاري (3323)، ومسلم (1570: 43)."},{"num":14850,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْتُلَ الْكِلَابَ، فَخَرَجْتُ أَقْتُلُهَا لَا أَرَى كَلْبًا إِلَّا قَتَلْتُهُ، فَإِذَا كَلْبٌ يَدُورُ بِبَيْتٍ، فَذَهَبْتُ لِأَقْتُلَهُ، فَنَادَانِي إِنْسَانٌ مِنْ جَوْفِ الْبَيْتِ: يَا عَبْدَ اللَّهِ، مَا تُرِيدُ أَنْ تَصْنَعَ؟ قَالَ: قُلْتُ: أُرِيدُ أَنْ أَقْتُلَ هَذَا الْكَلْبَ، فَقَالَتْ: إِنِّي امْرَأَةٌ مُضَيَّعَةٌ، وَإِنَّ هَذَا الْكَلْبَ يَطْرُدُ عَنِّي السَّبُعَ، وَيُؤْذِنُنِي بِالْجَائِي، فَائْتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاذْكُرْ ذَلِكَ لَهُ، قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَأَمَرَنِي بِقَتْلِهِ."],"takhrij":"صحيح: رواه أحمد (27188) عن أبي عامر (هو عبد الملك بن عمرو العقدي) ثنا يعقوب بن محمد بن طحلاء، حدثنا أبو الرجال، عن سالم بن عبد الله، عن أبي رافع قال: فذكره. ومن هذا الوجه رواه الطبراني في الكبير (927).","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الكلاب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (27188).","chapter_en":"What Has Been Narrated Concerning Killing Dogs","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":19,"content":{"translation":{"en":["Abū Rāfiʿ narrated: The Messenger of Allah ﷺ ordered me to kill dogs, so I went out killing them, and I did not see a dog except that I killed it. Then I came upon a dog circling around a house, and I went to kill it. Someone called out to me from inside the house: “O servant of Allah, what do you intend to do?” I replied: “I intend to kill this dog.” A woman said: “I am a helpless woman, and this dog drives wild beasts away from me and alerts me when someone comes.” I went to the Prophet ﷺ and mentioned that to him, but he ordered me to kill it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (27188)."},{"num":14851,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ:  كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَارٍ، وَقَدْ أُنْزِلَتْ عَلَيْهِ ﴿وَالْمُرْسَلاتِ عُرْفًا﴾، فَنَحْنُ نَأْخُذُهَا مِنْ فِيهِ رَطْبَةً، إِذْ خَرَجَتْ عَلَيْنَا حَيَّةٌ، فَقَالَ: اقْتُلُوهَا! فَابْتَدَرْنَاهَا، لِنَقْتُلَهَا، فَسَبَقَتْنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَقَاهَا اللهُ شَرَّكُمْ كَمَا وَقَاكُمْ شَرَّهَا."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4931)، ومسلم في السلام (2234) كلاهما من طريق الأعمش، عن إبراهيم، عن الأسود، عن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4931) and Muslim (2234).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: We were with the Prophet ﷺ in a cave, and the verse: “By those sent forth in succession…” had just been revealed to him, and we were receiving it fresh from his mouth. Then a snake came out toward us. The Prophet ﷺ said: “Kill it.” We rushed to kill it, but it escaped us. The Messenger of Allah ﷺ then said: “Allah protected it from your harm just as He protected you from its harm.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4931)، ومسلم (2234)."},{"num":14852,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ مُحْرِمًا بِقَتْلِ حَيَّةٍ بِمِنًى."],"takhrij":"صحيح: رواه مسلم في السلام (1235) عن أبي كريب، عن حفص بن غياث، عن الأعمش، عن إبراهيم، عن الأسود، عن عبد الله (هو ابن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1235).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: The Messenger of Allah ﷺ ordered a person in the state of iḥrām to kill a snake at Minā."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1235)."},{"num":14853,"demo":false,"sanad":"","matn":["عَنْ أَبِي السَّائِبِ، مَوْلَى هِشَامِ بْنِ زُهْرَةَ، أَنَّهُ قَالَ: دَخَلْتُ عَلَى أَبِي سَعِيدٍ الْخُدْرِيِّ، فَوَجَدْتُهُ يُصَلِّي، فَجَلَسْتُ أَنْتَظِرُهُ حَتَّى قَضَى صَلاَتَهُ، فَسَمِعْتُ تَحْرِيكًا تَحْتَ سَرِيرٍ فِي بَيْتِهِ، فَإِذَا حَيَّةٌ، فَقُمْتُ لأَقْتُلَهَا، فَأَشَارَ أَبُو سَعِيدٍ أَنِ اجْلِسْ، فَلَمَّا انْصَرَفَ، أَشَارَ إِلَى بَيْتٍ فِي الدَّارِ، فَقَالَ: أَتَرَى هَذَا الْبَيْتَ؟ فَقُلْتُ: نَعَمْ. قَالَ إِنَّهُ قَدْ كَانَ فِيهِ فَتًى حَدِيثُ عَهْدٍ بِعُرْسٍ، فَخَرَجَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْخَنْدَقِ، فَبَيْنَا هُوَ بِهِ، إِذْ أَتَاهُ الْفَتَى يَسْتَأْذِنُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، ائْذَنْ لِي أُحْدِثُ بِأَهْلِي عَهْدًا، فَأَذِنَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ: خُذْ عَلَيْكَ سِلاَحَكَ، فَإِنِّي أَخْشَى عَلَيْكَ بَنِي قُرَيْظَةَ فَانْطَلَقَ الْفَتَى إِلَى أَهْلِهِ، فَوَجَدَ امْرَأَتَهُ قَائِمَةً بَيْنَ الْبَابَيْنِ، فَأَهْوَى إِلَيْهَا بِالرُّمْحِ لِيَطْعُنَهَا، وَأَدْرَكَتْهُ غَيْرَةٌ، فَقَالَتْ: لاَ تَعْجَلْ حَتَّى تَدْخُلَ وَتَنْظُرَ مَا فِي بَيْتِكَ. فَدَخَلَ، فَإِذَا هُوَ بِحَيَّةٍ مُنْطَوِيَةٍ عَلَى فِرَاشِهِ، فَرَكَزَ فِيهَا رُمْحَهُ، ثُمَّ خَرَجَ بِهَا، فَنَصَبَهُ فِي الدَّارِ، فَاضْطَرَبَتِ الْحَيَّةُ فِي رَأْسِ الرُّمْحِ، وَخَرَّ الْفَتَى مَيِّتًا، فَمَا يُدْرَى أَيُّهُمَا كَانَ أَسْرَعَ مَوْتًا، الْفَتَى أَمِ الْحَيَّةُ؟ فَذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ بِالْمَدِينَةِ جِنًّا قَدْ أَسْلَمُوا، فَإِذَا رَأَيْتُمْ مِنْهُمْ شَيْئًا، فَآذِنُوهُ ثَلاَثَةَ أَيَّامٍ، فَإِنْ بَدَا لَكُمْ بَعْدَ ذَلِكَ، فَاقْتُلُوهُ، فَإِنَّمَا هُوَ شَيْطَانٌ.","وفي لفظ: إِنَّ لِهَذِهِ الْبُيُوتِ عَوَامِرَ، فَإِذَا رَأَيْتُمْ شَيْئًا مِنْهَا فَحَرِّجُوا عَلَيْهَا ثَلَاثًا، فَإِنْ ذَهَبَ، وَإِلَّا فَاقْتُلُوهُ، فَإِنَّهُ كَافِرٌ وَقَالَ لَهُمُ: اذْهَبُوا فَادْفِنُوا صَاحِبَكُمْ."],"takhrij":"صحيح: رواه مالك في الاستئذان (33) عن صيفي، مولى ابن أفلح، عن أبي السائب، مولى هشام بن زهرة، أنه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Istiʾdhān (33) and Muslim (2236:139).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Abū al-Sā’ib, the freedman of Hishām ibn Zuhrah, narrated: I entered upon Abū Saʿīd al-Khudrī and found him praying. I sat waiting until he finished his prayer. Then I heard something moving beneath a bed in his house and saw that it was a snake. I stood up to kill it, but Abū Saʿīd gestured to me to sit down. When he finished his prayer, he pointed to a house in the courtyard and said: “Do you see this house?” I replied: “Yes.” He said: There was once a young man living there who had only recently married. He went out with the Messenger of Allah ﷺ to the Trench. While he was there, the young man came to the Prophet ﷺ seeking permission and said: “O Messenger of Allah, permit me to go and see my family.” The Messenger of Allah ﷺ gave him permission and said: “Take your weapon with you, for I fear Banū Qurayẓah for you.” The young man went to his family and found his wife standing between the two doorposts. Jealousy overcame him, so he raised his spear to stab her. She said: “Do not be hasty. Enter and look at what is inside your house.” He entered and found a snake coiled upon his bed. He thrust his spear into it, then carried it outside and planted the spear upright in the courtyard. The snake writhed upon the spear, and the young man fell dead. It was not known which of the two died first—the young man or the snake. We mentioned this to the Messenger of Allah ﷺ, and he said: “There are jinn in Madinah who have accepted Islam. If you see any of them, warn them for three days. If they appear to you after that, then kill them, for it is only a devil.” In another wording: “These houses have inhabitants from among the jinn. If you see any of them, warn them for three days. If it leaves, then so be it; otherwise kill it, for it is an unbeliever.” And he said to them: “Go and bury your companion.”"]},"buhuth":{"en":["Muslim (2236:139) also narrated it through Ibn Wahb from Mālik with similar wording, except that it includes: “We came to the Messenger of Allah ﷺ, mentioned what had happened, and said, ‘Ask Allah to bring him back to life for us.’ He said, ‘Seek forgiveness for your companion,’ then said: ‘There are jinn in Madinah…’ to the end of the hadith.","Muslim (2236:140) also narrated it through Asmāʾ ibn ʿUbayd from a man called al-Sā’ib—identified there as Abū al-Sā’ib—relating the story with the second wording."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (33)، ومسلم (2236: 139)."},{"num":14854,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ:  أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ ذِي الطُّفْيَتَيْنِ، فَإِنَّهُ يَلْتَمِسُ الْبَصَرَ وَيُصِيبُ الْحَبَلَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3309)، ومسلم في السلام (2232) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3309) and Muslim (2232).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ ordered the killing of the snake with two stripes, for it attacks the eyesight and causes miscarriage."]},"buhuth":{"en":["The expression “the one with two stripes” refers to two white lines running along the back of the snake."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3309)، ومسلم (2232)."},{"num":14855,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ يَقُولُ: اقْتُلُوا الْحَيَّاتِ، وَاقْتُلُوا ذَا الطُّفْيَتَيْنِ وَالأَبْتَرَ، فَإِنَّهُمَا يَطْمِسَانِ الْبَصَرَ، وَيَسْتَسْقِطَانِ الْحَبَلَ.","قَالَ عَبْدُ اللَّهِ: فَبَيْنَا أَنَا أُطَارِدُ حَيَّةً لأَقْتُلَهَا، فَنَادَانِي أَبُو لُبَابَةَ: لاَ تَقْتُلْهَا، فَقُلْتُ: إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ أَمَرَ بِقَتْلِ الْحَيَّاتِ قَالَ: إِنَّهُ نَهَى بَعْدَ ذَلِكَ عَنْ ذَوَاتِ الْبُيُوتِ، وَهْىَ الْعَوَامِرُ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3297، 3298)، ومسلم في السلام (2233: 128) كلاهما من طريق الزهري، عن سالم، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3297, 3298) and Muslim (2233:128).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿUmar narrated that he heard the Prophet ﷺ delivering a sermon from the pulpit and saying: “Kill snakes, and kill the one with two stripes and the short-tailed snake, for the two of them cause blindness and cause pregnant women to miscarry.” ʿAbdullāh ibn ʿUmar said: While I was once chasing a snake in order to kill it, Abū Lubābah called out to me: “Do not kill it.” I replied: “The Messenger of Allah ﷺ ordered that snakes be killed.”","He said: “After that, he prohibited killing the snakes that live in houses, namely the resident snakes.”"]},"buhuth":{"en":["The word “al-abtar” means the short-tailed snake. It is described as a type of blue snake with a shortened tail, and the author states that when a pregnant woman sees it, she may miscarry."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3297، 3298)، ومسلم (2233: 128)."},{"num":14856,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ  أَنَّ أَبَا لُبَابَةَ كَلَّمَ ابْنَ عُمَرَ لِيَفْتَحَ لَهُ بَابًا فِي دَارِهِ، يَسْتَقْرِبُ بِهِ إِلَى الْمَسْجِدِ، فَوَجَدَ الْغِلْمَةُ جِلْدَ جَانٍّ، فَقَالَ عَبْدُ اللَّهِ: الْتَمِسُوهُ فَاقْتُلُوهُ! فَقَالَ أَبُو لُبَابَةَ: لَا تَقْتُلُوهُ؛ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَتْلِ الْجِنَّانِ الَّتِي فِي الْبُيُوتِ.","وفي رواية عنه: أَنَّ أَبَا لُبَابَةَ بْنَ عَبْدِ الْمُنْذِرِ الْأَنْصَارِيَّ، وَكَانَ مَسْكَنُهُ بِقُبَاءٍ فَانْتَقَلَ إِلَى الْمَدِينَةِ، فَبَيْنَمَا عَبْدُ اللَّهِ بْنُ عُمَرَ جَالِسًا مَعَهُ يَفْتَحُ خَوْخَةً لَهُ، إِذَا هُمْ بِحَيَّةٍ مِنْ عَوَامِرِ الْبُيُوتِ، فَأَرَادُوا قَتْلَهَا، فَقَالَ أَبُو لُبَابَةَ: إِنَّهُ قَدْ نُهِيَ عَنْهُنَّ يُرِيدُ عَوَامِرَ الْبُيُوتِ، وَأُمِرَ بِقَتْلِ الْأَبْتَرِ وَذِي الطُّفْيَتَيْنِ وَقِيلَ: هُمَا اللَّذَانِ يَلْتَمِعَانِ الْبَصَرَ، وَيَطْرَحَانِ أَوْلَادَ النساء.","وفي رواية عنه: كَانَ عَبْدُ اللهِ بْنُ عُمَرَ يَوْمًا عِنْدَ هَدْمٍ لَهُ، فَرَأَى وَبِيصَ جَانٍّ فَقَالَ: اتَّبِعُوا هَذَا الْجَانَّ فَاقْتُلُوهُ، قَالَ أَبُو لُبَابَةَ الْأَنْصَارِيُّ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم نَهَى عَنْ قَتْلِ الْجِنَّانِ الَّتِي تَكُونُ فِي الْبُيُوتِ، إِلَّا الْأَبْتَرَ وَذَا الطُّفْيَتَيْنِ، فَإِنَّهُمَا اللَّذَانِ يَخْطِفَانِ الْبَصَرَ، ويتتبعان مَا فِي بُطُونِ النِّسَاءِ."],"takhrij":"متفق عليه: رواه مسلم في السلام (2233: 131) من طرق عن الليث، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2233:131) and al-Bukhārī (3312–3313).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Nāfiʿ narrated: Abū Lubābah spoke to Ibn ʿUmar about opening a door in his house so that he could have a shorter route to the mosque. The young servants then found the shed skin of a snake. ʿAbdullāh ibn ʿUmar said: “Look for it and kill it.” Abū Lubābah said: “Do not kill it, for the Messenger of Allah ﷺ prohibited killing the snakes that live in houses.” In another narration: Abū Lubābah ibn ʿAbd al-Mundhir al-Anṣārī used to live in Qubāʾ and later moved to Madinah. While ʿAbdullāh ibn ʿUmar was sitting with him as a small doorway was being opened for him, they suddenly saw a snake from among the resident snakes of houses. They intended to kill it, but Abū Lubābah said: “Killing these has been prohibited,” meaning the resident snakes of houses. He added that the short-tailed snake and the one with two stripes had been ordered to be killed.","It was said that these are the two that cause the eyesight to flash or be harmed and cause women to miscarry.","In another narration: ʿAbdullāh ibn ʿUmar was one day near a building of his when he saw the gleam of a snake. He said: “Follow this snake and kill it.” Abū Lubābah al-Anṣārī said: “I heard the Messenger of Allah ﷺ prohibit killing snakes that live in houses, except the short-tailed snake and the one with two stripes, for these are the two that snatch away eyesight and cause the loss of what is in women’s wombs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2233: 131)، والبخاري (3312-3313)."},{"num":14857,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ، وَمَنْ تَرَكَ شَيْئًا مِنْهُنَّ خِيفَةً فَلَيْسَ مِنَّا."],"takhrij":"حسن: رواه أبو داود (5248)، وأحمد (9588، 10741)، والطحاوي في شرح المشكل (1338) كلهم من طرق عن محمد بن عجلان، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5248), Aḥmad (9588, 10741), and al-Ṭaḥāwī in Sharḥ al-Mushkil (1338).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said concerning snakes: “We have not made peace with them since we began fighting them. Whoever leaves any of them out of fear is not from us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5248)، وأحمد (9588، 10741)، والطحاوي في شرح المشكل (1338)."},{"num":14858,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَجْلَانَ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لِلْحَيَّاتِ: مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ، فَمَنْ تَرَكَهُنَّ خِيفَتَهُنَّ فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه الطحاوي في شرح المشكل (1339) عن بكار (هو ابن قتيبة)، قال: ثنا أبو داود (هو الطيالسي)، حدثنا زائدة بن قدامة، عن منصور، عن عبد الله بن مرة، عن مسروق، عن عبد الله بن مسعود فذكر مثل حديث أبي هريرة. أي لم يذكر الطحاوي لفظ حديث ابن مسعود، إنما أحال على لفظ حديث أبي هريرة الذي قبله. وهذا إسناد صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭaḥāwī in Sharḥ al-Mushkil (1339).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said concerning snakes: “We have not made peace with them since we began fighting them. Whoever leaves them because he fears them is not from us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطحاوي في شرح المشكل (1339)."},{"num":14859,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَرَكَ الْحَيَّاتِ مَخَافَةَ طَلَبِهِنَّ، فَلَيْسَ مِنَّا مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ."],"takhrij":"صحيح: رواه أبو داود (5250)، وأحمد (2037) كلاهما من حديث عبد الله بن نمير، حدثنا موسى بن مسلم، قال: سمعت عكرمة، يرفع الحديث فيما أرى إلى ابن عباس، قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في قتل الحيات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5250) and Aḥmad (2037).","chapter_en":"What Has Been Narrated Concerning Killing Snakes","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “Whoever leaves snakes because he fears pursuing them is not from us. We have not made peace with them since we began fighting them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5250)، وأحمد (2037)."},{"num":14860,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلاً يَتْبَعُ حَمَامَةً فَقَالَ: شَيْطَانٌ يَتْبَعُ شَيْطَانَةً."],"takhrij":"حسن: رواه أبو داود (4940)، وابن ماجه (3765)، وأحمد (8543)، وصحّحه ابن حبان (5874) كلهم من حديث حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن تتبع الحمامة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4940), Ibn Mājah (3765), Aḥmad (8543), and authenticated by Ibn Ḥibbān (5874).","chapter_en":"The Prohibition of Chasing after Pigeons","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في الرفق بالحيوانات","group_en":"Collection of What Has Been Narrated Concerning Kindness toward Animals","part_no":61,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated: The Prophet ﷺ saw a man chasing after a pigeon and said: “A devil chasing after a she-devil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4940)، وابن ماجه (3765)، وأحمد (8543)، وصححه ابن حبان (5874)."},{"num":14861,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا طِيَرَةَ وَخَيْرُهَا الْفَأْلُ قِيلَ: يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ؟ قَالَ: الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5754، 5755)، ومسلم في السلام (2223) كلاهما من طرق عن الزهري، قال: أخبرني عبيد الله بن عبدالله بن عتبة، أن أبا هريرة، قال: سمعت النبي صلى الله عليه وسلم يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5754, 5755) and Muslim (2223).","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Prophet ﷺ say: “There is no superstitious omen, and the best of it is a good sign.” He was asked: “O Messenger of Allah, what is a good sign?” He replied: “A good word that one of you hears.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5754، 5755)، ومسلم (2223)."},{"num":14862,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الطِّيَرَةُ مِنَ الشِّرْكِ. وَمَا مِنَّا إِلاَّ وَلَكِنَّ اللَّهَ يُذْهِبُهُ بِالتَّوَكُّلِ.","وفي لفظ: الطيرة شرك، الطيرة شرك ثلاثا."],"takhrij":"صحيح: رواه أبو داود (3910)، والترمذي (1614)، وابن ماجه (3538)، وأحمد (3687، 4171)، وصحّحه ابن حبان (6122)، والحاكم (1/17-18) كلهم من طرق عن سلمة بن كهيل، عن عيسى بن عاصم، عن زر، عن عبد الله بن مسعود قال: فذكره. واللفظ الثاني لأبي داود. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3910), al-Tirmidhī (1614), Ibn Mājah (3538), and Aḥmad (3687, 4171); authenticated by Ibn Ḥibbān (6122) and al-Ḥākim (1/17–18). The second wording is Abū Dāwūd’s, and its chain is authentic.","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Superstitious belief in omens is a form of shirk.” ʿAbdullāh ibn Masʿūd added: “There is none among us except that something of it may occur to him, but Allah removes it through reliance upon Him.” In another wording: “Superstitious omens are shirk. Superstitious omens are shirk.” He repeated it three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3910)، والترمذي (1614)، وابن ماجه (3538)، وأحمد (3687، 4171)، وصححه ابن حبان (6122)، والحاكم (1/17-18). واللفظ الثاني لأبي داود، وإسناده صحيح."},{"num":14863,"demo":false,"sanad":"","matn":["عَنْ أُمِّ كُرْزٍ أنها سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَقِرُّوا الطَّيْرَ مَكِنَاتِهَا."],"takhrij":"صحيح: رواه الطيالسي (1739)، والطبراني في الكبير (25/ح 404) كلاهما من طرق عن سفيان بن عيينة، عن عبيد الله بن أبي يزيد المكي، عن سباع بن ثابت، عن أم كرز الكعبية فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭayālisī (1739) and al-Ṭabarānī in al-Muʿjam al-Kabīr (25/167–168).","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Umm Kurz narrated that she heard the Prophet ﷺ say: “Leave the birds in their places.”"]},"buhuth":{"en":["It was also narrated by Abū Dāwūd (2835), Aḥmad (27139), Ibn Ḥibbān (6126), al-Ḥākim (4/237), and al-Bayhaqī (9/311) through routes from Sufyān, from ʿUbaydillāh ibn Abī Yazīd, from his father, from Sabāʿ bint Thābit, from Umm Kurz.","The mention of “his father” in that chain is an error, as Aḥmad and others stated. The chain is authentic, and Sabāʿ bint Thābit is regarded by most scholars as having Companionship.","Al-Baghawī said in Sharḥ al-Sunnah (11/266):","Regarding the words:","“Leave the birds in their makānāt.”","Abū Ziyād al-Kilābī said that the term makānāt is not normally used for birds; rather, wukanāt is used, meaning the places where birds make their nests.","Abū ʿUbayd said that makānāt refers to the eggs of desert lizards, the singular being makanah, and that the word was applied metaphorically to birds.","It has also been said that “upon their makānāt” means “in their places.”","Shamir said that it is the plural of makanah, meaning settledness or remaining firmly in place.","The scholars then differed regarding the intended meaning of leaving birds in their places.","Some said that it means disliking the hunting of birds at night.","Others said that it means prohibiting the practice of startling birds in order to seek omens from their flight; in other words, leave them in the places where Allah has placed them, recognizing that they themselves neither bring harm nor benefit.","It is related from al-Shāfiʿī that he interpreted the hadith as prohibiting the practice of driving birds into flight for omen-taking.","The Arabs were greatly attached to ʿiyāfah and seeking omens by startling birds.","When one of them left his home for a journey or some other need, he would look to see whether a bird was flying.","If he saw none, he would deliberately startle a bird from its place.","If it flew from his left to his right, he called it sāniḥ and regarded it as a favorable omen, so he continued with his affair.","If it flew from his right to his left, he called it bāriḥ, regarded it as a bad omen, and abandoned what he had intended to do.","The Prophet ﷺ therefore commanded them to leave birds in their places and not deliberately make them fly or startle them for the purpose of seeking omens."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطيالسي (1739)، والطبراني في الكبير (25/ح 404)."},{"num":14864,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ، قَالَ: أَتَيْتُ عَائِشَةَ، فَقُلْتُ: يَا أُمَّتَاهُ، حَدِّثِينِي شَيْئًا سَمِعْتِيهِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الطَّيْرُ تَجْرِي بِقَدَرٍ، وَكَانَ يُعْجِبُهُ الْفَأْلُ الْحَسَنُ."],"takhrij":"حسن: رواه أحمد (25982)، والبزّار - كشف الأستار (2161) كلاهما من حديث حسان بن إبراهيم، قال: حدّثنا سعيد بن مسروق، عن يوسف بن أبي بردة بن أبي موسى الأشعريّ، عن أبي بردة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (25982) and al-Bazzār, as cited in Kashf al-Astār (2161).","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Abū Burdah narrated: I came to ʿĀ’ishah and said: “O my mother, tell me something that you heard from the Messenger of Allah ﷺ.” She said: The Messenger of Allah ﷺ said: “The birds move according to divine decree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (25982)، والبزار - كشف الأستار (2161)."},{"num":14865,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَكْرَهُ الطِّيَرَةَ وَيُبْغِضُهَا."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (912) –واللفظ له، وأبو يعلى (2496- المطالب)، والطحاوي في شرح معاني الآثار (4/312) من طرق عن ابن أبي الزناد، علقمة بن أبي علقمة، عن أمه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (912), and this is his wording, and Abū Yaʿlā (2496, as cited in al-Maṭālib).","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ disliked superstitious omens and detested them.”"]},"buhuth":{"en":["At the beginning of al-Bukhārī’s narration there is a story:","Children would be brought to ʿĀ’ishah when they were born, and she would supplicate for blessing for them.","A child was brought to her, and when she went to place his pillow, she found a razor beneath his head.","She asked them about the razor, and they replied:","“We place it there as protection from the jinn.”","She took the razor, threw it away, and prohibited them from doing that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (912) - واللفظ له -، وأبو يعلى (2496 - المطالب)."},{"num":14866,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْجِبُهُ الْفَأْلُ الْحَسَنُ، وَيَكْرَهُ الطِّيَرَةَ."],"takhrij":"حسن: رواه ابن ماجه (3536)، وأحمد (8393)، وصحّحه ابن حبان (6121) كلهم من حديث محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الطيرة في الإسلام وهي الشؤم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3536), Aḥmad (8393), and authenticated by Ibn Ḥibbān (6121).","chapter_en":"What Has Been Narrated Concerning the Dislike of Superstitious Omens in Islam, Meaning Pessimistic Omens","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Prophet ﷺ liked a good omen and disliked superstitious pessimism.”"]},"buhuth":{"en":["The word al-ṭiyarah means pessimistic superstition or taking something as a bad omen.","Its origin lies in the customs of the people of the pre-Islamic period, who relied upon the movements of birds when deciding whether to proceed with something.","If one of them set out for some matter and saw a bird fly toward the right, he regarded it as a good omen and continued. If he saw it fly toward the left, he regarded it as a bad omen and turned back.","Sometimes a person would deliberately disturb a bird so that it would fly, and then base his decision upon the direction of its flight. Islamic law therefore prohibited this practice.","They called one type al-sāniḥ and the other al-bāriḥ.","The sāniḥ was a bird that passed from a person’s left to his right, and they regarded this as favorable.","The bāriḥ was the opposite: one that passed from his right to his left, and they regarded this as unfavorable.","See: Fatḥ al-Bārī (10/212–213).","The term taṭayyur later came to be used for every form of pessimistic superstition, whether connected to birds or to anything else.","Among the examples is the statement of Allah, the Exalted:","“Whenever good came to them, they said, ‘This is ours.’ But whenever something bad afflicted them, they attributed it as an evil omen to Mūsā and those with him. Surely, their fate is only with Allah, but most of them do not know.”","[Sūrat al-Aʿrāf 7:131]","And His statement:","“They said, ‘Indeed, we regard you as an evil omen. If you do not desist, we will surely stone you, and a painful punishment from us will surely touch you.’”","[Sūrat Yā-Sīn 36:18]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3536)، وأحمد (8393)، وصححه ابن حبان (6121)."},{"num":14867,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنْ كَانَ فَفِي الْفَرَسِ وَالْمَرْأَةِ وَالْمَسْكَنِ. يَعْنِي الشُّؤْمَ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (22) عن أبي حازم، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Istiʾdhān (22), al-Bukhārī (5095), and Muslim (2226).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī narrated that the Messenger of Allah ﷺ said: “If it were to be in anything, it would be in the horse, the woman, and the dwelling.” Meaning: misfortune or an evil omen."]},"buhuth":{"en":["The author explains that this also negates superstitious omens regarding the three things mentioned, and that the meaning is that there is no true superstitious omen even in these three."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (22)، والبخاري (5095)، ومسلم (2226)."},{"num":14868,"demo":false,"sanad":"","matn":["عَنْ جابر أَنَّهُ يُخْبِرُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنْ كَانَ فِي شَيْءٍ فَفِي الرَّبْعِ، وَالْخَادِمِ، وَالْفَرَسِ."],"takhrij":"صحيح: رواه مسلم في السلام (2227) عن إسحاق بن إبراهيم الحنظلي، أخبرنا عبد الله بن الحارث، عن ابن جريج، أخبرني أبو الزبير، أنه سمع جابرا يخبر فذكره.","grade":"صحيح","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2227).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated from the Messenger of Allah ﷺ that he said: “If it were to be in anything, it would be in the dwelling, the servant, and the horse.”"]},"buhuth":{"en":["The word “al-rabʿ” means a dwelling or a place of residence."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2227)."},{"num":14869,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: ذَكَرُوا الشُّؤْمَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ كَانَ الشُّؤْمُ فِي شَىْءٍ فَفِي الدَّارِ، وَالْمَرْأَةِ، وَالْفَرَسِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5094)، ومسلم في السلام (2225: 117) كلاهما من طريق عمر بن محمد بن زيد العسقلاني، عن أبيه، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5094) and Muslim (2225:117).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: Misfortune and evil omens were mentioned in the presence of the Prophet ﷺ, and he said: “If misfortune were to be in anything, it would be in the house, the woman, and the horse.”"]},"buhuth":{"en":["The author explains that this wording also negates the reality of superstitious misfortune, because it has already been authentically established that the Prophet ﷺ said:","“There is no superstitious omen.”","That is, there is no true superstition or inherent bad omen."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5094)، ومسلم (2225: 117)."},{"num":14870,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا عَدْوَى وَلَا طِيَرَةَ، إِنَّمَا الشُّؤْمُ فِي ثلاث: فِي الفرس، والمرأة، وَالدَّارِ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5772)، ومسلم في السلام (2225: 16) كلاهما من طريق ابن وهب، عن يونس، عن ابن شهاب، قال: أخبرني سالم بن عبد الله، وحمزة، أن عبد الله بن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5772) and Muslim (2225:16).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “There is no contagion and no superstitious omen. Misfortune is only in three things: the horse, the woman, and the house.”"]},"buhuth":{"en":["In this narration, misfortune appears to be affirmed regarding three things, whereas most narrations from Ibn ʿUmar use the wording:","“If misfortune were to be in anything…”","The scholars adopted two approaches regarding this.","The first is that the narrator transmitted the hadith according to its meaning and made an error in its wording, because the prohibition and negation of superstitious omens have been established in numerous authentic hadiths. The hadiths of ʿĀ’ishah and Saʿd ibn Abī Waqqāṣ also support this.","The second approach assumes the authenticity of this wording. According to this interpretation, if a person has a house in which he dislikes living, a wife whose companionship he dislikes, or a horse he dislikes keeping, he should separate himself from it: by moving from the house, divorcing the woman, or selling the horse, so that he does not fall into the prohibited belief in evil omens.","It has also been said that the “misfortune” of a house consists in its narrowness and having a bad neighbor; the “misfortune” of a woman is her inability to bear children; and the “misfortune” of a horse is that it is unsuitable for military expeditions. In such circumstances, it is preferable to part with it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5772)، ومسلم (2225: 16)."},{"num":14871,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: لاَ هَامَةَ وَلاَ عَدْوَى، وَلاَ طِيَرَةَ، وَإِنْ تَكُنِ الطِّيَرَةُ فِي شَىْءٍ فَفِي الْفَرَسِ، وَالْمَرْأَةِ، وَالدَّارِ."],"takhrij":"حسن: رواه أبو داود (3921)-واللفظ له-، وأحمد (1502)، وأبو يعلى (766)، وصحّحه ابن حبان (6127) كلهم من طريق يحيى بن أبي كثير، عن الحضرمي بن لاحق، عن سعيد بن المسيب، عن سعد بن مالك (أبي وقاص) فذكره.","grade":"حسن","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3921), and this is his wording, Aḥmad (1502), Abū Yaʿlā (766), and authenticated by Ibn Ḥibbān (6127).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Saʿd ibn Mālik narrated that the Messenger of Allah ﷺ used to say: “There is no hāmah, no contagion, and no superstitious omen. And if a superstitious omen were to exist in anything, it would be in the horse, the woman, and the house.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3921) - واللفظ له -، وأحمد (1502)، وأبو يعلى (766)، وصححه ابن حبان (6127)."},{"num":14872,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا طِيَرَةَ، وَالطِّيَرَةُ عَلَى مَنْ تَطَيَّرَ، وَإِنْ تَكُ فِي شَيْءٍ فَفِي الدَّارِ وَالْفَرَسِ وَالْمَرْأَةِ."],"takhrij":"حسن: رواه الطحاوي في شرح المعاني (4/314)، وصحّحه ابن حبان (6123)، والضياء في المختارة (2269) كلهم من طرق عن مالك بن إسماعيل، قال: حدثنا زهير بن معاوية، عن عتبة بن حميد، قال: حدثني عبيد الله بن أبى بكر أنه سمع عن أنس بن مالك يقول: فذكره.","grade":"حسن","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (4/314), authenticated by Ibn Ḥibbān (6123), and al-Ḍiyāʾ in al-Mukhtārah (2269).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “There is no superstitious omen, and its effect is upon the one who believes in it. If it were to be in anything, it would be in the house, the horse, and the woman.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في شرح المعاني (4/314)، وصححه ابن حبان (6123)، والضياء في المختارة (2269)."},{"num":14873,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَسَّانَ، قَالَ: دَخَلَ رَجُلَانِ مِنْ بَنِي عَامِرٍ عَلَى عَائِشَةَ فَأَخْبَرَاهَا أَنَّ أَبَا هُرَيْرَةَ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: الطِّيَرَةُ فِي الدَّارِ، وَالْمَرْأَةِ، وَالْفَرَسِ، فَغَضِبَتْ فَطَارَتْ شِقَّةٌ مِنْهَا فِي السَّمَاءِ، وَشِقَّةٌ فِي الْأَرْضِ، وَقَالَتْ: وَالَّذِي أَنْزَلَ الْفُرْقَانَ عَلَى مُحَمَّدٍ مَا قَالَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطُّ، إِنَّمَا قَالَ: كَانَ أَهْلُ الْجَاهِلِيَّةِ يَتَطَيَّرُونَ مِنْ ذَلِكَ.","وَفِي رِوَايَةِ: ثُمَّ قَرَأَتْ عائشة ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ﴾ [سورة الْحَدِيدِ: ٢٢]."],"takhrij":"حسن: رواه أحمد (26034، 26088)، والحاكم (2/479) مختصرا، وعنه البيهقي (8/140) من طريق قتادة، عن أبي حسان الأعرج فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب إن كانت الطيرة (الشؤم) ففي ثلاث","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26034, 26088) and al-Ḥākim (2/479).","chapter_en":"If There Were to Be an Evil Omen, It Would Be in Three Things","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Abū Ḥassān narrated: Two men from Banū ʿĀmir entered upon ʿĀ’ishah and informed her that Abū Hurayrah narrated from the Prophet ﷺ that he had said: “Superstitious misfortune is in the house, the woman, and the horse.” She became intensely angry and said: “By the One who revealed the Criterion to Muḥammad, the Messenger of Allah ﷺ never said that. Rather, he said: ‘The people of the pre-Islamic period used to regard these things as evil omens.’” In another narration, ʿĀ’ishah then recited: “No calamity occurs on earth or within yourselves except that it is written in a Book.” [Sūrat al-Ḥadīd 57:22]"]},"buhuth":{"en":["Despite the goodness of its chain, the author explains this by saying that Abū Hurayrah may not have preserved the beginning of the statement.","The Prophet ﷺ was speaking about the people of the pre-Islamic period and how they used to regard the house, the woman, and the horse as sources of bad omens. Abū Hurayrah may have heard the latter portion of the statement without hearing its beginning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26034، 26088)، والحاكم (2/479)."},{"num":14874,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى بْنِ سَعِيدٍ، أَنَّهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، دَارٌ سَكَنَّاهَا، وَالْعَدَدُ كَثِيرٌ، وَالْمَالُ وَافِرٌ، فَقَلَّ الْعَدَدُ، وَذَهَبَ الْمَالُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعُوهَا ذَمِيمَةً."],"takhrij":"حسن: رواه مالك في الا ستئذان (23) عن يحيى بن سعيد الأنصاري فذكره.","grade":"حسن","chapter_ar":"باب من سكن دارًا فتكدر عيشه فعليه أن ينتقل منها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Good due to supporting narrations: Mālik narrated it in al-Istiʾdhān (23) as a mursal report. A connected report with similar meaning from Anas was narrated by Abū Dāwūd (3924), al-Bukhārī in al-Adab al-Mufrad (918), al-Bayhaqī (8/140), and al-Ḍiyāʾ in al-Mukhtārah (1529).","chapter_en":"Whoever Lives in a House and Finds His Life Disturbed There Should Move Away from It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":3,"content":{"translation":{"en":["Yaḥyā ibn Saʿīd narrated: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we lived in a house while our numbers were many and our wealth was abundant. Then our numbers decreased and our wealth disappeared.” The Messenger of Allah ﷺ said: “Leave it while considering it blameworthy.”"]},"buhuth":{"en":["Al-Bukhārī said after the Anas route: “Its chain is open to question.” In summary, Yaḥyā ibn Saʿīd’s mursal report is strengthened by the mursal report of ʿAbdullāh ibn Shaddād because their routes are independent.","Al-Khaṭṭābī said:","“It is possible that he only ordered them to leave it and move away in order to eliminate the thought that had entered their minds that the misfortune which afflicted them was caused by the house itself and by living in it. Once they moved away, the source of that delusion would be cut off and the doubt that had entered their hearts concerning it would disappear. And Allah knows best.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (23) مرسلا. وروي نحوه عن أنس موصولا عند أبي داود (3924)، والبخاري في الأدب المفرد (918)، والبيهقي (8/140)، والضياء في المختارة (1529)."},{"num":14875,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَدَّتْهُ الطِّيَرَةُ مِنْ حَاجَةٍ، فَقَدْ أَشْرَكَ، قَالُوا: يَا رَسُولَ اللَّهِ، مَا كَفَّارَةُ ذَلِكَ؟ قَالَ: أَنْ يَقُولَ أَحَدُهُمْ: اللهُمَّ لَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا طَيْرَ إِلَّا طَيْرُكَ، وَلَا إِلَهَ غَيْرُكَ."],"takhrij":"حسن: رواه أحمد (7045) عن حسن، حدثنا ابن لهيعة، أخبرنا ابن هبيرة، عن أبي عبدالرحمن الحبلي، عن عبد الله بن عمرو قال: فذكره.","grade":"حسن","chapter_ar":"باب كفارة من قال بالطيرة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7045) and ʿAbdullāh ibn Wahb in his Jāmiʿ (658).","chapter_en":"The Expiation for One Who Acts upon a Superstitious Omen","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Whoever is turned back from fulfilling a need because of a superstitious omen has committed shirk.” They asked: “O Messenger of Allah, what is the expiation for that?” He replied: “That one of them should say: ‘O Allah, there is no good except Your good, there is no omen except what You decree, and there is no deity besides You.’”"]},"buhuth":{"en":["Ibn Lahīʿah is well known to have been criticized, but ʿAbdullāh ibn Wahb narrated this report in his Jāmiʿ through three chains; one of them is no. 658 from Ibn Lahīʿah. Ibn Wahb did not reproduce the full wording there, but referred to the following wording of Faḍālah ibn ʿUbayd.","Ibn al-Sunnī narrated the complete wording through this route in ʿAmal al-Yawm wa-al-Laylah (292). Ibn Wahb was among those who heard from Ibn Lahīʿah before his books were burned; for that reason, scholars graded the chain as good in the narrations of the ʿAbādilah from him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11279],"tks":"حسن: رواه أحمد (7045)، وعبد الله بن وهب في جامعه (658)."},{"num":14876,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ الأَنْصَارِيِّ صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مِنْ رِدَّتِهِ الطِّيَرَةِ فَقَدْ قَارَفَ الشِّرْكَ."],"takhrij":"حسن: رواه ابن وهب في جامعه (656) عن ابن لهيعة، عن عياش بن عباس، عن أبي الحصين، عن فضالة بن عبيد فذكره موقوفا.","grade":"حسن","chapter_ar":"باب كفارة من قال بالطيرة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Wahb in his Jāmiʿ (656) as a mawqūf report from Faḍālah ibn ʿUbayd.","chapter_en":"The Expiation for One Who Acts upon a Superstitious Omen","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في العدوى والطيرة","group_en":"Collection of What Has Been Narrated Concerning Contagion and Superstitious Omens","part_no":61,"group_no":18,"chapter_no":4,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd al-Anṣārī, a Companion of the Prophet ﷺ, said: “Whoever is turned back by a superstitious omen has fallen into shirk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن وهب في جامعه (656) موقوفا على فضالة بن عبيد."},{"num":14877,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَيُّمَا رَجُلٍ قَالَ لأَخِيهِ: يَا كَافِرُ، فَقَدْ بَاءَ بِهَا أَحَدُهُمَا."],"takhrij":"متفق عليه: رواه مالك في الكلام، والغيبة والتُّقى (1) عن عبد الله بن دينار، عن عبد الله بن عمر فذكره. ومن طريقه رواه البخاري في الأدب (6104).","grade":"متفق عليه","chapter_ar":"باب التحذير من قول أخيه: يا كافر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Kalām wa-al-Ghībah wa-al-Tuqā (1) and al-Bukhārī (6104).","chapter_en":"Warning against Saying to One’s Brother: “O Disbeliever”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Whenever a man says to his brother, ‘O disbeliever,’ that charge returns upon one of the two.”"]},"buhuth":{"en":["Muslim also narrated it in al-Īmān (60) through another route with the wording:","“Whenever a man says to his brother, ‘O disbeliever,’ that charge returns upon one of them. If the person is as he said, then it applies to him; otherwise, it returns upon the one who said it.”","Likewise, no one should say to a Muslim whose father died as a disbeliever and had been hostile toward Islam and the Muslims:","“This is the son of an enemy of Allah,”","as indicated in the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (6104)."},{"num":14878,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ زَيْدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُؤْذُوا مُسْلِمًا بِشَتْمِ كَافِرٍ."],"takhrij":"حسن: رواه الحاكم (1420) –وعنه البيهقي في الشعب (6253)- عن علي بن أحمد بن قرقوب التمار، حدثنا إبراهيم بن الحسين (هو ابن ديزيل)، حدثنا أبو اليمان (هو الحكم بن نافع البهراني)، أخبرني شعيب بن أبي حمزة، عن عبدالله بن عبدالرحمن بن أبي حسين، حدثني نوفل بن مساحق، عن سعيد بن زيد قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من قول أخيه: يا كافر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (1420), and through him by al-Bayhaqī in Shuʿab al-Īmān (6253).","chapter_en":"Warning against Saying to One’s Brother: “O Disbeliever”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":1,"content":{"translation":{"en":["Saʿīd ibn Zayd narrated that the Messenger of Allah ﷺ said: “Do not hurt a Muslim by insulting a disbeliever.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (1420)، وعنه البيهقي في الشعب (6253)."},{"num":14879,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ يَرْمِي رَجُلٌ رَجُلاً بِالْفُسُوقِ، وَلاَ يَرْمِيهِ بِالْكُفْرِ، إِلاَّ ارْتَدَّتْ عَلَيْهِ، إِنْ لَمْ يَكُنْ صَاحِبُهُ كَذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6045)، ومسلم في الإيمان (61) كلاهما من طريق عبد الوارث، عن الحسين، عن عبد الله بن بريدة، حدثني يحيى بن يعمر، أن أبا الأسود الديلي، حدثه عن أبي ذر فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب التحذير من قول أخيه: يا كافر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6045) and Muslim (61). The wording is that of al-Bukhārī.","chapter_en":"Warning against Saying to One’s Brother: “O Disbeliever”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr narrated that he heard the Prophet ﷺ say: “No man accuses another man of wickedness or accuses him of disbelief except that the accusation returns upon him if the person accused is not actually like that.”"]},"buhuth":{"en":["Muslim’s wording is:","“No man knowingly claims descent from someone other than his father except that he has committed an act of disbelief. Whoever claims something that does not belong to him is not from us, and let him take his seat in the Fire. And whoever calls a man a disbeliever, or says, ‘Enemy of Allah,’ when he is not so, the statement returns upon him.”","The Grand Mufti of the Kingdom of Saudi Arabia, Chairman of the Council of Senior Scholars and the Department of Scholarly Research and Fatwa, Shaykh ʿAbd al-ʿAzīz ibn ʿAbdullāh ibn Muḥammad Āl al-Shaykh, said:","“The people of extremism and excess have innovated a methodology of takfīr that makes the killing of Muslims and other protected persons appear insignificant. From this takfīr-based methodology, founded upon doubts and false interpretations, there arose the unlawful shedding of blood, violation of people’s honor, seizure of private and public wealth, bombing of homes and vehicles, and destruction of facilities.","Takfīr is a religious ruling whose judgment belongs to Allah and His Messenger ﷺ. Just as declaring something lawful, unlawful, or obligatory belongs to Allah and His Messenger, so too does takfīr. Not every statement or action that is described as kufr necessarily constitutes major kufr that expels a person from the religion.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[199],"tks":"متفق عليه: رواه البخاري (6045)، ومسلم (61)، واللفظ للبخاري."},{"num":14880,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَيْسَ أَحَدٌ أَحَبَّ إِلَيْهِ الْمَدْحُ مِنَ اللَّهِ، مِنْ أَجْلِ ذَلِكَ مَدَحَ نَفْسَهُ، وَلَيْسَ أَحَدٌ أَغْيَرَ مِنَ اللَّهِ، مِنْ أَجْلِ ذَلِكَ حَرَّمَ الْفَوَاحِشَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5520)، ومسلم في التوبة (2760: 32) كلاهما من حديث الأعمش، عن أبي وائل، عن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب اجتناب الفواحش","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5520) and Muslim (2760:32).","chapter_en":"Avoiding Obscenities and Shameful Deeds","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “There is no one who loves praise more than Allah; for that reason He praised Himself. And there is no one more protective of sacred honor than Allah; for that reason He prohibited obscenities and shameful deeds.”"]},"buhuth":{"en":["Muslim (2760:35) also narrated it through another route and added at the end:","“And there is no one who loves to establish an excuse more than Allah; for that reason He revealed the Book and sent the Messengers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5520)، ومسلم (2760: 32)."},{"num":14881,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ اللَّهَ يَغَارُ، وَإِنَّ الْمُؤْمِنَ يَغَارُ، وَغَيْرَةُ اللهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5223)، ومسلم في التوبة (2761) كلاهما من حديث يحيى قال: حدثني أبو سلمة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب اجتناب الفواحش","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5223) and Muslim (2761).","chapter_en":"Avoiding Obscenities and Shameful Deeds","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Indeed, Allah has protective jealousy, and the believer has protective jealousy. Allah’s protective jealousy is aroused when a believer commits what He has forbidden him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12324],"tks":"متفق عليه: رواه البخاري (5223)، ومسلم (2761)."},{"num":14882,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: آيَةُ الْمُنَافِقِ ثَلاَثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6095)، ومسلم في الإيمان (59: 107) كلاهما من طريق إسماعيل بن جعفر، قال: حدثنا نافع بن مالك بن أبي عامر أبو سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ذم الكذب والتحذير منه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6095) and Muslim (59:107).","chapter_en":"Condemning Lying and Warning against It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The signs of a hypocrite are three: when he speaks, he lies; when he promises, he breaks his promise; and when he is entrusted, he betrays the trust.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6095)، ومسلم (59: 107)."},{"num":14883,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ رَجُلَيْنِ أَتَيَانِي، قَالاَ: الَّذِي رَأَيْتَهُ يُشَقُّ شِدْقُهُ فَكَذَّابٌ، يَكْذِبُ بِالْكَذْبَةِ تُحْمَلُ عَنْهُ حَتَّى تَبْلُغَ الآفَاقَ، فَيُصْنَعُ بِهِ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأدب (6096) عن موسى بن إسماعيل، حدثنا جرير، حدثنا أبو رجاء، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب ذم الكذب والتحذير منه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6096).","chapter_en":"Condemning Lying and Warning against It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “Last night I saw two men who came to me. They said: ‘The man you saw whose side of the mouth was being torn open is a liar. He tells a lie that is carried from him until it reaches the horizons, and this will continue to be done to him until the Day of Resurrection.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6096)."},{"num":14884,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الله بن مسعود قَالَ قَالَ رَسُولُ الله: إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا، وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6094)، ومسلم في البر والصلة (2607) كلاهما عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن أبي وائل، عن عبد الله بن مسعود قال: فذكره. ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ذم الكذب والتحذير منه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6094) and Muslim (2607).","chapter_en":"Condemning Lying and Warning against It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Truthfulness leads to righteousness, and righteousness leads to Paradise. A man continues to speak the truth until he is recorded with Allah as a person of utmost truthfulness. Lying leads to wickedness, and wickedness leads to the Fire. A man continues to lie until he is recorded with Allah as a persistent liar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6094)، ومسلم (2607)."},{"num":14885,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: مَا كَانَ خُلُقٌ أَبْغَضَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْكَذِبِ، وَلَقَدْ كَانَ الرَّجُلُ يَكْذِبُ عِنْدَهُ الْكذْبَةَ، فَمَا تَزَالُ فِي نَفْسِهِ عَلَيْهِ، حَتَّى يَعْلَمَ أَنَّهُ قَدْ أَحْدَثَ مِنْهَا تَوْبَةً."],"takhrij":"صحيح: رواه ابن حبان (5736) من طريق محمد عبد الملك بن زنجويه-، والبيهقي في الكبرى (20821) من طريق أحمد بن منصور الرمادي- كلاهما (محمد بن عبدالملك، وأحمد بن منصور) عن عبد الرزاق، أخبرنا معمر، عن أيوب، عن ابن أبي مليكة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ذم الكذب والتحذير منه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (5736) and al-Bayhaqī in al-Sunan al-Kubrā (10/196).","chapter_en":"Condemning Lying and Warning against It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah narrated: “There was no character trait more hated by the Messenger of Allah ﷺ than lying. A man might tell a lie in his presence, and it would remain in the Prophet’s mind concerning him until he knew that the man had repented from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (5736)، والبيهقي في الكبرى (20821)."},{"num":14886,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَجْتَمِعُ الْإِيمَانُ وَالْكُفْرُ فِي قَلْبِ امْرِئٍ، وَلَا يَجْتَمِعُ الصِّدْقُ وَالْكَذِبُ جَمِيعًا، وَلَا تَجْتَمِعُ الْخِيَانَةُ وَالْأَمَانَةُ جَمِيعًا."],"takhrij":"حسن: رواه ابنُ وهب في الجامع (464) عن ابن لهيعة، عن أبي الأسود، عن عبدالله بن رافع، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ذم الكذب والتحذير منه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Wahb in al-Jāmiʿ (464) and Imām Aḥmad (8593).","chapter_en":"Condemning Lying and Warning against It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Faith and disbelief do not come together in the heart of a person; truthfulness and lying do not come together completely; and betrayal and trustworthiness do not come together completely.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن وهب في الجامع (464)، والإمام أحمد (8593)."},{"num":14887,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَامِرٍ، أَنَّهُ قَالَ: دَعَتْنِي أُمِّي يَوْمًا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ فِي بَيْتِنَا، فَقَالَتْ: هَا تَعَالَ أُعْطِيكَ. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَمَا أَرَدْتِ أَنْ تُعْطِيهِ. قَالَتْ: أُعْطِيهِ تَمْرًا. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّكِ لَوْ لَمْ تُعْطِيهِ شَيْئًا كُتِبَتْ عَلَيْكِ كِذْبَةٌ."],"takhrij":"حسن: رواه أبو داود (4991)، وأحمد (15702) كلاهما من حديث الليث بن سعد، عن ابن عجلان، أن رجلا من موالي عبد الله بن عامر بن ربيعة العدوي حدثه عن عبد الله بن عامر، أنه قال: فذكره.","grade":"حسن","chapter_ar":"باب من قال لصبي: تعال هاك ثم لم يعطه فهي كذبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4991) and Aḥmad (15702).","chapter_en":"If Someone Says to a Child, “Come, Take This,” Then Gives Him Nothing, It Is a Lie","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿĀmir narrated: One day my mother called me while the Messenger of Allah ﷺ was sitting in our house. She said: “Come here, I will give you something.” The Messenger of Allah ﷺ asked her: “What did you intend to give him?” She replied: “I intended to give him some dates.” The Messenger of Allah ﷺ said: “If you had not given him anything, a lie would have been recorded against you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4991)، وأحمد (15702)."},{"num":14888,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَيْلٌ لِلَّذِي يُحَدِّثُ الْقَوْمَ، ثُمَّ يَكْذِبُ لِيُضْحِكَهُمْ وَيْلٌ لَهُ. وَوَيْلٌ لَهُ."],"takhrij":"حسن: رواه أبو داود (4990)، والترمذي (2315) وأحمد (20021)، والحاكم (142)، والبيهقي في الآداب (374) كلهم من حديث بهز بن حكيم، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب من يضحك القوم بكذباته","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4990), al-Tirmidhī (2315), Aḥmad (20021), and al-Ḥākim (142).","chapter_en":"The One Who Makes People Laugh with His Lies","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":5,"content":{"translation":{"en":["Bahz ibn Ḥakīm narrated from his father, from his grandfather: I heard the Messenger of Allah ﷺ say: “Woe to the one who speaks to people and lies in order to make them laugh. Woe to him! Woe to him!”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4990)، والترمذي (2315)، وأحمد (20021)، والحاكم (142)."},{"num":14889,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ يُضْحِكُ بِهَا جُلَسَاءَهُ، يَهْوِي بِهَا مِنْ أَبْعَدِ مِنَ الثُّرَيَّا."],"takhrij":"حسن: رواه عبد الله بن المبارك في الزهد (948) -ومن طريقه الإمام أحمد (9220)، وابن حبان (5716)- عن الزبير بن سعيد، عن صفوان بن سليم، عن عطاء بن يسار، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب من يضحك القوم بكذباته","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullāh ibn al-Mubārak in al-Zuhd (948), and through him by Aḥmad (9220), and by Ibn Ḥibbān (5716).","chapter_en":"The One Who Makes People Laugh with His Lies","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A man may utter a word merely to make those sitting with him laugh, and because of it he falls farther than the distance of al-Thurayyā.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الله بن المبارك في الزهد (948)، ومن طريقه أحمد (9220)، وابن حبان (5716)."},{"num":14890,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ يَقُولُ اشْتَكَى ابْنٌ لأَبِي طَلْحَةَ، ـ قَالَ: ـ فَمَاتَ، وَأَبُو طَلْحَةَ خَارِجٌ، فَلَمَّا رَأَتِ امْرَأَتُهُ أَنَّهُ قَدْ مَاتَ هَيَّأَتْ شَيْئًا، وَنَحَّتْهُ فِي جَانِبِ الْبَيْتِ، فَلَمَّا جَاءَ أَبُو طَلْحَةَ قَالَ: كَيْفَ الْغُلاَمُ، قَالَتْ: قَدْ هَدَأَتْ نَفْسُهُ، وَأَرْجُو أَنْ يَكُونَ قَدِ اسْتَرَاحَ. وَظَنَّ أَبُو طَلْحَةَ أَنَّهَا صَادِقَةٌ، قَالَ: فَبَاتَ، فَلَمَّا أَصْبَحَ اغْتَسَلَ، فَلَمَّا أَرَادَ أَنْ يَخْرُجَ، أَعْلَمَتْهُ أَنَّهُ قَدْ مَاتَ، فَصَلَّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ أَخْبَرَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا كَانَ مِنْهُمَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَعَلَّ اللَّهَ أَنْ يُبَارِكَ لَكُمَا فِي لَيْلَتِكُمَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1301) عن بشر بن الحكم، حدثنا سفيان بن عيينة، أخبرنا إسحاق بن عبد الله بن أبي طلحة، أنه سمع أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب المعاريض مندوحة عن الكذب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1301) and Muslim (2144, following Hadith 2457).","chapter_en":"Indirect Expressions Provide a Way to Avoid Lying","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated: A son of Abū Ṭalḥah became ill and then died while Abū Ṭalḥah was away. When his wife saw that the child had died, she prepared him and placed him to one side of the house. When Abū Ṭalḥah returned, he asked: “How is the boy?” She replied: “His soul has become calm, and I hope that he has found rest.” Abū Ṭalḥah thought she meant that the boy had recovered and was resting. He spent the night with her. When morning came, he performed ghusl. As he was preparing to leave, she informed him that the child had died. He prayed with the Prophet ﷺ and then informed him of what had happened between the two of them. The Messenger of Allah ﷺ said: “Perhaps Allah will bless the two of you in your night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1301)، ومسلم (2144 عقب الحديث 2457)."},{"num":14891,"demo":false,"sanad":"","matn":["عَنْ أُمِّ كُلْثُومٍ بنت عقبة: أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ، فَيَنْمِي خَيْرًا، أَوْ يَقُولُ خَيْرًا.","زاد مسلم: قَالَ ابْنُ شِهَابٍ: وَلَمْ أَسْمَعْ يُرَخَّصُ فِي شَيْءٍ مِمَّا يَقُولُ النَّاسُ كَذِبٌ إِلَّا فِي ثَلَاثٍ: الْحَرْبُ، وَالْإِصْلَاحُ بَيْنَ النَّاسِ، وَحَدِيثُ الرَّجُلِ امْرَأَتَهُ وَحَدِيثُ الْمَرْأَةِ زَوْجَهَا."],"takhrij":"متفق عليه: رواه البخاري في الصلح (2692)، ومسلم في البر والصلة (2605) كلاهما من طرق أن حميد بن عبد الرحمن أخبره، أن أمه أم كلثوم بنت عقبة أخبرته فذكرته. والزيادة لمسلم.","grade":"متفق عليه","chapter_ar":"باب ليس الكذاب الذي يصلح بين الناس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2692) and Muslim (2605).","chapter_en":"The One Who Reconciles between People Is Not Considered a Liar","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":7,"content":{"translation":{"en":["Umm Kulthūm bint ʿUqbah narrated that she heard the Messenger of Allah ﷺ say: “The person who reconciles between people is not a liar when he conveys something good or says something good.” Muslim adds: Ibn Shihāb said: “I did not hear permission being granted regarding anything that people call lying except in three matters: war, reconciliation between people, and what a man says to his wife and what a woman says to her husband.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2692)، ومسلم (2605)."},{"num":14892,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْغَضَ رجال إِلَى اللَّهِ: الأَلَدُّ الْخَصِمُ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2457)، ومسلم في العلم (2668) كلاهما من طريق ابن جريج، عن ابن أبي مليكة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم الخصومة بالباطل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2457) and Muslim (2668).","chapter_en":"The Prohibition of Arguing Falsely","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":8,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “The most hated of men to Allah is the fiercely quarrelsome opponent.”"]},"buhuth":{"en":["The word “al-aladd” means one who is severe and persistent in disputation.","The word “al-khaṣim” means one who is skillful in arguing.","The meaning of the hadith is that arguing falsely in order to repel the truth or establish falsehood is prohibited."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2457)، ومسلم (2668)."},{"num":14893,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ وَالْجَهْلَ، فَلَيْسَ لِلَّهِ حَاجَةٌ أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ."],"takhrij":"صحيح: رواه البخاري في الأدب (6057) عن أحمد بن يونس، حدثنا ابن أبي ذئب، عن المقبري، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الاجتناب من قول الزور","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6057).","chapter_en":"Avoiding False Speech","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever does not give up false speech, acting upon it, and ignorant behavior, then Allah has no need for him to give up his food and drink.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَاجْتَنِبُوا قَوْلَ الزُّورِ﴾ [سورة الحج: ٣٠]."],"en":["Allah, the Exalted, says:","“And avoid false speech.”","[Sūrat al-Ḥajj 22:30]"]}},"tuhfa":{},"full":1,"rep":[12796],"tks":"صحيح: رواه البخاري (6057)."},{"num":14894,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا رَوَى عَنِ اللَّهِ تَبَارَكَ وَتَعَالَى أَنَّهُ قَالَ:  يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا، فَلَا تَظَالَمُوا، يَا عِبَادِي كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ، فَاسْتَهْدُونِي أَهْدِكُمْ، يَا عِبَادِي كُلُّكُمْ جَائِعٌ، إِلَّا مَنْ أَطْعَمْتُهُ، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ، يَا عِبَادِي كُلُّكُمْ عَارٍ، إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ، يَا عِبَادِي إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ، يَا عِبَادِي إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي، فَتَنْفَعُونِي، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي فَأَعْطَيْتُ كُلَّ إِنْسَانٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ، يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا، فَلْيَحْمَدِ اللهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ، فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ.","قَالَ سَعِيدٌ: كَانَ أَبُو إِدْرِيسَ الْخَوْلَانِيُّ، إِذَا حَدَّثَ بِهَذَا الْحَدِيثِ، جَثَا عَلَى رُكْبَتَيْهِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2577: 55) عن عبد الله بن عبد الرحمن بن بهرام الدارمي، حدثنا مروان يعني ابن محمد الدمشقي، حدثنا سعيد بن عبدالعزيز، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الظلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2577:55).","chapter_en":"The Prohibition of Injustice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":10,"content":{"translation":{"en":["Abū Dharr narrated from the Prophet ﷺ, who related from Allah, Blessed and Exalted, that He said: “O My servants, I have forbidden injustice for Myself and have made it forbidden among you, so do not wrong one another. O My servants, all of you are astray except those whom I guide, so seek guidance from Me and I will guide you. O My servants, all of you are hungry except those whom I feed, so ask Me for food and I will feed you. O My servants, all of you are unclothed except those whom I clothe, so ask Me for clothing and I will clothe you. O My servants, you commit sins by night and by day, and I forgive all sins, so seek My forgiveness and I will forgive you. O My servants, you can never reach a level where you could harm Me, nor can you reach a level where you could benefit Me. O My servants, if the first of you and the last of you, your humans and your jinn, were all upon the most God-fearing heart of any one man among you, that would not increase My kingdom in the slightest. O My servants, if the first of you and the last of you, your humans and your jinn, were all upon the most wicked heart of any one man, that would not decrease My kingdom in the slightest. O My servants, if the first of you and the last of you, your humans and your jinn, were all to stand together on one plain and ask Me, and I were to give every person what he asked for, that would not diminish what I possess except as much as a needle diminishes the sea when it is dipped into it. O My servants, these are only your deeds. I enumerate them for you and then repay you for them in full. So whoever finds good, let him praise Allah; and whoever finds otherwise, let him blame no one but himself.”","Saʿīd said: “Whenever Abū Idrīs al-Khawlānī narrated this hadith, he would fall upon his knees.”"]}},"tuhfa":{},"full":1,"rep":[5907],"tks":"صحيح: رواه مسلم (2577: 55)."},{"num":14895,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  اتَّقُوا الظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ، فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ، حَمَلَهُمْ عَلَى أَنْ سَفَكُوا دِمَاءَهُمْ، وَاسْتَحَلُّوا مَحَارِمَهُمْ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2578: 56) عن عبدالله بن مسلمة بن قعنب، حدثنا داود يعني ابن قيس، عن عبيدالله بن مقسم، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الظلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2578:56).","chapter_en":"The Prohibition of Injustice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be layers of darkness on the Day of Resurrection. And beware of greed, for greed destroyed those who came before you. It drove them to shed one another’s blood and to treat what was sacred among them as lawful.”"]}},"tuhfa":{},"full":1,"rep":[5909,12734,13524,14991],"tks":"صحيح: رواه مسلم (2578: 56)."},{"num":14896,"demo":false,"sanad":"","matn":["عَنْ ا بن عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2447)، ومسلم في البر والصلة (2579: 57) كلاهما من طريق عبد العزيز الماجشون، عن عبد الله بن دينار، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الظلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2447) and Muslim (2579:57).","chapter_en":"The Prohibition of Injustice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Indeed, injustice will be layers of darkness on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2447)، ومسلم (2579: 57)."},{"num":14897,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَتَدْرُونَ مَا الْمُفْلِسُ؟ قَالُوا: الْمُفْلِسُ فِينَا مَنْ لَا دِرْهَمَ لَهُ، وَلَا مَتَاعَ، فَقَالَ: إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلَاةٍ، وَصِيَامٍ، وَزَكَاةٍ، وَيَأْتِي قَدْ شَتَمَ هَذَا، وَقَذَفَ هَذَا، وَأَكَلَ مَالَ هَذَا، وَسَفَكَ دَمَ هَذَا، وَضَرَبَ هَذَا، فَيُعْطَى هَذَا مِنْ حَسَنَاتِهِ، وَهَذَا مِنْ حَسَنَاتِهِ، فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يُقْضَى مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ، ثُمَّ طُرِحَ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في المظالم (2581: 59) من طرق عن إسماعيل وهو ابن جعفر، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الظلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2581:59).","chapter_en":"The Prohibition of Injustice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do you know who the bankrupt person is?” They replied: “The bankrupt person among us is the one who has neither dirhams nor possessions.” He said: “The bankrupt person from my Ummah is the one who comes on the Day of Resurrection with prayer, fasting, and zakāh, but he also comes having insulted this person, falsely accused that person, consumed another person’s wealth, shed another person’s blood, and struck another person. So this person will be given from his good deeds, and that person will be given from his good deeds. If his good deeds run out before what he owes has been fully settled, some of their sins will be taken and cast upon him, and then he will be cast into the Fire.”"]}},"tuhfa":{},"full":1,"rep":[5924,12735,12981,16221],"tks":"صحيح: رواه مسلم (2581: 59)."},{"num":14898,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إن الله عزوجل يملي للظالم، فإذا أخذه لم يفلته ثم قرأ: ﴿وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ﴾) [هود: ١٠٢]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4686)، ومسلم في البر والصلة (2583: 11) كلاهما من طريق أبي معاوية، حدثنا بريد بن أبي بردة، عن أبيه، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الظلم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4686) and Muslim (2583:11).","chapter_en":"The Prohibition of Injustice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":10,"content":{"translation":{"en":["Abū Mūsā narrated that the Messenger of Allah ﷺ said: “Indeed, Allah, Mighty and Majestic, gives the wrongdoer respite, but when He seizes him, He does not let him escape.” Then he recited: “Such is the seizure of your Lord when He seizes the towns while they are wrongdoing. Indeed, His seizure is painful and severe.” [Sūrat Hūd 11:102]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4686)، ومسلم (2583: 11)."},{"num":14899,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: إِنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَلَا أُنَبِّئُكُمْ مَا الْعَضْهُ؟ هِيَ النَّمِيمَةُ الْقَالَةُ بَيْنَ النَّاسِ وَإِنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الرَّجُلَ يَصْدُقُ حَتَّى يُكْتَبَ صِدِّيقًا، وَيَكْذِبُ حَتَّى يُكْتَبَ كَذَّابًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2606) من طرق عن محمد بن جعفر، حدثنا شعبة، سمعت أبا إسحاق، يحدث عن أبي الأحوص، عن عبد الله بن مسعود، قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم النميمة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2606).","chapter_en":"The Prohibition of Tale-Bearing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that Muḥammad ﷺ said: “Shall I tell you what al-ʿaḍh is? It is tale-bearing: carrying statements between people.” And Muḥammad ﷺ also said: “A man continues to speak truthfully until he is recorded as a person of utmost truthfulness, and he continues to lie until he is recorded as a liar.”"]},"buhuth":{"en":["Regarding the word al-ʿaḍh, Ibn al-Athīr said in al-Nihāyah that this is how it is narrated in the books of hadith, while the books of uncommon vocabulary transmit it as al-ʿiḍah, with a kasrah on the ʿayn and a fatḥah on the ḍād.","Al-Zamakhsharī said that its original form is al-ʿiḍhah, derived from al-ʿaḍh, meaning slander and false accusation. Its final letter was omitted just as letters were omitted in certain other Arabic words, and its plural is ʿiḍīn.","It may be said:","“There is an ugly ʿiḍah between them,”","meaning malicious slander or tale-bearing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2606)."},{"num":14900,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَدْرُونَ مَا الْعَضْهُ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: نَقْلُ الْحَدِيثِ مِنْ بَعْضِ النَّاسِ إِلَى بَعْضٍ، لِيُفْسِدُوا بَيْنَهُمْ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (424)، والبيهقي (21159) كلاهما من حديث يزيد بن أبي حبيب، عن سنان بن سعد، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب تحريم النميمة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (424) and al-Bayhaqī (10/246–247).","chapter_en":"The Prohibition of Tale-Bearing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Do you know what al-ʿaḍh is?” They replied: “Allah and His Messenger know best.” He said: “It is carrying statements from some people to others in order to cause corruption between them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (424)، والبيهقي (21159)."},{"num":14901,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَدْخُلُ الْجَنَّةَ قَتَّاتٌ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6056)، ومسلم في الإيمان (105) كلاهما من طريق عن منصور، عن إبراهيم، عن همام بن الحارث، قال: كان رجل ينقل الحديث إلى الأمير، فكنا جلوسا في المسجد فقال القوم: هذا ممن ينقل الحديث إلى الأمير، قال: فجاء حتى جلس إلينا فقال حذيفة: فذكر الحديث. واللفظ لمسلم","grade":"متفق عليه","chapter_ar":"باب تحريم النميمة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6056) and Muslim (105). The wording is that of Muslim.","chapter_en":"The Prohibition of Tale-Bearing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":11,"content":{"translation":{"en":["Ḥudhayfah narrated: I heard the Prophet ﷺ say: “A tale-bearer will not enter Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6056)، ومسلم (105)، واللفظ لمسلم."},{"num":14902,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرَيْنِ، فَقَالَ: إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا هَذَا: فَكَانَ لاَ يَسْتَتِرُ مِنْ بَوْلِهِ، وَأَمَّا هَذَا: فَكَانَ يَمْشِي بِالنَّمِيمَةِ ثُمَّ دَعَا بِعَسِيبٍ رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ، فَغَرَسَ عَلَى هَذَا وَاحِدًا، وَعَلَى هَذَا وَاحِدًا، ثُمَّ قَالَ: لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6052)، ومسلم في الطهارة (292) كلاهما من طريق وكيع، عن الأعمش، قال: سمعت مجاهدا، يحدث، عن طاوس، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم النميمة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6052) and Muslim (292).","chapter_en":"The Prohibition of Tale-Bearing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The Messenger of Allah ﷺ passed by two graves and said: “The two of them are being punished, and they are not being punished for something they regarded as serious. As for this one, he did not protect himself from his urine; and as for the other, he used to go about spreading tales between people.” Then he called for a fresh palm stalk, split it into two pieces, planted one upon each grave, and said: “Perhaps their punishment will be lightened as long as these two do not dry out.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6052)، ومسلم (292)."},{"num":14903,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَتَدْرُونَ مَا الْغِيبَةُ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قِيلَ: أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ؟ قَالَ: إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ، وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ بَهَتَّهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة والآداب (2589) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2589).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do you know what backbiting is?” They replied: “Allah and His Messenger know best.” He said: “It is mentioning your brother in a way that he dislikes.” It was asked: “What if what I say about my brother is actually true?” He replied: “If what you say is true, then you have backbitten him. If it is not true, then you have slandered him.”"]}},"tuhfa":{},"full":1,"rep":[13108,13358],"tks":"صحيح: رواه مسلم (2589)."},{"num":14904,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: حَكَيْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا، فَقَالَ: مَا يَسُرُّنِي أَنِّي حَكَيْتُ رَجُلًا، وَأَنَّ لِي كَذَا وَكَذَا، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ صَفِيَّةَ امْرَأَةٌ - وَقَالَ بِيَدِهِ، كَأَنَّهُ يَعْنِي قَصِيرَةً - فَقَالَ: لَقَدْ مَزَجْتِ بِكَلِمَةٍ، لَوْ مُزِجَ بِهَا مَاءُ الْبَحْرِ مَزَجَتْ."],"takhrij":"صحيح: رواه أبو داود (4875) والترمذي (2502، 2503) وأحمد (25560) كلهم من طريق سفيان الثوري، قال: حدثنا علي بن الأقمر، عن أبي حذيفة –وكان من أصحاب عبد الله، وكان طلحة يحدث عنه- عن عائشة، قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4875), al-Tirmidhī (2502, 2503), and Aḥmad (25560).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: I imitated a man in the presence of the Prophet ﷺ. He said: “I would not like to imitate a person even if I were given such-and-such in return.” She said: I then said: “O Messenger of Allah, Ṣafiyyah is a woman…” and she gestured with her hand, apparently indicating that Ṣafiyyah was short. He said: “You have uttered a word which, if it were mixed with the water of the sea, would contaminate it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13359],"tks":"صحيح: رواه أبو داود (4875)، والترمذي (2502، 2503)، وأحمد (25560)."},{"num":14905,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: هَاجَتْ رِيحٌ مُنْتِنَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ نَاسًا مِنَ الْمُنَافِقِينَ اغْتَابُوا أُنَاسًا مِنَ الْمُسْلِمِينَ، فَبُعِثَتْ هَذِهِ الرِّيحُ لِذَلِكَ."],"takhrij":"صحيح: رواه عبد بن حميد (1028) والبخاري في الأدب المفرد (733) والخرائطي في مساوئ الأخلاق (187) كلهم من طريق فضيل بن عياض، عن سليمان –وهو الأعمش-، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd ibn Ḥumayd (1028), al-Bukhārī in al-Adab al-Mufrad (733), and al-Kharāʾiṭī in Masāwiʾ al-Akhlāq (187).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Jābir narrated: A foul-smelling wind arose during the time of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “Some of the hypocrites have backbitten some of the Muslims, and this wind was sent because of that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد بن حميد (1028)، والبخاري في الأدب المفرد (733)، والخرائطي في مساوئ الأخلاق (187)."},{"num":14906,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَارْتَفَعَتْ رِيحُ جِيفَةٍ مُنْتِنَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَدْرُونَ مَا هَذِهِ الرِّيحُ؟ هَذِهِ رِيحُ الَّذِينَ يَغْتَابُونَ الْمُؤْمِنِينَ."],"takhrij":"حسن: رواها أحمد (14784) والبخاري في الأدب المفرد (732) كلاهما من طريق عبد الوارث بن سعيد، حدثنا واصل مولى أبي عيينة، حدثني خالد بن عُرْفُطة، عن طلحة بن نافع، عن جابر بن عبد الله، قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (14784) and al-Bukhārī in al-Adab al-Mufrad (732).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: We were with the Prophet ﷺ when a foul wind, like the smell of a decaying corpse, arose. The Messenger of Allah ﷺ said: “Do you know what this smell is? This is the smell of those who backbite the believers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (14784)، والبخاري في الأدب المفرد (732)."},{"num":14907,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا عُرِجَ بِي مَرَرْتُ بِقَوْمٍ لَهُمْ أَظْفَارٌ مِنْ نُحَاسٍ يَخْمِشُونَ وُجُوهَهُمْ وَصُدُورَهُمْ، فَقُلْتُ: مَنْ هَؤُلاَءِ يَا جِبْرِيلُ؟ قَالَ: هَؤُلاَءِ الَّذِينَ يَأْكُلُونَ لُحُومَ النَّاسِ، وَيَقَعُونَ فِي أَعْرَاضِهِمْ."],"takhrij":"صحيح: رواه أبو داود (4878) وأحمد (13340) كلاهما من طريق أبي المغيرة الخولاني، حدثنا صفوان السكسكي، حدثني راشد بن سعد وعبد الرحمن بن جبير، عن أنس بن مالك، قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4878) and Aḥmad (13340).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “When I was taken up, I passed by a people who had fingernails of copper with which they were scratching their faces and chests. I asked, ‘Who are these, O Jibrīl?’ He replied, ‘These are the ones who used to eat the flesh of people and attack their honor.’”"]}},"tuhfa":{},"full":1,"rep":[8613,13364,13954],"tks":"صحيح: رواه أبو داود (4878)، وأحمد (13340)."},{"num":14908,"demo":false,"sanad":"","matn":["عن أنس قال: كانت العرب تخدم بعضها بعضا في الأسفار، وكان مع أبي بكر وعمر رجل يخدمهما فنام، فاستيقظا ولم يهيئ طعاما، فقال: إن هذا لنؤوم بينكم، فأيقظاه فقالا: ائت رسول الله صلى الله عليه وسلم فقل له: إن أبا بكر وعمر يقرئانك السلام، وهما يستأدمانك، فأتاه فقال صلى الله عليه وسلم: أخبرهما أنهما قد ائتدما ففزعا، فجاءا إلى النبي صلى الله عليه وسلم، فقالا: يا رسول الله، بعثنا نستأدمك، فقلت: ائتدما فبأي شيء ائتدمنا؟ فقال: بأكلكما لحم أخيكما، إني لأرى لحمه بين ثناياكم فقالا: يا رسول الله، فاستغفر لنا، قال: هو فليستغفر لكما."],"takhrij":"حسن: رواه الخرائطي في مساوئ الأخلاق (186) والضياء المقدسي في المختارة (1696، 1697) كلاهما من طريق أبي بدر عباد بن الوليد، حدثنا حبان بن هلال، حدثنا حماد بن سلمة، أنبأنا ثابت البناني، عن أنس، قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Kharāʾiṭī in Masāwiʾ al-Akhlāq (186) and al-Ḍiyāʾ al-Maqdisī in al-Mukhtārah (1696, 1697).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Anas narrated: The Arabs used to serve one another during journeys. Abū Bakr and ʿUmar had a man with them who served them. He fell asleep, and when they awoke they found that he had not prepared any food. They said: “This man of yours certainly sleeps a lot.” They woke him and said: “Go to the Messenger of Allah ﷺ and tell him: ‘Abū Bakr and ʿUmar send you salām and ask you for something to eat with their bread.’” He went to the Prophet ﷺ, who said: “Tell them that they have already eaten something with their bread.” They became alarmed and came to the Prophet ﷺ, saying: “O Messenger of Allah, we sent to you asking for something to eat with our bread, and you said that we had already eaten. What did we eat?” He replied: “You ate the flesh of your brother. Indeed, I can see his flesh between your teeth.” They said: “O Messenger of Allah, then seek forgiveness for us.” He replied: “Let him seek forgiveness for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13365],"tks":"حسن: رواه الخرائطي في مساوئ الأخلاق (186)، والضياء المقدسي في المختارة (1696، 1697)."},{"num":14909,"demo":false,"sanad":"","matn":["عَنِ الْمُسْتَوْرِدِ، أَنَّهُ حَدَّثَهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَكَلَ بِرَجُلٍ مُسْلِمٍ أَكْلَةً فَإِنَّ اللَّهَ يُطْعِمُهُ مِثْلَهَا مِنْ جَهَنَّمَ، وَمَنْ كُسِيَ ثَوْبًا بِرَجُلٍ مُسْلِمٍ فَإِنَّ اللَّهَ يَكْسُوهُ مِثْلَهُ مِنْ جَهَنَّمَ، وَمَنْ قَامَ بِرَجُلٍ مَقَامَ سُمْعَةٍ وَرِيَاءٍ، فَإِنَّ اللَّهَ يَقُومُ بِهِ مَقَامَ سُمْعَةٍ وَرِيَاءٍ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أبو داود (4881)، والبخاري في الأدب المفرد (240)، وأحمد (18011)، وأبو يعلى (6858) كلهم من طرق عن وقاص بن ربيعة عن المستورد فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4881), al-Bukhārī in al-Adab al-Mufrad (240), Aḥmad (18011), and Abū Yaʿlā (6858).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["Al-Mustawrid narrated that the Prophet ﷺ said: “Whoever gains a meal at the expense of a Muslim man, Allah will feed him the like of it from Hell. Whoever is clothed with a garment at the expense of a Muslim man, Allah will clothe him with the like of it from Hell. And whoever takes a stand against a man for the sake of reputation and showing off, Allah will expose him in a position of reputation and showing off on the Day of Resurrection.”"]},"buhuth":{"en":["The expression “whoever gains a meal at the expense of a Muslim man” means gaining food or benefit through backbiting him, slandering him, attacking his honor, or harming him before someone who is hostile toward him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4881)، والبخاري في الأدب المفرد (240)، وأحمد (18011)، وأبو يعلى (6858)."},{"num":14910,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ- يَعْنِي ابْنَ مَسْعُودٍ - قَالَ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ رَجُلٌ، فَوَقَعَ فِيهِ رَجُلٌ مِنْ بَعْدِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَخَلَّلْ. فَقَالَ: وَمَا أَتَخَلَّلُ يَا رَسُولَ اللَّهِ، أَكَلَتُ لَحْمًا؟ فَقَالَ: إِنَّكَ أَكَلْتَ لَحْمَ أَخِيكَ."],"takhrij":"حسن: رواه الطبراني في الكبير (10092) عن محمد بن عبد الله الحضرمي، ثنا أبو بكر بن أبي شيبة، ثنا أبو خالد، عن يونس بن أبي إسحاق، عن أبي إسحاق، عن أبي الأحوص، عن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغيبة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (10/126).","chapter_en":"The Prohibition of Backbiting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: We were sitting with the Prophet ﷺ when a man got up and left. Another man then spoke ill of him after he had gone. The Prophet ﷺ said to him: “Clean between your teeth.” He said: “Why should I clean between my teeth, O Messenger of Allah? Have I eaten meat?” He replied: “You have eaten the flesh of your brother.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (10092)."},{"num":14911,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الأَسْلَمِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا مَعْشَرَ مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلِ الإِيمَانُ قَلْبَهُ، لاَ تَغْتَابُوا الْمُسْلِمِينَ، وَلاَ تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنِ اتَّبَعَ عَوْرَاتِهِمْ يَتَّبِعِ اللَّهُ عَوْرَتَهُ، وَمَنْ يَتَّبِعِ اللَّهُ عَوْرَتَهُ يَفْضَحْهُ فِي بَيْتِهِ."],"takhrij":"حسن: رواه أبو داود (4880) وأحمد (19776) وأبو يعلى (7423) والبيهقي في الكبرى (21164) كلهم من طريق أبي بكر بن عياش، عن الأعمش، عن سعيد بن عبد الله بن جريج، عن أبي برزة الأسلمي، قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تتبع عورات المسلمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4880), Aḥmad (19776), Abū Yaʿlā (7423), and al-Bayhaqī in al-Sunan al-Kubrā (10/247).","chapter_en":"Warning against Searching for the Faults and Private Matters of Muslims","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":13,"content":{"translation":{"en":["Abū Barzah al-Aslamī narrated that the Messenger of Allah ﷺ said: “O people who have believed with their tongues while faith has not entered their hearts, do not backbite the Muslims and do not search for their faults. Whoever searches for their faults, Allah will search out his faults, and whoever Allah searches out his faults, He will disgrace him even inside his own home.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13360,13953],"tks":"حسن: رواه أبو داود (4880)، وأحمد (19776)، وأبو يعلى (7423)، والبيهقي في الكبرى (21164)."},{"num":14912,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَسْمَعَ الْعَوَاتِقَ فِي بُيُوتِهَا، أَوْ قَالَ: فِي خُدُورِهَا، فَقَالَ: يَا مَعْشَرَ مَنْ آمَنَ بِلِسَانِهِ، لَا تَغْتَابُوا الْمُسْلِمِينَ، وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنْ تَتَبَّعَ عَوْرَةَ أَخِيهِ تَتَبَّعَ اللَّهُ عَوْرَتَهُ، وَمَنْ تَتَبَّعِ اللَّهُ عَوْرَتَهُ يَفْضَحْهُ فِي جَوْفِ بَيْتِهِ."],"takhrij":"حسن: رواه أبو يعلى (1675) عن إبراهيم بن دينار، حدثنا مصعب بن سلام، عن حمزة بن حبيب الزيات، عن أبي إسحاق السبيعي، عن البراء، فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تتبع عورات المسلمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (1675).","chapter_en":"Warning against Searching for the Faults and Private Matters of Muslims","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":13,"content":{"translation":{"en":["Al-Barāʾ narrated: The Messenger of Allah ﷺ delivered a sermon to us so loudly that even the young women in their homes—or in their private chambers—could hear him. He said: “O people who have believed with their tongues, do not backbite the Muslims and do not search for their faults. Whoever searches for the fault of his brother, Allah will search for his fault, and whoever Allah searches for his fault, He will disgrace him inside his own house.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13361],"tks":"حسن: رواه أبو يعلى (1675)."},{"num":14913,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: صَعِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ فَنَادَى بِصَوْتٍ رَفِيعٍ فَقَالَ: يَا مَعْشَرَ مَنْ قَدْ أَسْلَمَ بِلِسَانِهِ وَلَمْ يُفْضِ الإِيمَانُ إِلَى قَلْبِهِ، لاَ تُؤْذُوا الْمُسْلِمِينَ، وَلاَ تُعَيِّرُوهُمْ، وَلاَ تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنْ تَتَبَّعَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ تَتَبَّعَ اللَّهُ عَوْرَتَهُ، وَمَنْ تَتَبَّعَ اللَّهُ عَوْرَتَهُ يَفْضَحْهُ وَلَوْ فِي جَوْفِ رَحْلِهِ قَالَ: وَنَظَرَ ابْنُ عُمَرَ يَوْمًا إِلَى الْبَيْتِ أَوْ إِلَى الْكَعْبَةِ، فَقَالَ: مَا أَعْظَمَكِ، وَأَعْظَمَ حُرْمَتَكِ، وَالْمُؤْمِنُ أَعْظَمُ حُرْمَةً عِنْدَ اللَّهِ مِنْكِ."],"takhrij":"حسن: رواه الترمذي (2032) وابن حبان (5763) كلاهما من طريق الفضل بن موسى، حدثنا الحسين بن واقد، عن أوفى بن دلهم، عن نافع، عن ابن عمر، قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تتبع عورات المسلمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2032) and Ibn Ḥibbān (5763).","chapter_en":"Warning against Searching for the Faults and Private Matters of Muslims","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ ascended the pulpit and called out in a loud voice: “O people who have submitted with their tongues while faith has not reached their hearts, do not harm the Muslims, do not shame them, and do not search for their faults. Whoever searches for the fault of his Muslim brother, Allah will search for his fault, and whoever Allah searches for his fault, He will disgrace him even inside his own dwelling.” Ibn ʿUmar once looked at the House—or the Kaʿbah—and said: “How great you are, and how great your sanctity is! Yet the believer has greater sanctity with Allah than you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13362],"tks":"حسن: رواه الترمذي (2032)، وابن حبان (5763)."},{"num":14914,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّكَ إِنِ اتَّبَعْتَ عَوْرَاتِ النَّاسِ أَفْسَدْتَهُمْ، أَوْ كِدْتَ أَنْ تُفْسِدَهُمْ. فَقَالَ أَبُو الدَّرْدَاءِ كَلِمَةٌ سَمِعَهَا مُعَاوِيَةُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَعَهُ اللَّهُ تَعَالَى بِهَا."],"takhrij":"صحيح: رواه أبو داود (4888)، وابن حبان (5760)، والبيهقي في الكبرى (17623) كلهم من طريق محمد بن يوسف الفريابي، عن سفيان (هو الثوري)، عن ثور، عن راشد بن سعد، عن معاوية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التحذير من تتبع عورات المسلمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4888), Ibn Ḥibbān (5760), and al-Bayhaqī in al-Sunan al-Kubrā (8/333).","chapter_en":"Warning against Searching for the Faults and Private Matters of Muslims","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":13,"content":{"translation":{"en":["Muʿāwiyah narrated: I heard the Messenger of Allah ﷺ say: “If you search for people’s faults, you will corrupt them—or you will nearly corrupt them.” Abū al-Dardāʾ said: “A statement Muʿāwiyah heard from the Messenger of Allah ﷺ, and Allah, the Exalted, benefited him through it.”"]},"buhuth":{"en":["The words “if you search for…” refer to spying for the purpose of uncovering people’s private faults and defects and publicizing them. There is no doubt that this causes great corruption.","As for investigation undertaken for the preservation of public security and safety, and for identifying saboteurs and corrupt people, the author states that this is a duty of the state in order to protect society, property, honor, and lives."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4888)، وابن حبان (5760)، والبيهقي في الكبرى (17623)."},{"num":14915,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ وَأَبِي أُمَامَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْأَمِيرَ إِذَا ابْتَغَى الرِّيبَةَ فِي النَّاسِ أَفْسَدَهُمْ."],"takhrij":"حسن: رواه الطبراني في مسند الشاميين (1660) عن أحمد بن المعلى (هو الدمشقي)، ثنا هشام بن عمار، ثنا إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن جبير بن نفير، وكثير بن مرة، عن المقدام بن معدي كرب وأبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تتبع عورات المسلمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in Musnad al-Shāmiyyīn (1660).","chapter_en":"Warning against Searching for the Faults and Private Matters of Muslims","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":13,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdīkarib and Abū Umāmah narrated that the Prophet ﷺ said: “When a ruler goes looking for reasons to suspect people, he corrupts them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في مسند الشاميين (1660)."},{"num":14916,"demo":false,"sanad":"","matn":["حَدَّثَتْنِي عَائِشَةُ،  أَنَّ رَجُلًا اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: ائْذَنُوا لَهُ، فَلَبِئْسَ ابْنُ الْعَشِيرَةِ، أَوْ بِئْسَ رَجُلُ الْعَشِيرَةِ فَلَمَّا دَخَلَ عَلَيْهِ أَلَانَ لَهُ الْقَوْلَ. قَالَتْ عَائِشَةُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ قُلْتَ لَهُ الَّذِي قُلْتَ، ثُمَّ أَلَنْتَ لَهُ الْقَوْلَ؟ قَالَ: يَا عَائِشَةُ إِنَّ شَرَّ النَّاسِ مَنْزِلَةً عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ، مَنْ وَدَعَهُ، أَوْ تَرَكَهُ النَّاسُ اتِّقَاءَ فُحْشِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6054)، ومسلم في البر والصلة (2591: 73) كلاهما من طريق سفيان بن عيينة، عن ابن المنكدر، سمع عروة بن الزبير، يقول: حدثتني عائشة فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز اغتياب أهل الشر والفساد، ودفاع شرهم بالكلام والمال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6054) and Muslim (2591:73).","chapter_en":"The Permissibility of Mentioning the Faults of People of Evil and Corruption, and Repelling Their Harm with Words and Wealth","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":14,"content":{"translation":{"en":["ʿĀ’ishah narrated: A man asked permission to enter upon the Prophet ﷺ. The Prophet ﷺ said: “Allow him to enter. What a bad son of his clan he is,” or: “What a bad man of his clan he is.” When the man entered, the Prophet ﷺ spoke gently to him. ʿĀ’ishah said: I asked: “O Messenger of Allah, you said about him what you said, then you spoke gently to him?” He replied: “O ʿĀ’ishah, among the worst people in rank before Allah on the Day of Resurrection is the one whom people leave alone or avoid because they fear his obscene and abusive speech.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6054)، ومسلم (2591: 73)."},{"num":14917,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ذُبُّوا بِأَمْوَالِكُمْ عَنْ أَعْرَاضِكُمْ، قَالُوا: يَا رَسُولَ اللَّهِ، كَيْفَ تَذُبُّ بِأَمْوَالِنَا عَنْ أَعْرَاضِنَا؟، قَالَ: يُعْطِي الشَّاعِرَ، وَمَنْ تَخَافُونَ مِنْ لِسَانِهِ."],"takhrij":"حسن: رواه حمزة بن يوسف السهمي في تاريخ جرجان (356) عن أبي بكر أحمد بن إبراهيم الإسماعيلي، حدثنا أبو بكر بن عمير، حدثنا سيّار بن نصر بن سيّار البزّاز، حدثنا الهيثم بن أيوب الطالقاني، حدثنا سهل بن عبد الرحمن الجرجاني، حدثنا محمد بن مطرف، عن محمد بن المنكدر، عن سعيد بن المسيب، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب جواز اغتياب أهل الشر والفساد، ودفاع شرهم بالكلام والمال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ḥamzah ibn Yūsuf al-Sahmī in Tārīkh Jurjān (p. 223).","chapter_en":"The Permissibility of Mentioning the Faults of People of Evil and Corruption, and Repelling Their Harm with Words and Wealth","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Defend your honor with your wealth.” They asked: “O Messenger of Allah, how do we defend our honor with our wealth?” He replied: “By giving something to the poet and to anyone whose tongue you fear.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه حمزة بن يوسف السهمي في تاريخ جرجان (ص 223)."},{"num":14918,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ. قِيلَ: يَا رَسُولَ اللَّهِ، وَكَيْفَ يَلْعَنُ الرَّجُلُ وَالِدَيْهِ؟ قَالَ: يَسُبُّ الرَّجُلُ أَبَا الرَّجُلِ، فَيَسُبُّ أَبَاهُ، وَيَسُبُّ أَمَّهُ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (5973)، ومسلم في الإيمان (90) كلاهما من طريق سعد بن إبراهيم، عن حُميد بن عبد الرحمن، عن عبد الله بن عمرو بن العاص فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن سب الوالدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5973) and Muslim (90).","chapter_en":"The Prohibition of Insulting One’s Parents","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “Among the greatest of the major sins is that a man curses his own parents.” They asked: “O Messenger of Allah, how does a man curse his own parents?” He replied: “He insults another man’s father, so that man insults his father; and he insults his mother, so that man insults his mother.”"]}},"tuhfa":{},"full":1,"rep":[14045],"tks":"متفق عليه: رواه البخاري (5973)، ومسلم (90)."},{"num":14919,"demo":false,"sanad":"","matn":["عن أَبِي الطُّفَيْلِ عامر بن وَاثِلَةَ قَالَ: كُنْتُ عِنْدَ عَلِيِّ بْنِ أَبِي طَالِبٍ، فَأَتَاهُ رَجُلٌ، فَقَالَ: مَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسِرُّ إِلَيْكَ؟ قَالَ: فَغَضِبَ، وَقَالَ: مَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسِرُّ إِلَيَّ شَيْئًا يَكْتُمُهُ النَّاسَ، غَيْرَ أَنَّهُ قَدْ حَدَّثَنِي بِكَلِمَاتٍ أَرْبَعٍ، قَالَ: فَقَالَ: مَا هُنَّ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: قَالَ: لَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَهُ، وَلَعَنَ اللهُ مَنْ ذَبَحَ لِغَيْرِ اللهِ، وَلَعَنَ اللهُ مَنْ آوَى مُحْدِثًا، وَلَعَنَ اللهُ مَنْ غَيَّرَ مَنَارَ الْأَرْضِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1978) من طرق عن مروان بن معاوية الفزاري، حدثنا منصور بن حيان، حدثنا أبو الطفيل عامر بن واثلة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن سب الوالدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1978).","chapter_en":"The Prohibition of Insulting One’s Parents","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":15,"content":{"translation":{"en":["Abū al-Ṭufayl ʿĀmir ibn Wāthilah narrated: I was with ʿAlī ibn Abī Ṭālib when a man came to him and asked: “What did the Prophet ﷺ privately confide to you?” ʿAlī became angry and said: “The Prophet ﷺ never privately told me anything that he concealed from the people, except that he did tell me four statements.” The man asked: “What are they, O Commander of the Believers?” ʿAlī replied that the Prophet ﷺ said: “May Allah curse whoever curses his father. May Allah curse whoever sacrifices for other than Allah. May Allah curse whoever shelters an offender. And may Allah curse whoever alters the boundary markers of the land.”"]},"buhuth":{"en":["The expression “alters the boundary markers of the land” means causing corruption and destruction by changing established land boundaries."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1978)."},{"num":14920,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَلْعُونٌ مَنْ سَبَّ أَبَاهُ، مَلْعُونٌ مَنْ سَبَّ أُمَّهُ، مَلْعُونٌ مَنْ ذَبَحَ لِغَيْرِ الله، مَلْعُونٌ مَنْ غَيَّرَ تُخُومَ الْأَرْضِ، مَلْعُونٌ مَنْ كَمَّهَ أَعْمَى عَنْ الطَّرِيقِ، مَلْعُونٌ مَنْ وَقَعَ عَلَى بَهِيمَةٍ، مَلْعُونٌ مَنْ عَمِلَ عَمَلَ قَوْمِ لُوطٍ.","وفي رواية: قَالَهَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِرَارًا ثَلَاثًا فِي اللُّوطِيَّةِ."],"takhrij":"حسن: رواه أحمد (1875، 2913، 2914، 2915)، والطبراني في الكبير (4/356)، والخرائطي في مساوئ الأخلاق (75) كلهم من حديث عمرو بن أبي عمرو مولى المطلب، عن عكرمة، عن ابن عباس قال: فذكره. قال الحاكم: \"صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب النهي عن سب الوالدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (1875, 2913, 2914, 2915) and al-Ṭabarānī in al-Muʿjam al-Kabīr (4/356).","chapter_en":"The Prohibition of Insulting One’s Parents","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “Cursed is the one who insults his father. Cursed is the one who insults his mother. Cursed is the one who sacrifices for other than Allah. Cursed is the one who alters the boundaries of the land. Cursed is the one who deliberately misdirects a blind person from the road. Cursed is the one who has intercourse with an animal. Cursed is the one who commits the act of the people of Lūṭ.”","In another narration, the Messenger of Allah ﷺ repeated the statement concerning the act of the people of Lūṭ three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1875، 2913، 2914، 2915)، والطبراني في الكبير (4/356)."},{"num":14921,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلاَ تَجَسَّسُوا، وَلاَ تَحَسَّسُوا، وَلاَ تنافسوا، وَلاَ تَحَاسَدُوا، وَلاَ تَبَاغَضُوا، وَلاَ تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا."],"takhrij":"متفق عليه: رواه مالك في حسن الخلق (15) عن أبي الزناد، عن الأعرج، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ḥusn al-Khuluq (15), al-Bukhārī (6066), and Muslim (2563:28).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Beware of suspicion, for suspicion is the falsest of speech. Do not spy, do not seek out one another’s secrets, do not compete against one another in rivalry, do not envy one another, do not hate one another, and do not turn your backs on one another. Rather, be servants of Allah as brothers.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13355],"tks":"متفق عليه: رواه مالك (15)، والبخاري (6066)، ومسلم (2563: 28)."},{"num":14922,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَحَاسَدُوا، وَلَا تَبَاغَضُوا، وَلَا تَجَسَّسُوا، وَلَا تَحَسَّسُوا، وَلَا تَنَاجَشُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا وَفِي لفظ: لَا تقاطعوا، وَلَا تَدَابَرُوا، وَلَا تَبَاغَضُوا، وَلَا تَحَاسَدُوا، وَكُونُوا إِخْوَانًا كَمَا أمركم اللَّهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2563: 30) من طريق جرير، عن الأعمش، عن أبي صالح، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2563:30).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not envy one another, do not hate one another, do not spy on one another, do not seek out one another’s hidden matters, do not engage in deceptive bidding, and be servants of Allah as brothers.” In another wording: “Do not cut one another off, do not turn your backs on one another, do not hate one another, and do not envy one another. Be brothers as Allah has commanded you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2563: 30)."},{"num":14923,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَهَجَّرُوا، وَلَا تَدَابَرُوا، وَلَا تَحَسَّسُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2563: 29) عن قتيبة بن سعيد، حدثنا عبد العزيز يعني ابن محمد، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2563:29).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not boycott one another, do not turn your backs on one another, do not seek out one another’s hidden matters, and let none of you sell over the sale of another. Be servants of Allah as brothers.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2563: 29)."},{"num":14924,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا تَنَافَسُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2563: 29) عن أحمد بن سعيد الدارمي، حدثنا حبان، حدثنا وهيب، حدثنا سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2563:29).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Do not hate one another, do not turn your backs on one another, and do not compete against one another in rivalry. Be servants of Allah as brothers.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2563: 29)."},{"num":14925,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِيَّاكُمْ وَالْحَسَدَ، فَإِنَّ الْحَسَدَ يَأْكُلُ الْحَسَنَاتِ كَمَا تَأْكُلُ النَّارُ الْحَطَبَ. أَوْ قَالَ: الْعُشْبَ."],"takhrij":"حسن: رواه أبو داود (4903)، وعبد بن حميد (1430) كلاهما من طريق أبي عامر يعني عبد الملك بن عمرو، حدثنا سليمان بن بلال، عن إبراهيم بن أبي أسيد، عن جده، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4903) and ʿAbd ibn Ḥumayd (1430).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Beware of envy, for envy consumes good deeds just as fire consumes firewood—or he said: grass.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4903)، وعبد بن حميد (1430)."},{"num":14926,"demo":false,"sanad":"","matn":["عن ضمرة بن ثَعْلَبَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا لَمْ يَتَحَاسَدُوا."],"takhrij":"حسن: رواه أبو الشيخ في التوبيخ والتنبيه (80)، والطبراني في الكبير (8157) كلاهما من طرق عن إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن أبي بحرية، عن ضمرة بن ثعلبة فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū al-Shaykh in al-Tawbīkh wa-al-Tanbīh (80) and al-Ṭabarānī in al-Muʿjam al-Kabīr (8/369).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Ḍamrah ibn Thaʿlabah narrated that the Messenger of Allah ﷺ said: “People will continue to remain upon goodness so long as they do not envy one another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو الشيخ في التوبيخ والتنبيه (80)، والطبراني في الكبير (8157)."},{"num":14927,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ وَهْبٍ، قَالَ: أُتِيَ ابْنُ مَسْعُودٍ فَقِيلَ هَذَا فُلاَنٌ تَقْطُرُ لِحْيَتُهُ خَمْرًا، فَقَالَ عَبْدُ اللَّهِ: إِنَّا قَدْ نُهِينَا عَنِ التَّجَسُّسِ وَلَكِنْ إِنْ يَظْهَرْ لَنَا شَىْءٌ نَأْخُذْ بِهِ."],"takhrij":"صحيح: رواه أبو داود (4890)، وعبد الرزاق في المصنف (18945)، وصحّحه الحاكم (4/377) كلهم من طرق عن الأعمش، عن زيد بن وهب قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4890), ʿAbd al-Razzāq in al-Muṣannaf (18945), and authenticated by al-Ḥākim (4/377).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Zayd ibn Wahb narrated: Someone came to Ibn Masʿūd and said: “So-and-so has wine dripping from his beard.” ʿAbdullāh ibn Masʿūd replied: “We have been prohibited from spying. But if something becomes openly apparent to us, we act upon it.”"]},"buhuth":{"en":["The person referred to as “so-and-so” is named in the narrations of ʿAbd al-Razzāq and al-Ḥākim as al-Walīd ibn ʿUqbah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4890)، وعبد الرزاق في المصنف (18945)، وصححه الحاكم (4/377)."},{"num":14928,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْتَعِينُوا عَلَى الْحَوَائِجِ بِكِتْمَانِهَا، فَإِنَّ لِكُلِّ نِعْمَةٍ حَاسِدًا."],"takhrij":"حسن: رواه ابنُ حبان في روضة العقلاء( ص187)، وحمزة بن يوسف السهمي في تاريخ جرجان (ص 223) –واللفظ له- كلاهما من طريق الهيثم بن أيوب الطالقاني، حدثنا سهل بن عبدالرحمن الجرجاني، عن محمد بن مطرف أبي غسّان، عن محمد بن المنكدر، عن عروة، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān in Rawḍat al-ʿUqalāʾ (p. 187) and Ḥamzah al-Sahmī in Tārīkh Jurjān (p. 223).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Seek help in accomplishing your needs by keeping them concealed, for every blessing has someone who envies it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في روضة العقلاء (ص 187)، وحمزة السهمي في تاريخ جرجان (ص 223)."},{"num":14929,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: لَمَّا نَظَرَ رَسُولُ اللهِ صلى الله عليه وسلم إِلَى الْكَعْبَةِ قَالَ: مَرْحَبًا بِكِ مِنْ بَيْتٍ، مَا أَعْظَمَكِ، وَأَعْظَمَ حُرْمَتَكِ، وَلَلْمُؤْمِنُ أَعْظَمُ حُرْمَةَ عِنْدَ اللهِ مِنْكِ، إِنَّ اللهَ حَرَّمَ مِنْكِ وَاحِدَةً، وَحَرَّمَ مِنَ الْمُؤْمِنِ ثَلَاثًا: دَمَهُ وَمَالَهُ وَأَنَ يُظَنَّ بِهِ ظَنَّ السَّوْءِ."],"takhrij":"حسن: رواه البيهقي في الشعب (6280) عن أبي حازم، أنا أبو بكر محمد بن إبراهيم بن حيوة الوراق، أنا جعفر بن أحمد بن نصر، نا الحسين بن منصور، نا حفص بن عبدالرحمن، عن شبل، عن ابن أبي نجيح، عن مجاهد، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من سوء الظن ومن التجسس والتحاسد والتباغض ونحوها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī in Shuʿab al-Īmān (6280).","chapter_en":"Warning against Evil Suspicion, Spying, Envy, Hatred, and Similar Traits","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbās narrated: When the Messenger of Allah ﷺ looked at the Kaʿbah, he said: “Welcome to you, O House! How great you are, and how great your sanctity is! Yet the believer has greater sanctity with Allah than you. Allah has made one thing concerning you sacred, while He has made three things concerning the believer sacred: his blood, his wealth, and that evil suspicion be held about him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في الشعب (6280)."},{"num":14930,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَظُنُّ فُلاَنًا وَفُلاَنًا يَعْرِفَانِ مِنْ دِينِنَا شَيْئًا. قَالَ اللَّيْثُ: كَانَا رَجُلَيْنِ مِنَ الْمُنَافِقِينَ.","وفي لفظ عنها: دخل عليّ النبي صلى الله عليه وسلم يوما، وقال: يا عائشة، ما أظن فلانا وفلانا يعرفان ديننا الذي نحن عليه."],"takhrij":"صحيح: رواه البخاري في الأدب (6067) عن سعيد بن عفير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يجوز من الظن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6067).","chapter_en":"Suspicion That Is Permissible","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Prophet ﷺ said: “I do not think that so-and-so and so-and-so know anything of our religion.” Al-Layth said: “They were two men from among the hypocrites.” In another wording, ʿĀ’ishah said: The Prophet ﷺ entered upon me one day and said: “O ʿĀ’ishah, I do not think that so-and-so and so-and-so understand the religion upon which we are.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6067)."},{"num":14931,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  تُفْتَحُ أَبْوَابُ الْجَنَّةِ يَوْمَ الِاثْنَيْنِ، وَيَوْمَ الْخَمِيسِ، فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللهِ شَيْئًا، إِلَّا رَجُلًا كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ شَحْنَاءُ، فَيُقَالُ: أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا."],"takhrij":"صحيح: رواه مالك في حسن الخلق (17) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ذم الشحناء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in Ḥusn al-Khuluq (17) and Muslim (2565:35).","chapter_en":"Condemnation of Mutual Resentment and Hostility","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The gates of Paradise are opened on Monday and Thursday, and every Muslim servant who does not associate anything with Allah is forgiven, except a man between whom and his brother there is hostility. It is said: ‘Delay these two until they reconcile. Delay these two until they reconcile. Delay these two until they reconcile.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10727,16265],"tks":"صحيح: رواه مالك (17)، ومسلم (2565: 35)."},{"num":14932,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَبَاغَضُوا، وَلاَ تَحَاسَدُوا، وَلاَ تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا، وَلاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ."],"takhrij":"متفق عليه: رواه مالك في الأخلاق (14) عن ابن شهاب، عن أنس بن مالك فذكره. ورواه البخاري في الأدب (6076)، ومسلم في البرو الصلة (2559: 23) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Akhlāq (14), al-Bukhārī (6076), and Muslim (2559:23).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Do not hate one another, do not envy one another, and do not turn your backs on one another. Be servants of Allah as brothers. It is not lawful for a Muslim to boycott his brother for more than three nights.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13357],"tks":"متفق عليه: رواه مالك (14)، والبخاري (6076)، ومسلم (2559: 23)."},{"num":14933,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَحِلُّ لِرَجُلٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ، يَلْتَقِيَانِ فَيُعْرِضُ هَذَا، وَيُعْرِضُ هَذَا، وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلاَمِ."],"takhrij":"متفق عليه: رواه مالك في حسن الخلق (13) عن ابن شهاب، عن عطاء بن يزيد الليثي، عن أبي أيوب الأنصاري فذكره. ورواه البخاري في الأدب (6077)، ومسلم في البر والصلة (2560: 25) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ḥusn al-Khuluq (13), al-Bukhārī (6077), and Muslim (2560:25).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī narrated that the Messenger of Allah ﷺ said: “It is not lawful for a Muslim to boycott his brother for more than three nights. They meet, and this one turns away and that one turns away. The better of the two is the one who begins with the greeting of salām.”"]},"buhuth":{"en":["Regarding the words “more than three nights,” the scholars said that this hadith prohibits Muslims from boycotting one another for more than three nights and permits it during the first three, as explicitly stated in the hadith.","The first three days are excused because human beings are naturally subject to anger, bad temper, and similar reactions. Therefore, a period of three days is allowed so that the temporary cause may subside.","Al-Nawawī mentioned this in his commentary on Muslim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (13)، والبخاري (6077)، ومسلم (2560: 25)."},{"num":14934,"demo":false,"sanad":"","matn":["عَنِ الزُّهْرِيِّ، قَالَ حَدَّثَنِي عَوْفُ بْنُ مَالِكِ بْنِ الطُّفَيْلِ ـ هُوَ ابْنُ الْحَارِثِ وَهْوَ ابْنُ أَخِي عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأُمِّهَا ـ أَنَّ عَائِشَةَ حُدِّثَتْ: أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ قَالَ فِي بَيْعٍ أَوْ عَطَاءٍ أَعْطَتْهُ عَائِشَةُ: وَاللَّهِ لَتَنْتَهِيَنَّ عَائِشَةُ، أَوْ لأَحْجُرَنَّ عَلَيْهَا. فَقَالَتْ: أَهُوَ قَالَ هَذَا؟ قَالُوا: نَعَمْ. قَالَتْ: هُوَ لِلَّهِ عَلَىَّ نَذْرٌ، أَنْ لاَ أُكَلِّمَ ابْنَ الزُّبَيْرِ أَبَدًا. فَاسْتَشْفَعَ ابْنُ الزُّبَيْرِ إِلَيْهَا، حِينَ طَالَتِ الْهِجْرَةُ، فَقَالَتْ: لاَ وَاللَّهِ، لاَ أُشَفِّعُ فِيهِ أَبَدًا، وَلاَ أَتَحَنَّثُ إِلَى نَذْرِي. فَلَمَّا طَالَ ذَلِكَ عَلَى ابْنِ الزُّبَيْرِ كَلَّمَ الْمِسْوَرَ بْنَ مَخْرَمَةَ وَعَبْدَ الرَّحْمَنِ بْنَ الأَسْوَدِ بْنِ عَبْدِ يَغُوثَ، وَهُمَا مِنْ بَنِي زُهْرَةَ، وَقَالَ لَهُمَا: أَنْشُدُكُمَا بِاللَّهِ لَمَّا أَدْخَلْتُمَانِي عَلَى عَائِشَةَ، فَإِنَّهَا لاَ يَحِلُّ لَهَا أَنْ تَنْذُرَ قَطِيعَتِي. فَأَقْبَلَ بِهِ الْمِسْوَرُ وَعَبْدُ الرَّحْمَنِ مُشْتَمِلَيْنِ بِأَرْدِيَتِهِمَا، حَتَّى اسْتَأْذَنَا عَلَى عَائِشَةَ، فَقَالاَ: السَّلاَمُ عَلَيْكِ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، أَنَدْخُلُ؟ قَالَتْ عَائِشَةُ: ادْخُلُوا. قَالُوا: كُلُّنَا؟ قَالَتْ: نَعَمِ، ادْخُلُوا كُلُّكُمْ. وَلاَ تَعْلَمُ أَنَّ مَعَهُمَا ابْنَ الزُّبَيْرِ، فَلَمَّا دَخَلُوا دَخَلَ ابْنُ الزُّبَيْرِ الْحِجَابَ، فَاعْتَنَقَ عَائِشَةَ وَطَفِقَ يُنَاشِدُهَا وَيَبْكِي، وَطَفِقَ الْمِسْوَرُ وَعَبْدُ الرَّحْمَنِ يُنَاشِدَانِهَا إِلاَّ مَا كَلَّمَتْهُ وَقَبِلَتْ مِنْهُ، وَيَقُولاَنِ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَمَّا قَدْ عَلِمْتِ مِنَ الْهِجْرَةِ، فَإِنَّهُ لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ. فَلَمَّا أَكْثَرُوا عَلَى عَائِشَةَ مِنَ التَّذْكِرَةِ وَالتَّحْرِيجِ طَفِقَتْ تُذَكِّرُهُمَا نَذْرَهَا وَتَبْكِي وَتَقُولُ: إِنِّي نَذَرْتُ، وَالنَّذْرُ شَدِيدٌ. فَلَمْ يَزَالاَ بِهَا حَتَّى كَلَّمَتِ ابْنَ الزُّبَيْرِ، وَأَعْتَقَتْ فِي نَذْرِهَا ذَلِكَ أَرْبَعِينَ رَقَبَةً. وَكَانَتْ تَذْكُرُ نَذْرَهَا بَعْدَ ذَلِكَ فَتَبْكِي، حَتَّى تَبُلَّ دُمُوعُهَا خِمَارَهَا."],"takhrij":"صحيح: رواه البخاري في الأدب (6073، 6074، 6075) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: حدثني عوف بن مالك بن الطفيل فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6073, 6074, 6075).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["ʿAwf ibn Mālik ibn al-Ṭufayl—who was the maternal nephew of ʿĀ’ishah, the wife of the Prophet ﷺ—narrated that ʿĀ’ishah related: ʿAbdullāh ibn al-Zubayr said concerning some sale or gift that ʿĀ’ishah had made: “By Allah, ʿĀ’ishah must stop doing this, or I will have her legally restricted from disposing of her wealth.” ʿĀ’ishah asked: “Did he really say that?” They replied: “Yes.” She said: “By Allah, I make a vow never to speak to Ibn al-Zubayr again.” When the estrangement lasted for a long time, Ibn al-Zubayr sought people to intercede for him with her. She said: “No, by Allah, I will never accept intercession for him, nor will I break my vow.” When this became difficult for Ibn al-Zubayr, he spoke to al-Miswar ibn Makhramah and ʿAbd al-Raḥmān ibn al-Aswad ibn ʿAbd Yaghūth, both from Banū Zuhrah. He said to them: “I adjure you by Allah to get me into the presence of ʿĀ’ishah, for it is not lawful for her to vow to sever relations with me.” Al-Miswar and ʿAbd al-Raḥmān brought him with them, wrapped in their cloaks, and sought permission to enter upon ʿĀ’ishah. They said: “Peace, mercy, and blessings of Allah be upon you. May we enter?” ʿĀ’ishah replied: “Enter.” They asked: “All of us?” She replied: “Yes, all of you may enter,” not knowing that Ibn al-Zubayr was with them. When they entered, Ibn al-Zubayr went behind the curtain, embraced ʿĀ’ishah, and began pleading with her and weeping. Al-Miswar and ʿAbd al-Raḥmān also continued pleading with her to speak to him and accept his apology. They reminded her: “The Prophet ﷺ prohibited the kind of estrangement that you know about, for it is not lawful for a Muslim to boycott his brother for more than three nights.” When they repeatedly reminded her and pressed her strongly, ʿĀ’ishah began reminding them of her vow while weeping and saying: “I made a vow, and a vow is a serious matter.” They continued until she finally spoke to Ibn al-Zubayr. As expiation connected to that vow, she freed forty slaves. Afterward, whenever she remembered her vow, she would weep until her tears soaked her head covering."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6073، 6074، 6075)."},{"num":14935,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا يَحِلُّ لِلْمُؤْمِنِ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2561) عن محمد بن رافع، حدثنا محمد بن أبي فديك، أخبرنا الضحاك وهو ابن عثمان، عن نافع، عن عبدالله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2561).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “It is not lawful for a believer to boycott his brother for more than three days.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2561)."},{"num":14936,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا هِجْرَةَ بَعْدَ ثَلَاثٍ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2562) عن قتيبة بن سعيد، حدثنا عبدالعزيز يعني ابن محمد، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2562).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There is to be no estrangement after three days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2562)."},{"num":14937,"demo":false,"sanad":"","matn":["عن سَعْدِ بن مَالِكٍ أَبِي وَقَّاصٍ عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاثٍ."],"takhrij":"صحيح: رواه أحمد (1589)، والبزار- كشف الأستار (2051)، وأبو يعلى (720) كلهم من طريق إسرائيل، عن أبي إسحاق، عن محمد بن سعد بن مالك، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (1589), al-Bazzār as cited in Kashf al-Astār (2051), and Abū Yaʿlā (720).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Saʿd ibn Mālik Abū Waqqāṣ narrated that the Messenger of Allah ﷺ said: “It is not lawful for a Muslim to boycott his brother for more than three days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (1589)، والبزار - كشف الأستار (2051)، وأبو يعلى (720)."},{"num":14938,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَكُونُ لِمُسْلِمٍ أَنْ يَهْجُرَ مُسْلِمًا فَوْقَ ثَلاَثَةٍ، فَإِذَا لَقِيَهُ سَلَّمَ عَلَيْهِ ثَلاَثَ مِرَارٍ كُلُّ ذَلِكَ لاَ يَرُدُّ عَلَيْهِ فَقَدْ بَاءَ بِإِثْمِهِ."],"takhrij":"حسن: رواه أبو داود (4913)، وأبو يعلى (4583) كلاهما من طريق محمد بن المثني، حدثنا محمد بن خالد بن عثمة، حدثنا عبد الله بن المنيب يعني المدني، قال: أخبرني هشام بن عروة، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4913) and Abū Yaʿlā (4583).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “A Muslim should not boycott another Muslim for more than three days. If he meets him and gives him salām three times, but each time the other person refuses to return it, then the one who refuses bears the sin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4913)، وأبو يعلى (4583)."},{"num":14939,"demo":false,"sanad":"","matn":["عن هِشَامِ بن عَامِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ مُسْلِمًا فَوْقَ ثَلَاثِ لَيَالٍ، فَإِنْ كَانَ تَصَارَمَا فَوْقَ ثَلَاثٍ، فَإِنَّهُمَا نَاكِبَانِ عَنِ الْحَقِّ مَا دَامَا عَلَى صُرَامِهِمَا، وَأَوَّلُهُمَا فَيْئًا فَسَبْقُهُ بِالْفَيْءِ، كَفَّارَتُهُ، فَإِنْ سَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ، وَرَدَّ عَلَيْهِ سَلَامَهُ رَدَّتْ عَلَيْهِ الْمَلَائِكَةُ، وَرَدَّ عَلَى الْآخَرِ الشَّيْطَانُ، فَإِنْ مَاتَا عَلَى صُرَامِهِمَا لَمْ يَجْتَمِعَا فِي الْجَنَّةِ أَبَدًا."],"takhrij":"صحيح: رواه أحمد (16257)، والبخاري في الأدب المفرد (402، 407)، وصحّحه ابن حبان (5664) كلهم من طرق عن يزيد، عن معاذة العدوية قالت: سمعت هشام بن عامر قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16257), al-Bukhārī in al-Adab al-Mufrad (402, 407), and authenticated by Ibn Ḥibbān (5664).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Hishām ibn ʿĀmir narrated: I heard the Messenger of Allah ﷺ say: “It is not lawful for a Muslim to boycott another Muslim for more than three nights. If their severance continues beyond three, then both of them have deviated from the truth for as long as they remain estranged. The first of them to return and reconcile has that initiative as an expiation for him. If he gives salām to the other but the other does not return it, the angels return his salām, while Satan responds to the other. If they both die while persisting in their severance, they will never be together in Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16257)، والبخاري في الأدب المفرد (402، 407)، وصححه ابن حبان (5664)."},{"num":14940,"demo":false,"sanad":"","matn":["عَنْ أَبِي خِرَاشٍ السُّلَمِيِّ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ هَجَرَ أَخَاهُ سَنَةً فَهُوَ كَسَفْكِ دَمِهِ."],"takhrij":"صحيح: رواه أبو داود (4915)، وأحمد (17935)، وصحّحه الحاكم (7292) كلهم من طرق عن حيوة، عن أبي عثمان الوليد بن أبي الوليد، عن عمران بن أبي أنس، عن أبي خراش السلمي فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم الهجر فوق ثلاث بلا عذر شرعي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4915), Aḥmad (17935), and authenticated by al-Ḥākim (7292).","chapter_en":"The Prohibition of Boycotting a Muslim for More than Three Days without a Legitimate Religious Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":19,"content":{"translation":{"en":["Abū Khirāsh al-Sulamī narrated that he heard the Messenger of Allah ﷺ say: “Whoever boycotts his brother for a year, it is like shedding his blood.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4915)، وأحمد (17935)، وصححه الحاكم (7292)."},{"num":14941,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  كَفَى بِالْمَرْءِ كَذِبًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ."],"takhrij":"صحيح: رواه مسلم في المقدمة (5) متصلا عن أبي بكر بن أبي شيبة، حدثنا علي بن حفص، حدثنا شعبة، عن خبيب بن عبد الرحمن، عن حفص بن عاصم، عن أبي هريرة فذكره. وهذه الرواية الثانية عند مسلم.","grade":"صحيح","chapter_ar":"باب النهي عن الحديث بكل ما يسمع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Introduction (5) and Abū Dāwūd (4992).","chapter_en":"The Prohibition of Relating Everything One Hears","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “It is enough of a lie for a person to relate everything he hears.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1275],"tks":"صحيح: رواه مسلم (5)، وأبو داود (4992)."},{"num":14942,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (48)، ومسلم في الإيمان (64) كلاهما من حديث شعبة، عن زُبيد، عن أبي وائل، عن عبدالله بن مسعود، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (48) and Muslim (64).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Prophet ﷺ said: “Insulting a Muslim is wickedness, and fighting him is kufr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (48)، ومسلم (64)."},{"num":14943,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قِتَالُ المسلم كُفْرٌ، وَسِبَابُهُ فُسُوقٌ، وَلا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاثَةِ أَيَّامٍ."],"takhrij":"حسن: رواه النسائي (4104)، وأحمد (1519) كلاهما من حديث عبدالرزاق –وهو في مصنفه (20224)- قال: أخبرنا معمر، عن أبي إسحاق، عن عمر بن سعد، حدثنا سعد بن أبي وقاص فذكره.","grade":"حسن","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (4104) and Aḥmad (1519).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Messenger of Allah ﷺ said: “Fighting a Muslim is kufr, insulting him is wickedness, and it is not lawful for a Muslim to boycott his brother for more than three days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4104)، وأحمد (1519)."},{"num":14944,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ."],"takhrij":"حسن: رواه ابن ماجه (3940) عن أبي بكر بن أبي شيبة قال: حدثنا محمد بن الحسن الأسدي قال: حدثنا أبو هلال، عن ابن سيرين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3940).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Insulting a Muslim is wickedness, and fighting him is kufr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3940)."},{"num":14945,"demo":false,"sanad":"","matn":["عن أنس، عن النبي صلى الله عليه وسلم قال: سباب المسلم فسوق، وقتاله كفر."],"takhrij":"حسن: رواه المروزي في تعظيم قدر الصلاة (1104) عن علي بن الحسن بن أبي عيسى، حدثنا المقرئ، حدثنا ابن لهيعة، حدثني يزيد بن أبي حبيب، عن سنان بن سعد الكندي، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Marwazī in Taʿẓīm Qadr al-Ṣalāh (1104).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “Insulting a Muslim is wickedness, and fighting him is kufr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه المروزي في تعظيم قدر الصلاة (1104)."},{"num":14946,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الْمُسْتَبَّانِ مَا قَالَا، فَعَلَى الْبَادِئِ مَا لَمْ يَعْتَدِ الْمَظْلُومُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2587) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2587).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whatever two people who insult one another say, the sin of it falls upon the one who began it, so long as the wronged person does not exceed the limit.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2587)."},{"num":14947,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُسْتَبَّانِ مَا قَالاَ، فَعَلَى الْبَادِئِ، حَتَّى يَعْتَدِيَ الْمَظْلُومُ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (424) عن أحمد بن عيسى، قال: حدثنا ابن وهب قال: أخبرني عمرو بن الحارث، عن يزيد بن أبي حبيب، عن سنان بن سعد، عن أنس بن مالك قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من السباب والقتال","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (424).","chapter_en":"Warning against Insulting and Fighting","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Whatever two people who insult one another say, the burden falls upon the one who began it until the wronged person exceeds the limit.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (424)."},{"num":14948,"demo":false,"sanad":"","matn":["عَنْ عِيَاضِ بْنِ حِمَارٍ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، الرَّجُلُ مِنْ قَوْمِي يَشْتُمُنِي وَهُوَ دُونِي؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُسْتَبَّانِ شَيْطَانَانِ يَتَهَاتَرَانِ وَيَتَكَاذَبَانِ، فَمَا قَالَا فَهُوَ عَلَى الْبَادِئِ حَتَّى يَعْتَدِيَ الْمَظْلُومُ."],"takhrij":"صحيح: رواه أبو داود الطيالسي (1176)- ومن طريقه البيهقي (21087)- وأحمد (17486- 17488) كلاهما من طرق عن همام، عن قتادة، عن يزيد بن عبد الله بن الشخير، عن عياض بن حمار فذكره. والسياق للطيالسي.","grade":"صحيح","chapter_ar":"باب ما جاء أن المستبين من الشيطان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd al-Ṭayālisī (1176), and through him al-Bayhaqī (10/235), and Aḥmad (17486, 17488).","chapter_en":"What Has Been Narrated That Two People Trading Insults Are from Satan","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":22,"content":{"translation":{"en":["ʿIyāḍ ibn Ḥimār narrated: I said: “O Messenger of Allah, what about a man from my people who insults me even though he is beneath me in status?” The Messenger of Allah ﷺ said: “The two people who exchange insults are two devils, speaking recklessly and lying against one another. Whatever they say is upon the one who began it, until the wronged person exceeds the limit.”"]},"buhuth":{"en":["The expression “yatahātarān wa-yatakādhabān” means that they exchange reckless, shameless, and false speech with one another. It derives from al-hatr, meaning false and worthless speech."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود الطيالسي (1176)، ومن طريقه البيهقي (21087)، وأحمد (17486، 17488)."},{"num":14949,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَسُبُّوا الأَمْوَاتَ، فَتُؤْذُوا الأَحْيَاءَ."],"takhrij":"صحيح: رواه الترمذي (1982)، وصحّحه ابن حبان (3022) من طريق أبي داود الحفري-، وأحمد (18209) من طريق أبي نعيم الفضل بن دكين- كلاهما من طريق سفيان الثوري، عن زياد بن عِلاقة قال: سمعت المغيرة بن شعبة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن سب الأموات","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1982) and authenticated by Ibn Ḥibbān (3022).","chapter_en":"The Prohibition of Insulting the Dead","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":23,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated that the Messenger of Allah ﷺ said: “Do not insult the dead, for by doing so you hurt the living.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3648],"tks":"صحيح: رواه الترمذي (1982)، وصححه ابن حبان (3022)."},{"num":14950,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا يَنْبَغِي لِصِدِّيقٍ أَنْ يَكُونَ لَعَّانًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2597) من طرق عن العلاء بن عبد الرحمن، حدثه عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2597).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “It is not fitting for a person of utmost truthfulness to be someone who frequently curses.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2597)."},{"num":14951,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ يَكُنِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبَّابًا، وَلاَ فَحَّاشًا، وَلاَ لَعَّانًا، كَانَ يَقُولُ لأَحَدِنَا عِنْدَ الْمَعْتَبَةِ: مَا لَهُ، تَرِبَ جَبِينُهُ."],"takhrij":"صحيح: رواه البخاري في الأدب (6031) عن أصبغ، قال: أخبرني ابن وهب، أخبرنا أبو يحيى هو فليح بن سليمان، عن هلال بن أسامة، عن أنس بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6031).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ was neither abusive, obscene in speech, nor one who frequently cursed. When reproaching one of us, he would merely say: “What is the matter with him? May dust be upon his forehead.”"]}},"tuhfa":{},"full":1,"rep":[13238],"tks":"صحيح: رواه البخاري (6031)."},{"num":14952,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، سَمِعْتُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَكُونُ اللَّعَّانُونَ شُفَعَاءَ، وَلَا شُهَدَاءَ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2598: 85) عن سويد بن سعيد، حدثني حفص بن ميسرة، عن زيد بن أسلم، أن عبد الملك بن مروان، بعث إلى أم الدرداء بأنجاد من عنده، فلما أن كان ذات ليلة، قام عبد الملك من الليل، فدعا خادمه، فكأنه أبطأ عليه، فلعنه، فلما أصبح قالت له أم الدرداء: سمعتك الليلة، لعنت خادمك حين دعوته، فقالت: سمعت أبا الدرداء يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2598:85).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Abū al-Dardāʾ narrated: I heard the Messenger of Allah ﷺ say: “Those who frequently curse will not be intercessors or witnesses on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2598: 85)."},{"num":14953,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قِيلَ:  يَا رَسُولَ اللَّهِ ادْعُ عَلَى الْمُشْرِكِينَ قَالَ: إِنِّي لَمْ أُبْعَثْ لَعَّانًا، وَإِنَّمَا بُعِثْتُ رَحْمَةً."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2599) من طرق عن مروان الفزاري، عن يزيد وهو ابن كيسان، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2599).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated: It was said: “O Messenger of Allah, supplicate against the polytheists.” He replied: “I was not sent as one who curses. I was only sent as a mercy.”"]}},"tuhfa":{},"full":1,"rep":[12766],"tks":"صحيح: رواه مسلم (2599)."},{"num":14954,"demo":false,"sanad":"","matn":["عن ثابت بن الضَّحَّاكِ-وَكَانَ من أَصْحَابِ الشَّجَرَةِ- حَدَّثَهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ حَلَفَ عَلَى مِلَّةٍ غَيْرِ الإِسْلاَمِ فَهْوَ كَمَا قَالَ، وَلَيْسَ عَلَى ابْنِ آدَمَ نَذْرٌ فِيمَا لاَ يَمْلِكُ، وَمَنْ قَتَلَ نَفْسَهُ بِشَىْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ، وَمَنْ لَعَنَ مُؤْمِنًا فَهْوَ كَقَتْلِهِ، وَمَنْ قَذَفَ مُؤْمِنًا بِكُفْرٍ فَهْوَ كَقَتْلِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6047)، ومسلم في الإيمان (110) كلاهما من طريق يحيى بن أبي كثير، عن أبي قلابة: أن ثابت بن الضحاك فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6047) and Muslim (110).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Thābit ibn al-Ḍaḥḥāk—who was among the Companions who pledged allegiance beneath the tree—narrated that the Messenger of Allah ﷺ said: “Whoever swears by a religion other than Islam is as he has said. A son of Ādam has no binding vow concerning something he does not own. Whoever kills himself with something in this world will be punished with it on the Day of Resurrection. Whoever curses a believer is like one who kills him, and whoever accuses a believer of disbelief is like one who kills him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7089],"tks":"متفق عليه: رواه البخاري (6047)، ومسلم (110)."},{"num":14955,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْمُؤْمِنَ لَيْسَ بِاللَّعَّانِ، وَلَا الطَّعَّانِ، وَلَا الْفَاحِشِ، وَلَا الْبَذِيءِ."],"takhrij":"حسن: رواه أحمد (3948)، والبخاري في الأدب المفرد (312)، وصحّحه ابن حبان (192)، والحاكم (30) كلهم من طرق عن أبي بكر بن عياش، عن الحسن بن عمرو الفقيمي، عن محمد بن عبد الرحمن بن يزيد، عن أبيه، عن عبد الله قال: فذكره. وإسناده حسن من أجل أبي بكر بن عياش فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3948), al-Bukhārī in al-Adab al-Mufrad (312), authenticated by Ibn Ḥibbān (192), and al-Ḥākim (1/12).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The believer is not one who curses others, attacks people’s honor, speaks obscenely, or uses foul language.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أحمد (3948)، والبخاري في الأدب المفرد (312)، وصححه ابن حبان (192)، والحاكم (30)."},{"num":14956,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَنْبَغِي لِلْمُؤْمِنِ أَنْ يَكُونَ لِعَانًا."],"takhrij":"حسن: رواه الترمذي (2019)، والبخاري في الأدب المفرد (309)، وصحّحه الحاكم (146) كلهم من طريق كثير بن زيد، عن سالم بن عبد الله، عن أبيه عبد الله بن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2019), al-Bukhārī in al-Adab al-Mufrad (309), and authenticated by al-Ḥākim (145).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “It is not fitting for a believer to be someone who frequently curses.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2019)، والبخاري في الأدب المفرد (309)، وصححه الحاكم (145)."},{"num":14957,"demo":false,"sanad":"","matn":["عَنْ الْعَيْزَارِ بْنِ جَرْوَلٍ الْحَضْرَمِيِّ، عَنْ رَجُلٍ مِنْهُمْ يُكْنَى أَبَا عُمَيْرٍ، أَنَّهُ كَانَ صَدِيقًا لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ، وَإِنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ، زَارَهُ فِي أَهْلِهِ، فَلَمْ يَجِدْهُ، قَالَ: فَاسْتَأْذَنَ عَلَى أَهْلِهِ، وَسَلَّمَ، فَاسْتَسْقَى، قَالَ: فَبَعَثَتِ الْجَارِيَةَ تَجِيئُهُ بِشَرَابٍ مِنَ الْجِيرَانِ، فَأَبْطَأَتْ، فَلَعَنَتْهَا، فَخَرَجَ عَبْدُ اللَّهِ، فَجَاءَ أَبُو عُمَيْرٍ، فَقَالَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، لَيْسَ مِثْلُكَ يُغَارُ عَلَيْهِ، هَلَّا سَلَّمْتَ عَلَى أَهْلِ أَخِيكَ، وَجَلَسْتَ، وَأَصَبْتَ مِنَ الشَّرَابِ؟ قَالَ: قَدْ فَعَلْتُ، فَأَرْسَلَتِ الْخَادِمَ، فَأَبْطَأَتْ، إِمَّا لَمْ يَكُنْ عِنْدَهُمْ، وَإِمَّا رَغِبُوا فِيمَا عِنْدَهُمْ، فَأَبْطَأَتِ الْخَادِمُ، فَلَعَنَتْهَا، وَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّ اللَّعْنَةَ إِذَا وُجِّهَتْ إِلَى مَنْ وُجِّهَتْ إِلَيْهِ، فَإِنْ أَصَابَتْ عَلَيْهِ سَبِيلًا، أَوْ وَجَدَتْ فِيهِ مَسْلَكًا، وَإِلَّا قَالَتْ: يَا رَبِّ، وُجِّهْتُ إِلَى فُلَانٍ، فَلَمْ أَجِدْ عَلَيْهِ سَبِيلًا، وَلَمْ أَجِدْ فِيهِ مَسْلَكًا، فَيُقَالُ لَهَا: ارْجِعِي مِنْ حَيْثُ جِئْتِ، فَخَشِيتُ أَنْ تَكُونَ الْخَادِمُ مَعْذُورَةً، فَتَرْجِعَ اللَّعْنَةُ، فَأَكُونَ سَبَبَهَا."],"takhrij":"حسن: رواه أحمد (3876) عن وكيع، حدثنا عمر بن ذر، عن العيزار بن جرول الحضرمي فذكره.","grade":"حسن","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3876).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Al-ʿAyzār ibn Jarwal al-Ḥaḍramī narrated from a man of his people known as Abū ʿUmayr, who was a friend of ʿAbdullāh ibn Masʿūd: ʿAbdullāh ibn Masʿūd once visited him at his home but did not find him there. He sought permission from his family, greeted them with salām, and asked for something to drink. The woman of the house sent a servant girl to bring him a drink from the neighbors, but she was delayed, so the woman cursed her. ʿAbdullāh then left. When Abū ʿUmayr returned, he said: “O Abū ʿAbd al-Raḥmān, someone like you should not be made to feel unwelcome. Why did you not greet your brother’s family, sit down, and have something to drink?” He replied: “I did. She sent the servant girl, but she was delayed. Perhaps they had nothing, or perhaps the neighbors were reluctant to give what they had. When the servant girl was delayed, she cursed her.” Then he said: I heard the Messenger of Allah ﷺ say: “When a curse is directed toward someone, if it finds a valid path to him, or finds something in him that deserves it, then it reaches him. Otherwise it says: ‘My Lord, I was directed toward so-and-so, but I found no path to him and found nothing in him deserving it.’ It is then told: ‘Return from where you came.’” ʿAbdullāh said: “So I feared that the servant girl might have had a valid excuse, and that the curse would return, with me being the cause of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (3876)."},{"num":14958,"demo":false,"sanad":"","matn":["عَنْ جُرْمُوزَ الْهُجَيْمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَوْصِنِي، قَالَ: أُوصِيكَ أَنْ لَا تَكُونَ لَعَّانًا."],"takhrij":"صحيح: رواه أحمد (20678)، وابن أبي عاصم في الآحاد والمثاني (1189)، والطبراني في الكبير (2180) كلهم من حديث عبدالصمد بن عبد الوارث، حدثني عبيدالله بن هوذة القريعي، حدثني رجل أنه سمع جرموز الهجيمي فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (20678), Ibn Abī ʿĀṣim in al-Āḥād wa-al-Mathānī (1189), and al-Ṭabarānī in al-Muʿjam al-Kabīr (2/283).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Jarmūz al-Hujaymī narrated: I said: “O Messenger of Allah, advise me.” He replied: “I advise you not to be one who frequently curses.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20678)، وابن أبي عاصم في الآحاد والمثاني (1189)، والطبراني في الكبير (2180)."},{"num":14959,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ، أَنْ رَجُلاً لَعَنَ الرِّيحَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لاَ تَلْعَنِ الرِّيحَ فَإِنَّهَا مَأْمُورَةٌ، وَإِنَّهُ مَنْ لَعَنَ شَيْئًا لَيْسَ لَهُ بِأَهْلٍ رَجَعَتِ اللَّعْنَةُ عَلَيْهِ."],"takhrij":"صحيح: رواه أبو داود (4908)، والترمذي (1978)، وصحّحه ابن حبان (5745) كلهم من طريق بشر بن عمر، حدثنا أبان بن يزيد، عن قتادة، عن أبي العالية، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4908), al-Tirmidhī (1978), and authenticated by Ibn Ḥibbān (5745).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: A man cursed the wind in the presence of the Prophet ﷺ. The Prophet ﷺ said: “Do not curse the wind, for it is commanded. Whoever curses something that does not deserve the curse, the curse returns upon him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4908)، والترمذي (1978)، وصححه ابن حبان (5745)."},{"num":14960,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْعَبْدَ إِذَا لَعَنَ شَيْئًا صَعِدَتِ اللَّعْنَةُ إِلَى السَّمَاءِ فَتُغْلَقُ أَبْوَابُ السَّمَاءِ دُونَهَا، ثُمَّ تَهِبْطُ إِلَى الأَرْضِ فَتُغْلَقُ أَبْوَابُهَا دُونَهَا، ثُمَّ تَأْخُذُ يَمِينًا وَشِمَالاً، فَإِذَا لَمْ تَجِدْ مَسَاغًا رَجَعَتْ إِلَى الَّذِي لُعِنَ، فَإِنْ كَانَ لِذَلِكَ أَهْلاً وَإِلاَّ رَجَعَتْ إِلَى قَائِلِهَا."],"takhrij":"حسن: رواه أبو داود (4905)، وابن أبي الدنيا في الصمت (384) كلاهما من طريق يحيى بن حسان، حدثنا الوليد بن رباح، سمعت نمران يذكر عن أم الدرداء قالت: سمعت أبا الدرداء يقول: فذكره.","grade":"حسن","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4905) and Ibn Abī al-Dunyā in al-Ṣamt (384).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Messenger of Allah ﷺ said: “When a servant curses something, the curse rises toward the sky, but the gates of the sky are closed before it. It then descends toward the earth, but its gates are closed before it. It then turns to the right and to the left. If it finds no place to go, it returns to the one who was cursed. If that person deserves it, it reaches him; otherwise, it returns to the one who uttered it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4905)، وابن أبي الدنيا في الصمت (384)."},{"num":14961,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَلاَعَنُوا بِلَعْنَةِ اللَّهِ، وَلاَ بِغَضَبِ اللَّهِ، وَلاَ بِالنَّارِ."],"takhrij":"صحيح: رواه أبو داود (4906)، والترمذي (1976)، وأحمد (20175)، والبخاري في الأدب المفرد (320)، وصحّحه الحاكم (150) كلهم من طرق عن قتادة، عن الحسن، عن سمرة قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في ذم اللعن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4906), al-Tirmidhī (1976), Aḥmad (20175), and al-Bukhārī in al-Adab al-Mufrad (320).","chapter_en":"Condemnation of Cursing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":24,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “Do not curse one another with the curse of Allah, nor with the wrath of Allah, nor with the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4906)، والترمذي (1976)، وأحمد (20175)، والبخاري في الأدب المفرد (320)."},{"num":14962,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، وَأَبِي هُرَيْرَةَ قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الْعِزُّ إِزَارُهُ، وَالْكِبْرِيَاءُ رِدَاؤُهُ، فَمَنْ يُنَازِعُنِي عَذَّبْتُهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2620) عن أحمد بن يوسف الأزدي، حدثنا عمر بن حفص بن غياث، حدثنا أبي، حدثنا الأعمش، حدثنا أبو إسحاق، عن أبي مسلم الأغر، أنه حدثه عن أبي سعيد الخدري، وأبي هريرة قالا: فذكراه.","grade":"صحيح","chapter_ar":"باب التحذير من التعلي على اللّٰه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2620).","chapter_en":"Warning against Exalting Oneself in Rivalry with Allah","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":25,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī and Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Might is His lower garment, and greatness is His cloak; whoever contends with Me regarding them, I will punish him.”"]},"buhuth":{"en":["Regarding the words, “Might is His lower garment, and greatness is His cloak; whoever contends with Me regarding them, I will punish him,” al-Nawawī said:","This is how it appears in all the manuscripts. The pronouns in “His lower garment” and “His cloak” refer to Allah, the Exalted, as this is understood from the context.","There is an omitted phrase whose intended meaning is: Allah, the Exalted, says, “Whoever contends with Me regarding that, I will punish him.”","The meaning of “contends with Me” is that a person adopts these qualities for himself in such a way that he becomes, in meaning, like one claiming a share in them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13262],"tks":"صحيح: رواه مسلم (2620)."},{"num":14963,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، - قَالَ هَنَّادٌ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: الْكِبْرِيَاءُ رِدَائِي، وَالْعَظَمَةُ إِزَارِي، فَمَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا قَذَفْتُهُ فِي النَّارِ."],"takhrij":"صحيح: رواه أبو داود (4090)، وابن حبان (5671) من طريق حماد بن سلمة- ورواه أحمد (8894) من طريق سفيان (وهو ابن عيينة) – كلاهما عن عطاء بن السائب، عن سلمان الأغر، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من التعلي على اللّٰه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4090), Ibn Ḥibbān (5671), and Aḥmad (8894).","chapter_en":"Warning against Exalting Oneself in Rivalry with Allah","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said that Allah, Mighty and Majestic, says: “Greatness is My cloak, and majesty is My lower garment. Whoever contends with Me regarding either of them, I will cast him into the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4090)، وابن حبان (5671)، وأحمد (8894)."},{"num":14964,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ. قَالَ رَجُلٌ: إِنَّ الرَّجُلَ يُحِبُّ أَنْ يَكُونَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً. قَالَ: إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ، الْكِبْرُ بَطَرُ الْحَقِّ، وَغَمْطُ النَّاسِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (91: 147) من طريق فضيل الفقيمي، عن إبراهيم، عن علقمة، عن عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (91:147).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “No one who has an atom’s weight of arrogance in his heart will enter Paradise.” A man said: “A man likes his clothes to be good and his sandals to be good.” The Prophet ﷺ replied: “Indeed, Allah is Beautiful and loves beauty. Arrogance is rejecting the truth and looking down upon people.”"]}},"tuhfa":{},"full":1,"rep":[102],"tks":"صحيح: رواه مسلم (91: 147)."},{"num":14965,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَا يَدْخُلُ النَّارَ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ حَبَّةِ خَرْدَلٍ مِنْ إِيمَانٍ، وَلَا يَدْخُلُ الْجَنَّةَ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ حَبَّةِ خَرْدَلٍ مِنْ كِبْرِيَاءَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (91: 148) من طرق عن علي بن مسهر، عن الأعمش، عن إبراهيم، عن علقمة، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (91:148).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “No one who has a mustard seed’s weight of faith in his heart will enter the Fire, and no one who has a mustard seed’s weight of arrogance in his heart will enter Paradise.”"]},"buhuth":{"en":["Al-Tirmidhī (1999) said:","Some of the scholars explained the hadith, “No one who has an atom’s weight of faith in his heart will enter the Fire,” to mean that he will not remain eternally in the Fire.","This is also narrated from Abū Saʿīd al-Khudrī, from the Prophet ﷺ:","“Whoever has an atom’s weight of faith in his heart will be brought out of the Fire.”","More than one of the Tābiʿīn also explained the verse:","“Our Lord, indeed whoever You admit into the Fire, You have disgraced him, and the wrongdoers will have no helpers.”","[Sūrat Āl ʿImrān 3:192]","to mean:","“Whoever You leave eternally in the Fire, You have disgraced him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (91: 148)."},{"num":14966,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَكَانَ رَجُلاً جَمِيلاً، - فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي رَجُلٌ حُبِّبَ إِلَىَّ الْجَمَالُ، وَأُعْطِيتُ مِنْهُ مَا تَرَى، حَتَّى مَا أُحِبُّ أَنْ يَفُوقَنِي أَحَدٌ، - إِمَّا قَالَ: بِشِرَاكِ نَعْلِي. وَإِمَّا قَالَ: بِشِسْعِ نَعْلِي، - أَفَمِنَ الْكِبْرِ ذَلِكَ؟ قَالَ لاَ، وَلَكِنَّ الْكِبْرَ مَنْ بَطَرَ الْحَقَّ، وَغَمَطَ النَّاسَ."],"takhrij":"صحيح: رواه أبو داود (4092)، والبخاري في الأدب المفرد (556)، وصحّحه ابن حبان (5467)، والحاكم (7366) كلهم من طريق هشام بن حسان، عن محمد بن سيرين، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4092), al-Bukhārī in al-Adab al-Mufrad (556), and authenticated by Ibn Ḥibbān (5467).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah narrated: A handsome man came to the Prophet ﷺ and said: “O Messenger of Allah, beauty has been made beloved to me, and I have been given of it what you see. I do not even like anyone to surpass me”—either he said—“in the strap of my sandal,” or, “in the lace of my sandal. Is that arrogance?” The Prophet ﷺ replied: “No. Rather, arrogance is rejecting the truth and looking down upon people.”"]},"buhuth":{"en":["The expression “looking down upon people” means belittling them, treating them with contempt, and considering them insignificant.","The expression “rejecting the truth” means refusing and denying it out of pride and haughtiness."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15295],"tks":"صحيح: رواه أبو داود (4092)، والبخاري في الأدب المفرد (556)، وصححه ابن حبان (5467)."},{"num":14967,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بن الأكوع، أَنَّ رَجُلًا أَكَلَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِمَالِهِ، فَقَالَ: كُلْ بِيَمِينِكَ، قَالَ: لَا أَسْتَطِيعُ، قَالَ: لَا اسْتَطَعْتَ، مَا مَنَعَهُ إِلَّا الْكِبْرُ، قَالَ: فَمَا رَفَعَهَا إِلَى فِيهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2021) عن أبي بكر بن أبي شيبة، حدثنا زيد بن الحباب، عن عكرمة بن عمار، حدثني إياس بن سلمة بن الأكوع، أن أباه، حدثه فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2021).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ narrated: A man ate with his left hand in the presence of the Messenger of Allah ﷺ. The Prophet ﷺ said: “Eat with your right hand.” The man replied: “I cannot.” The Prophet ﷺ said: “May you not be able to.” Nothing prevented him except arrogance. Salamah said: “After that, he was never able to raise that hand to his mouth.”"]},"buhuth":{"en":["His words “I cannot” were said out of arrogance, as the context indicates.","The words of the Prophet ﷺ, “May you not be able to,” were a supplication against him, and what he supplicated for came to pass."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14312],"tks":"صحيح: رواه مسلم (2021)."},{"num":14968,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، قَالَ: الْتَقَى عَبْدُ اللَّهِ بْنُ عُمَرَ وَعَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِي عَلَى الْمَرْوَةِ، فَتَحَدَّثَا، ثُمَّ مَضَى عَبْدُ اللَّهِ بْنُ عَمْرٍو، وَبَقِيَ عَبْدُ اللَّهِ بْنُ عُمَرَ يَبْكِي، فَقَالَ لَهُ رَجُلٌ: مَا يُبْكِيكَ يَا أَبَا عَبْدِ الرَّحْمَنِ؟ قَالَ: - هَذَا يَعْنِي عَبْدَ اللَّهِ بْنَ عَمْرٍو: - زَعَمَ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ كِبْرٍ، أَكَبَّهُ اللهُ عَلَى وَجْهِهِ فِي النَّارِ."],"takhrij":"حسن: رواه أحمد (7015)، وابن أبي الدنيا في التواضع (196) كلاهما من حديث مروان بن شجاع أبي عمرو الجزري، حدثني إبراهيم بن أبي عبلة العقيلي من أهل بيت المقدس، عن أبي سلمة بن عبد الرحمن قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7015) and Ibn Abī al-Dunyā in al-Tawāḍuʿ (196).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["Abū Salamah ibn ʿAbd al-Raḥmān narrated: ʿAbdullāh ibn ʿUmar and ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ met at al-Marwah and spoke together. Then ʿAbdullāh ibn ʿAmr went on, while ʿAbdullāh ibn ʿUmar remained behind weeping. A man asked him: “Why are you crying, O Abū ʿAbd al-Raḥmān?” He replied: “This man”—meaning ʿAbdullāh ibn ʿAmr—“claims that he heard the Messenger of Allah ﷺ say: ‘Whoever has a mustard seed’s weight of arrogance in his heart, Allah will cast him face-first into the Fire.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7015)، وابن أبي الدنيا في التواضع (196)."},{"num":14969,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سمعت رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقول: مَنْ تَعَظَّمَ فِي نَفْسِهِ أَوْ اخْتَالَ فِي مِشْيَتِهِ لَقِيَ الله وَهُوَ عَلَيْهِ غَضْبَانُ."],"takhrij":"صحيح: رواه الإمام أحمد (5995)، والبخاري في الأدب المفرد (549) كلاهما من طريقين عن يونس بن القاسم الحنفي اليمامي، قال: سمعت عكرمة بن خالد المخزومي، يقول: سمعت ابن عمر يقول فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من الكبر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Imām Aḥmad (5995) and al-Bukhārī in al-Adab al-Mufrad (549).","chapter_en":"Warning against Arrogance","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":26,"content":{"translation":{"en":["Ibn ʿUmar narrated: I heard the Messenger of Allah ﷺ say: “Whoever considers himself great or walks arrogantly will meet Allah while He is angry with him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5995)، والبخاري في الأدب المفرد (549)."},{"num":14970,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ: شَيْخٌ زَانٍ، ومَلِك كَذَّابٌ، وَعَائِلٌ مُسْتَكْبِرٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (107) من طريق الأعمش، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم المستكبرين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (107).","chapter_en":"What Has Been Narrated Concerning the Condemnation of the Arrogant","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":27,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There are three whom Allah will not speak to on the Day of Resurrection, nor purify them, and for them is a painful punishment: an elderly adulterer, a lying ruler, and an arrogant poor man.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (107)."},{"num":14971,"demo":false,"sanad":"","matn":["عن سَلْمَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثَةٌ لَا يَدْخُلُونَ الْجَنَّةَ: الشَّيْخُ الزَّانِي، وَالْإِمَامُ الْكَذَّابُ، وَالْعَائِلُ الْمَزْهُوُّ."],"takhrij":"حسن: رواه البزار (2529) عن العباس بن أبي طالب، قال: أخبرنا منجاب بن الحارث، قال: أخبرنا حفص بن غياث، عن عاصم (هو الأحول)، عن أبي عثمان، عن سلمان فذكره. وإسناده حسن من أجل العباس بن أبي طالب، وهو العباس بن جعفر بن عبدالله البغدادي صدوق.","grade":"حسن","chapter_ar":"باب ما جاء في ذم المستكبرين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (2529).","chapter_en":"What Has Been Narrated Concerning the Condemnation of the Arrogant","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":27,"content":{"translation":{"en":["Salmān narrated that the Messenger of Allah ﷺ said: “Three will not enter Paradise: an elderly adulterer, a lying leader, and an impoverished man who is conceited and arrogant.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (2529)."},{"num":14972,"demo":false,"sanad":"","matn":["عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أُخْبِرُكُمْ بِأَهْلِ الْجَنَّةِ، كُلُّ ضَعِيفٍ مُتَضَاعِفٍ، لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ، أَلاَ أُخْبِرُكُمْ بِأَهْلِ النَّارِ؟ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6071)، ومسلم في الجنة (2853) كلاهما من طريق معبد بن خالد القيسي، عن حارثة بن وهب الخزاعي، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ذم المستكبرين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6071) and Muslim (2853).","chapter_en":"What Has Been Narrated Concerning the Condemnation of the Arrogant","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":27,"content":{"translation":{"en":["Ḥārithah ibn Wahb al-Khuzāʿī narrated that the Prophet ﷺ said: “Shall I tell you who the people of Paradise are? Every weak person whom people regard as insignificant; if he were to swear by Allah, Allah would fulfill his oath. Shall I tell you who the people of the Fire are? Every harsh, arrogant, overbearing person.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16537],"tks":"متفق عليه: رواه البخاري (6071)، ومسلم (2853)."},{"num":14973,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم: حسبُ امرئ من الشر أن يحقر أخاه المسلم، كل المسلم على المسلم حرام، دمه، وماله، وعرضه."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2564: 32) عن عبد الله بن مسلمة بن قعنب، حدثنا داود يعني ابن قيس، عن أبي سعيد، مولى عامر بن كريز، عن أبي هريرة، قال: فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب التحذير من احتقار المسلم ولو كان من الضعفاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2564:32).","chapter_en":"Warning against Looking Down upon a Muslim Even If He Is among the Weak","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “It is enough evil for a person that he despise his Muslim brother. Everything belonging to a Muslim is sacred to another Muslim: his blood, his wealth, and his honor.”"]},"buhuth":{"en":["The meaning of the words “It is enough evil for a person” is that despising even one Muslim is sufficient as a grave evil in itself.","In other words, if one sought a single act sufficient to demonstrate serious evil, this alone would be enough, showing the enormity of the matter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2564: 32)."},{"num":14974,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  رُبَّ أَشْعَثَ، مَدْفُوعٍ بِالْأَبْوَابِ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2622) عن سويد بن سعيد، حدثني حفص بن ميسرة، عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من احتقار المسلم ولو كان من الضعفاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2622).","chapter_en":"Warning against Looking Down upon a Muslim Even If He Is among the Weak","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “How many a disheveled person, driven away from people’s doors, is such that if he were to swear by Allah, Allah would surely fulfill his oath.”"]}},"tuhfa":{},"full":1,"rep":[7059,13008,15119],"tks":"صحيح: رواه مسلم (2622)."},{"num":14975,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: عَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلا مِنَ الأَنْصَارِ، فَلَمَّا دَنَا مِنْ مَنْزِلِهِ، سَمِعَهُ يَتَكَلَّمُ فِي الدَّاخِلِ، فَلَمَّا اسْتَأْذَنَ عَلَيْهِ، دَخَلَ، فَلَمْ يَرَ أَحَدًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَمِعْتُكَ تُكَلِّمُ غَيْرَكَ. فَقَالَ: يَا رَسُولَ اللَّهِ! لَقَدْ دَخَلْتُ الدَّاخلَ اغْتِمَامًا مِنْ كَلامِ النَّاسِ مِمَّا بِي مِنَ الْحُمَّى، فَدَخَلَ عَلَيَّ رَجُلٌ، مَا رَأَيْتُ رَجُلًا قَطُّ بَعْدَكَ، أَكْرَمَ مَجْلِسًا، وَلا أَحْسَنَ حَدِيثًا وَقَالَ: ذَاكَ جِبْرِيلُ، وَإِنَّ مِنْكُمْ لَرِجَالًا، لَوْ أَنَّ أَحَدَهُمْ يُقْسِمُ عَلَى اللَّهِ لأَبَرَّهُ."],"takhrij":"حسن: رواه البزار –كشف الأستار (2811)، والطبراني في الكبير (12321)، وفي الأوسط –مجمع البحرين (3954) كلهم من طريق محمد بن عبدالوهاب الحارثي، حدثنا يعقوب القمي، عن جعفر بن أبي المغيرة، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من احتقار المسلم ولو كان من الضعفاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (3/306–307), and al-Ṭabarānī in al-Muʿjam al-Kabīr (12/11–12).","chapter_en":"Warning against Looking Down upon a Muslim Even If He Is among the Weak","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":28,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Messenger of Allah ﷺ visited a man from the Anṣār who was ill. As he approached his house, he heard him speaking to someone inside. When the Prophet ﷺ sought permission and entered, he saw no one there. The Messenger of Allah ﷺ said to him: “I heard you speaking to someone.” The man replied: “O Messenger of Allah, I entered the house distressed by what people were saying about the fever that has afflicted me. Then a man entered upon me. After you, I have never seen anyone more dignified in company or more pleasant in speech than him.” The Prophet ﷺ said: “That was Jibrīl. Indeed, among you are men such that if one of them were to swear by Allah, Allah would fulfill his oath.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار - كشف الأستار (2811)، والطبراني في الكبير (12264)."},{"num":14976,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ لَمْ تَكُونُوا تُذْنِبُونَ لَخَشِيتُ عَلَيْكُمْ مَا هُوَ أَكْبَرُ مِنْهُ، الْعُجْبَ."],"takhrij":"حسن: رواه البزار (6936) عن محمد بن عبد الملك القرشي، حدثنا سلام أبو المنذر، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن العجب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (6936).","chapter_en":"The Prohibition of Self-Admiration","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":29,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “If you did not commit sins, I would fear for you something even worse than that: self-admiration.”"]},"buhuth":{"en":["The meaning of the hadith is that the human being was created with a tendency toward error and forgetfulness.","Were it not for that, he could fall into self-admiration, which is among the gravest sins.","The hadith does not contain any encouragement to commit sins or acts of disobedience."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (6936)."},{"num":14977,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى:  أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلًا أَشْرَكَ فِيهِ مَعِي غَيْرِي، تَرَكْتُهُ وَشِرْكَهُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2985) عن زهير بن حرب، حدثنا إسماعيل بن إبراهيم، أخبرنا روح بن القاسم، عن العلاء بن عبد الرحمن بن يعقوب، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2985).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said that Allah, Blessed and Exalted, says: “I am the One who has no need whatsoever of partners. Whoever performs a deed in which he associates someone else with Me, I abandon him and his association.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2985)."},{"num":14978,"demo":false,"sanad":"","matn":["عَنْ جندب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ يُسَمِّعْ يُسَمِّعِ اللهُ بِهِ، وَمَنْ يُرَائِي يُرَائِي اللهُ بِهِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6499)، ومسلم في الزهد (2987) كلاهما من طرق عن سفيان، عن سلمة بن كهيل، قال: سمعت جندبا فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6499) and Muslim (2987).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Jundub narrated that the Messenger of Allah ﷺ said: “Whoever performs deeds so that people will hear of them, Allah will expose him; and whoever shows off, Allah will expose his showing off.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6499)، ومسلم (2987)."},{"num":14979,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ، وَمَنْ رَاءَى رَاءَى اللهُ بِهِ."],"takhrij":"صحيح: رواه مسلم في الزهد (2986) عن عمر بن حفص بن غياث، حدثني أبي، عن إسماعيل بن سميع، عن مسلم البطين، عن سعيد بن جبير، عن ابن عباس، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2986).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “Whoever seeks reputation through his deeds, Allah will expose him; and whoever shows off, Allah will expose his showing off.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2986)."},{"num":14980,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدِ بْنِ أَبِي فَضَالَةَ الْأَنْصَارِيِّ، وَكَانَ مِنَ الصَّحَابَةِ، أَنَّهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا جَمَعَ اللَّهُ عَزَّ وَجَلَّ الْأَوَّلِينَ، وَالْآخِرِينَ لِيَوْمٍ لَا رَيْبَ فِيهِ، نَادَى مُنَادٍ: مَنْ كَانَ أَشْرَكَ فِي عَمَلٍ عَمِلَهُ لِلَّهِ أَحَدًا، فَلْيَطْلُبْ ثَوَابَهُ مِنْ عِنْدِ غَيْرِ اللهِ عَزَّ وَجَلَّ، فَإِنَّ اللَّهَ أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ."],"takhrij":"حسن: رواه الإمام أحمد (15838) –والسياق له، والترمذي (3154)، وابن ماجه (4203)، وابن حبان (404) كلهم من طرقٍ عن محمد بن بكر البُرساني، أخبرنا عبدالحميد بن جعفر، أخبرنا أبي، عن زياد بن ميناء، عن أبي سعد بن أبي فضالة الأنصاري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (15838), and this is his wording, al-Tirmidhī (3154), Ibn Mājah (4203), and Ibn Ḥibbān (404).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Abū Saʿd ibn Abī Faḍālah al-Anṣārī, who was among the Companions, narrated: I heard the Messenger of Allah ﷺ say: “When Allah, Mighty and Majestic, gathers the first and the last for a Day about which there is no doubt, a caller will announce: ‘Whoever associated anyone with Allah, Blessed and Exalted, in a deed he performed, let him seek his reward from other than Allah, Mighty and Majestic. For Allah has absolutely no need of any partner.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15838) - والسياق له -، والترمذي (3154)، وابن ماجه (4203)، وابن حبان (404)."},{"num":14981,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ سمّع النَّاسَ بِعَمَلِهِ سمّع اللَّهُ بِهِ سَامِعَ خَلْقِهِ، وَصَغَّرَهُ وَحَقَّرَهُ."],"takhrij":"صحيح: رواه الطبراني في الكبير (14414)، وأبو نعيم في الحلية (911) كلاهما من طريق القاسم بن زكريا، قال: أعطاني عبد الرحيم بن محمد السكري كتابا، فكتبت منه: حدثنا عباد بن العوام، ثنا أبان بن تغلب، عن عمرو بن مرة، عن خيثمة، عن عبدالله بن عمرو فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (14414) and Abū Nuʿaym in Ḥilyat al-Awliyāʾ (4/123–124).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “Whoever publicizes his deeds so that people will hear of them, Allah will make the creation hear of him, and He will belittle and humiliate him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (14414)، وأبو نعيم في الحلية (911)."},{"num":14982,"demo":false,"sanad":"","matn":["عن أَبِي هند الداري أنه سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ قَامَ مَقَامَ رِيَاءٍ وَسُمْعَةٍ رَاءَى اللهُ بِهِ يَوْمَ الْقِيَامَةِ وَسَمَّعَ."],"takhrij":"حسن: رواه أحمد (22322)، والبزار –كشف الأستار (2026)، والطبراني في الكبير (22/ح 803) كلهم من طريق عبد الله بن يزيد المقرئ، حدثنا حيوة، حدثنا أبو صخر أنه سمع مكحولا يقول: حدثني أبو هند الداري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22322), al-Bazzār as cited in Kashf al-Astār (2026), and al-Ṭabarānī in al-Muʿjam al-Kabīr (22/319).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Abū Hind al-Dārī narrated that he heard the Messenger of Allah ﷺ say: “Whoever takes a position for the sake of showing off and seeking reputation, Allah, the Exalted, will expose his showing off and reputation-seeking on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22322)، والبزار في كشف الأستار (2026)، والطبراني في الكبير (22/ح 803)."},{"num":14983,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ، وَمَنْ رَاءَى رَاءَى اللهُ بِهِ."],"takhrij":"حسن: رواه أحمد (20456)، والبزار (3691) كلاهما من طريق بكار بن عبد العزيز، حدثني أبي (هو عبد العزيز بن أبي بكرة)، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20456) and al-Bazzār (3691).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Abū Bakrah narrated that the Messenger of Allah ﷺ said: “Whoever seeks reputation through his deeds, Allah will expose him; and whoever shows off, Allah will expose his showing off.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20456)، والبزار (3691)."},{"num":14984,"demo":false,"sanad":"","matn":["عن بشير بْنِ عَقْرَبَةَ الجهَنِيِّ قَالَ: إِنِّي سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ قَامَ يَخْطُبُ لَا يَلْتَمِسُ بِهَا إِلَّا رِيَاءً وَسُمْعَةً، أَوْقَفَهُ الله عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ مَوْقِفَ رِيَاءٍ وَسُمْعَةٍ."],"takhrij":"حسن: رواه الإمام أحمد (16073) عن سعيد بن منصور، -قال عبدالله: حدثناه أبي عنه وهو حيٌّ- قال: حدثنا حجر بن الحارث الغساني من أهل الرملة، عن عبد الله بن عون الكناني، -وكان عاملا لعمر بن عبد العزيز على الرملة- أنه شهد عبدالملك بن مروان قال: لبشير بن عقربة الجهني يوم قُتِلَ عمرو بنُ سعيد بنُ العاص يا أبا اليمان إني قد احتجتُ اليوم إلى كلامك، فقُمْ فتكلَّمْ قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (16073).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Bashīr ibn ʿAqrabah al-Juhanī narrated: I heard the Messenger of Allah ﷺ say: “Whoever stands to deliver a sermon seeking nothing through it except showing off and reputation, Allah, Mighty and Majestic, will make him stand on the Day of Resurrection in a position of showing off and reputation-seeking.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16073)."},{"num":14985,"demo":false,"sanad":"","matn":["عَنْ شداد بن أَوْسٍ قَالَ: كُنَّا نَعُدُّ الشِّرْكَ الأصغر عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرِّيَاءَ."],"takhrij":"حسن: رواه البزار –كشف الأستار (3565)، والطبراني في الأوسط –مجمع البحرين (4941) كلاهما من طريق سعيد بن الحكم بن أبي مريم، قال: نا يحيى بن أيوب، عن عمارة بن غزية، عن يعلى بن شداد بن أوس، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (3565), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (4941).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Shaddād ibn Aws narrated: “During the time of the Messenger of Allah ﷺ, we used to regard showing off as minor shirk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3565)، والطبراني في الأوسط في مجمع البحرين (4941)."},{"num":14986,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ لَبِيدٍ قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   فَقَالَ: أَيُّهَا النَّاسُ إِيَّاكُمْ وَشِرْكَ السَّرَائِرِ قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا شِرْكُ السَّرَائِرِ؟ قَالَ: يَقُومُ الرَّجُلُ فَيُصَلِّي، فَيُزَيِّنُ صَلَاتَهُ جَاهِدًا لِمَا يَرَى مِنْ نَظَرِ النَّاسِ إِلَيْهِ، فَذَلِكَ شِرْكُ السَّرَائِرِ.","وفي رواية: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ : إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ الشِّرْكُ الْأَصْغَرُ ، قَالُوا : وَمَا الشِّرْكُ الْأَصْغَرُ يَا رَسُولَ اللَّهِ ؟ قَالَ : الرِّيَاءُ ، يَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُمْ يَوْمَ الْقِيَامَةِ إِذَا جُزِيَ النَّاسُ بِأَعْمَالِهِمْ : اذْهَبُوا إِلَى الَّذِينَ كُنْتُمْ تُرَاءُونَ فِي الدُّنْيَا ، فَانْظُرُوا هَلْ تَجِدُونَ عِنْدَهُمْ جَزَاءً."],"takhrij":"صحيح: رواه ابن خزيمة (937)، وابن أبي شيبة (8489)، وأحمد (23631)، والبغوي في شرح السنة (4135)، والبيهقي في شعب الإيمان (6831) كلهم من طرق عن عاصم بن عمر بن قتادة، عن محمود بن لبيد فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (937), Ibn Abī Shaybah (8489), Aḥmad (23631), al-Baghawī in Sharḥ al-Sunnah (4135), and al-Bayhaqī in Shuʿab al-Īmān (6831).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Maḥmūd ibn Labīd narrated: The Prophet ﷺ came out and said: “O people, beware of hidden shirk.” They asked: “O Messenger of Allah, what is hidden shirk?” He replied: “A man stands to pray and exerts himself in beautifying his prayer because he sees people looking at him. That is hidden shirk.” In another narration, the Messenger of Allah ﷺ said: “The thing I fear most for you is minor shirk.” They asked: “O Messenger of Allah, what is minor shirk?” He replied: “Showing off. On the Day of Resurrection, when people are rewarded for their deeds, Allah, Mighty and Majestic, will say to them: ‘Go to those for whom you used to show off in the world and see whether you find any reward with them.’”"]}},"tuhfa":{},"full":1,"rep":[12031],"dr":1,"tks":"صحيح: رواه ابن خزيمة (937)، وابن أبي شيبة (8489)، وأحمد (23631)، والبغوي في شرح السنة (4135)، والبيهقي في شعب الإيمان (6831)."},{"num":14987,"demo":false,"sanad":"","matn":["عن عبد الله بن زيد الأنصاري قال: قال رسولُ الله صلى الله عليه وسلم:يا نعَايا العرب، ثلاثًا، إنّ أخوفَ ما أخافُ عليكم الرياءُ، والشهوةُ الخفيّةُ."],"takhrij":"حسن: رواه أبو يعلى كما في المطالب العالية (3222)، والبيهقي في الزهد (316) كلاهما من طريق عبد الله بن بُديل بن ورقاء الخزاعي، عن الزهري، عن عباد بن تميم، عن عمّه (هو عبد الله بن زيد بن عاصم الأنصاري) قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā, as cited in al-Maṭālib al-ʿĀliyah (3222), and al-Bayhaqī in al-Zuhd (316).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd al-Anṣārī narrated that the Messenger of Allah ﷺ said three times: “O heralds of the death of the Arabs! Indeed, what I fear most for you is showing off and hidden desire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى كما في المطالب العالية (3222)، والبيهقي في الزهد (316)."},{"num":14988,"demo":false,"sanad":"","matn":["عن شهر بن حوشب قَالَ ابْنُ غَنْمٍ: لَمَّا دَخَلْنَا مَسْجِدَ الْجَابِيَةِ أَنَا وَأَبُو الدَّرْدَاءِ لَقِينَا عُبَادَةَ بْنَ الصَّامِتِ، فَأَخَذَ يَمِينِي بِشِمَالِهِ وَشِمَالَ أَبِي الدَّرْدَاءِ بِيَمِينِهِ، فَخَرَجَ يَمْشِي بَيْنَنَا وَنَحْنُ نَنْتَجِي وَاللهُ أَعْلَمُ بمَا نَتَنَاجَى وَذَاكَ قَوْلُهُ، فَقَالَ عُبَادَةُ بْنُ الصَّامِتِ: لَئِنْ طَالَ بِكُمَا عُمْرُ أَحَدِكُمَا أَوْ كِلَاكُمَا لَتُوشِكَانِ أَنْ تَرَيَا الرَّجُلَ مِنْ ثَبَجِ الْمُسْلِمِينَ - يَعْنِي مِنْ وَسَطٍ - قَرَأَ الْقُرْآنَ عَلَى لِسَانِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَعَادَهُ وَأَبْدَاهُ، وَأَحَلَّ حَلَالَهُ، وَحَرَّمَ حَرَامَهُ، وَنَزَلَ عِنْدَ مَنَازِلِهِ، أَوْ قَرَأَهُ عَلَى لِسَانِ أَخِيهِ قِرَاءَةً عَلَى لِسَانِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَعَادَهُ وَأَبْدَاهُ، وَأَحَلَّ حَلَالَهُ، وَحَرَّمَ حَرَامَهُ، وَنَزَلَ عِنْدَ مَنَازِلِهِ، لَا يَحُورُ فِيكُمْ إِلَّا كَمَا يَحُورُ رَأْسُ الْحِمَارِ الْمَيِّتِ. قَالَ: فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ طَلَعَ شَدَّادُ بْنُ أَوْسٍ وَعَوْفُ بْنُ مَالِكٍ، فَجَلَسَا إِلَيْنَا، فَقَالَ شَدَّادٌ: إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ أَيُّهَا النَّاسُ لَمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مِنَ الشَّهْوَةِ الْخَفِيَّةِ وَالشِّرْكِ فَقَالَ عُبَادَةُ بْنُ الصَّامِتِ وَأَبُو الدَّرْدَاءِ: اللهُمَّ غَفْرًا، أَوَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ حَدَّثَنَا: إِنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ يُعْبَدَ فِي جَزِيرَةِ الْعَرَبِ؟ ؟ فَأَمَّا الشَّهْوَةُ الْخَفِيَّةُ فَقَدْ عَرَفْنَاهَا، هِيَ شَهَوَاتُ الدُّنْيَا مِنْ نِسَائِهَا وَشَهَوَاتِهَا، فَمَا هَذَا الشِّرْكُ الَّذِي تُخَوِّفُنَا بِهِ يَا شَدَّادُ؟ فَقَالَ شَدَّادٌ: أَرَأَيْتُكُمْ لَوْ رَأَيْتُمْ رَجُلًا يُصَلِّي لِرَجُلٍ، أَوْ يَصُومُ لَهُ، أَوْ يَتَصَدَّقُ لَهُ، أَتَرَوْنَ أَنَّهُ قَدْ أَشْرَكَ؟ قَالُوا: نَعَمْ وَاللهِ، إِنَّهُ مَنْ صَلَّى لِرَجُلٍ، أَوْ صَامَ لَهُ، أَوْ تَصَدَّقَ لَهُ، لَقَدْ أَشْرَكَ. فَقَالَ شَدَّادٌ: فَإِنِّي قَدْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ صَلَّى يُرَائِي فَقَدْ أَشْرَكَ، وَمَنْ صَامَ يُرَائِي فَقَدْ أَشْرَكَ، وَمَنْ تَصَدَّقَ يُرَائِي فَقَدْ أَشْرَكَ. فَقَالَ عَوْفُ بْنُ مَالِكٍ عِنْدَ ذَلِكَ: أَفَلَا يَعْمِدُ إِلَى مَا ابْتُغِيَ فِيهِ وَجْهُهُ مِنْ ذَلِكَ الْعَمَلِ كُلِّهِ، فَيَقْبَلَ مَا خَلَصَ لَهُ، وَيَدَعَ مَا يُشْرَكُ بِهِ؟ فَقَالَ شَدَّادٌ عِنْدَ ذَلِكَ: فَإِنِّي قَدْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: أَنَا خَيْرُ قَسِيمٍ لِمَنْ أَشْرَكَ بِي، مَنْ أَشْرَكَ بِي شَيْئًا فَإِنَّ حَشْدَهُ عَمَلَهُ قَلِيلَهُ وَكَثِيرَهُ لِشَرِيكِهِ الَّذِي أَشْرَكَهُ بِهِ، وَأَنَا عَنْهُ غَنِيٌّ."],"takhrij":"حسن: رواه أحمد (17140) واللفظ له، والطبراني في الكبير (7/337)، والحاكم (4/329)، وأبو نعيم في الحلية (1/268-269) كلهم من حديث عبد الحميد بن بهرام، عن شهر بن حوشب أنه سمع عبد الرحمن بن غنم يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17140), and this is his wording, al-Ṭabarānī in al-Muʿjam al-Kabīr (7/337), al-Ḥākim (4/329), and Abū Nuʿaym in Ḥilyat al-Awliyāʾ (1/268–269).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Shahr ibn Ḥawshab narrated that he heard Ibn Ghanm say: When Abū al-Dardāʾ and I entered the mosque of al-Jābiyah, we met ʿUbādah ibn al-Ṣāmit. He took my right hand with his left and the left hand of Abū al-Dardāʾ with his right, and walked between us while we were speaking privately—and Allah knows best what we were speaking about. ʿUbādah ibn al-Ṣāmit said: “If either one of you, or both of you, live long enough, you will soon see a man from the very midst of the Muslims who has learned the Qur’an directly from the tongue of Muḥammad ﷺ, repeating and reciting it, treating its lawful as lawful and its unlawful as unlawful, and observing its proper limits; or who learned it from his brother exactly as it was recited from the tongue of Muḥammad ﷺ, repeating and reciting it, treating its lawful as lawful and its unlawful as unlawful, and observing its proper limits—yet among you he will be of no more benefit than the head of a dead donkey.” While we were in that state, Shaddād ibn Aws and ʿAwf ibn Mālik arrived and sat with us. Shaddād said: “O people, what I fear most for you is what I heard the Messenger of Allah ﷺ mention: ‘Hidden desire and shirk.’” ʿUbādah ibn al-Ṣāmit and Abū al-Dardāʾ said: “O Allah, forgive us! Did the Messenger of Allah ﷺ not tell us: ‘Satan has despaired of being worshiped in the Arabian Peninsula’?” They continued: “As for hidden desire, we know what that is: the desires of this world, including its women and other attractions. But what is this shirk about which you are frightening us, O Shaddād?” Shaddād replied: “Suppose you saw a man praying for the sake of another person, fasting for his sake, or giving charity for his sake. Would you consider that shirk?” They replied: “Yes, by Allah. Whoever prays, fasts, or gives charity for another person has committed shirk.” Shaddād said: “I heard the Messenger of Allah ﷺ say: ‘Whoever prays to show off has committed shirk; whoever fasts to show off has committed shirk; and whoever gives charity to show off has committed shirk.’” ʿAwf ibn Mālik then said: “Would Allah not take from the entirety of that deed what was sincerely intended for His Face, accept what was purely for Him, and leave aside what involved association?” Shaddād replied: “I heard the Messenger of Allah ﷺ say: ‘Allah, Mighty and Majestic, says: I am the best One with whom a share may be assigned. Whoever associates anything with Me, then the entirety of his deed—little or much—is for the partner whom he associated with Me, and I have no need of it.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10702],"tks":"حسن: رواه أحمد (17140) واللفظ له، والطبراني في الكبير (7/337)، والحاكم (4/329)، وأبو نعيم في الحلية (1/268-269)."},{"num":14989,"demo":false,"sanad":"","matn":["عَنِ الضَّحَّاكِ بْنِ قَيْسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ اللَّهَ يَقُولُ: أَنَا خَيْرُ شَرِيكٍ، فَمَنْ أَشْرَكَ بِي أَحَدًا فَهُوَ لِشَرِيكِي، يَا أَيُّهَا النَّاسُ، أَخْلِصُوا الْأَعْمَالَ لِلَّهِ، فَإِنَّ اللَّهَ عز وجل لَا يَقْبَلُ مِنَ الْعَمَلِ أَلَا مَا خَلُصَ لَهُ، وَلَا تَقُولُوا: هَذَا لِلَّهِ وَلِلرَّحِمِ، فَإِنَّهُ لِلرَّحِمِ، وَلَيْسَ لِلَّهِ مِنْهُ شَيْءٌ، وَلَا تَقُولُوا: هَذَا لِلَّهِ وَلِوُجُوهِكُمْ، فَإِنَّهُ لِوُجُوهِكُمْ، وَلَيْسَ لِلَّهِ عز وجل مِنْهُ شَيْءٌ."],"takhrij":"حسن: رواه ابنُ قانع في معجم الصحابة (473) عن أحمد بن يحيى بن إسحاق، نا سعيد بن سليمان، عن عبيدة بن حميد، عن عبدالعزيز بن رفيع، عن تميم بن سلمة، عن الضحاك بن قيس قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Qāniʿ in Muʿjam al-Ṣaḥābah (473).","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Al-Ḍaḥḥāk ibn Qays narrated that the Messenger of Allah ﷺ said: “Allah says: ‘I am the best of partners. Whoever associates someone with Me, then his deed belongs to that partner.’ O people, make your deeds sincere for Allah, for Allah, Mighty and Majestic, accepts no deed except that which is sincerely for Him. Do not say, ‘This is for Allah and for maintaining family ties,’ for then it is for the family ties and Allah has no share in it. And do not say, ‘This is for Allah and for gaining people’s favor,’ for then it is for gaining people’s favor and Allah, Mighty and Majestic, has no share in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن قانع في معجم الصحابة (473)."},{"num":14990,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَتَذَاكَرُ الْمَسِيحَ الدَّجَّالَ، فَقَالَ: أَلاَ أُخْبِرُكُمْ بِمَا هُوَ أَخْوَفُ عَلَيْكُمْ عِنْدِي مِنَ الْمَسِيحِ الدَّجَّالِ. قَالَ: قُلْنَا بَلَى. فَقَالَ: الشِّرْكُ الْخَفِيُّ: أَنْ يَقُومَ الرَّجُلُ يُصَلِّي فَيُزَيِّنُ صَلاَتَهُ لِمَا يَرَى مِنْ نَظَرِ رَجُلٍ."],"takhrij":"حسن: رواه ابن ماجه (4204) عن عبد الله بن سعيد، حدثنا أبو خالد الأحمر، عن كثير بن زيد، عن رُبيح بن عبد الرحمن بن أبي سعيد الخدري، عن أبيه، عن أبي سعيد قال: فذكره. وإسناده حسن من أجل ربيح بن عبد الرحمن مختلف فيه غير أنه حسن الحديث، قال أبو زرعة: شيخ، وقال ابن عدي: أرجو أنه لا بأس به، وذكره ابن حبان في الثقات، فيُحسّن حديثه إذا كان له أصل، وهذا منه. وقد حسّنه أيضا البوصيري في الزوائد.","grade":"حسن","chapter_ar":"باب ما جاء في الشرك الأصغر والخفي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4204). Its chain is good because of Rubayḥ ibn ʿAbd al-Raḥmān, concerning whom there is disagreement, though his hadith is acceptable. Abū Zurʿah called him a shaykh; Ibn ʿAdī said, “I hope there is no harm in him”; and Ibn Ḥibbān included him among the trustworthy narrators. His hadith is therefore graded good when it has a supporting basis, as this one does. Al-Būṣīrī also graded it good in al-Zawāʾid.","chapter_en":"What Has Been Narrated Concerning Minor and Hidden Shirk","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":30,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: The Messenger of Allah ﷺ came out to us while we were discussing al-Masīḥ al-Dajjāl. He said: “Shall I tell you what I fear for you even more than al-Masīḥ al-Dajjāl?” We replied: “Yes.” He said: “Hidden shirk: a man stands to pray and beautifies his prayer because he notices another man watching him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4204). وإسناده حسن من أجل ربيح بن عبد الرحمن؛ مختلف فيه، غير أنه حسن الحديث. قال أبو زرعة: شيخ، وقال ابن عدي: أرجو أنه لا بأس به، وذكره ابن حبان في الثقات، فيحسن حديثه إذا كان له أصل، وهذا منه. وقد حسنه أيضا البوصيري في الزوائد."},{"num":14991,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  اتَّقُوا الظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ، فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ، حَمَلَهُمْ عَلَى أَنْ سَفَكُوا دِمَاءَهُمْ، وَاسْتَحَلُّوا مَحَارِمَهُمْ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2578: 56) عن عبدالله بن مسلمة بن قعنب، حدثنا داود يعني ابن قيس، عن عبيدالله بن مقسم، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ذم الشح والجبن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2578:56).","chapter_en":"Condemnation of Avarice and Cowardice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":31,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be layers of darkness on the Day of Resurrection. And beware of avarice, for avarice destroyed those who came before you. It drove them to shed one another’s blood and to make lawful what was sacred among them.”"]}},"tuhfa":{},"full":1,"rep":[5909,12734,13524,14895],"tks":"صحيح: رواه مسلم (2578: 56)."},{"num":14992,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: شَرُّ مَا فِي رَجُلٍ شُحٌّ هَالِعٌ، وَجُبْنٌ خَالِعٌ."],"takhrij":"صحيح: رواه أبو داود (2511)، وأحمد (8010، 8263)، وابن حبان (3250)، والبيهقي (150) كلهم من طرق عن موسى بن عُلي بن رباح، عن أبيه، عن عبد العزيز بن مروان، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ذم الشح والجبن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2511), Aḥmad (8010, 8263), Ibn Ḥibbān (3250), and al-Bayhaqī (9/170).","chapter_en":"Condemnation of Avarice and Cowardice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":31,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “The worst traits that can be in a man are overwhelming avarice and devastating cowardice.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (2511)، وأحمد (8010، 8263)، وابن حبان (3250)، والبيهقي (150)."},{"num":14993,"demo":false,"sanad":"","matn":["عَنْ عَمْرٍو الْبِكَالِيِّ، عَنِ الْأَعْوَرِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: مَا أَخَافُ عَلَى أُمَّتِي إِلَّا ثَلَاثًا: شُحٌّ مُطَاعٌ، وَهَوًى مُتَّبَعٌ، وَإِمَامٌ ضَالٌّ."],"takhrij":"حسن: رواه ابنُ قانع في معجم الصحابة (707)، وأبو نعيم في معرفة الصحابة (5071) كلاهما من طريق أبي عبد الرحمن المقرئ، عن ابن لهيعة، حدثني ابنُ هبيرة، عن عمرو البكالي، عن أبي الأعور قال: فذكره.","grade":"حسن","chapter_ar":"باب ذم الشح والجبن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Qāniʿ in Muʿjam al-Ṣaḥābah (2/206) and Abū Nuʿaym in Maʿrifat al-Ṣaḥābah (4/2018).","chapter_en":"Condemnation of Avarice and Cowardice","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":31,"content":{"translation":{"en":["Abū al-Aʿwar al-Sulamī narrated that the Messenger of Allah ﷺ said: “I fear only three things for my Ummah: avarice that is obeyed, desire that is followed, and a misguided leader.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن قانع في معجم الصحابة (707)، وأبو نعيم في معرفة الصحابة (5071)."},{"num":14994,"demo":false,"sanad":"","matn":["عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ لِفُلَانٍ نَخْلَةً فِي حَائِطِي، فَمُرْهُ فَلْيَبِعْنِيهَا، أَوْ لِيَهَبْهَا لِي، قَالَ: فَأَبَى الرَّجُلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: افْعَلْ، وَلَكَ بِهَا نَخْلَةٌ فِي الْجَنَّةِ، فَأَبَى، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا أَبْخَلُ النَّاسِ."],"takhrij":"صحيح: رواه أحمد (23085) عن وكيع، حدثنا الأعمش، عن أبي صالح ذكوان، عن بعض أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم البخل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23085).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Miserliness","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":32,"content":{"translation":{"en":["One of the Companions of the Prophet ﷺ narrated: A man came to the Prophet ﷺ and said: “O Messenger of Allah, so-and-so owns a date-palm in my garden. Tell him to sell it to me or give it to me.” The man refused. The Messenger of Allah ﷺ said to him: “Do so, and in exchange you will have a date-palm in Paradise.” He still refused. The Prophet ﷺ then said: “This is the most miserly of people.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4052],"tks":"صحيح: رواه أحمد (23085)."},{"num":14995,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنَّ لِفُلَانٍ فِي حَائِطِي عَذْقًا، وَإِنَّهُ قَدْ آذَانِي، وَشَقَّ عَلَيَّ مَكَانُ عَذْقِهِ، فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: بِعْنِي عَذْقَكَ الَّذِي فِي حَائِطِ فُلَانٍ قَالَ: لَا، قَالَ: فَهَبْهُ لِي، قَالَ: لَا، قَالَ: فَبِعْنِيهِ بِعَذْقٍ فِي الْجَنَّةِ، قَالَ: لَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا رَأَيْتُ الَّذِي هُوَ أَبْخَلُ مِنْكَ، إِلَّا الَّذِي يَبْخَلُ بِالسَّلَامِ."],"takhrij":"حسن: رواه أحمد (14517) عن أبي عامر العقدي، حدثنا زهير، عن عبد الله بن محمد بن عقيل، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذم البخل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (14517).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Miserliness","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":32,"content":{"translation":{"en":["Jābir narrated: A man came to the Prophet ﷺ and said: “So-and-so owns a cluster-bearing date-palm in my garden, and its location has caused me harm and hardship.” The Prophet ﷺ sent for its owner and said: “Sell me your date-palm that is in so-and-so’s garden.” He replied: “No.” The Prophet ﷺ said: “Then give it to me as a gift.” He replied: “No.” The Prophet ﷺ said: “Then sell it to me in exchange for a date-palm in Paradise.” He again replied: “No.” The Prophet ﷺ said: “I have not seen anyone more miserly than you except one who is miserly even with the greeting of salām.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14244],"tks":"حسن: رواه أحمد (14517)."},{"num":14996,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللهِ ﷺ قَالَ: يَا أَيُّهَا النَّاسُ ابْتَاعُوا أَنْفُسَكُمْ مِنَ اللهِ عَزَّ وَجَلَّ، فَإِنْ بَخِلَ أَحَدُكُمْ أَنْ يُعْطِيَ مَالَهُ النَّاسَ فَلْيَتَصَدَّقْ عَلَى نَفْسِهِ، فَلْيَأْكُلْ وَلْيَلْبِسْ مِمَّا رَزَقَهُ اللهُ."],"takhrij":"صحيح: رواه البيهقي في شعب الإيمان (4250) بإسناده من طريق محمد بن الوليد البسري، حدثنا حبان بن هلال، حدثنا سليم بن حيان، حدثنا حميد بن هلال، يحدّث عن أبي قلابة، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم البخل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqī in Shuʿab al-Īmān (4250).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Miserliness","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":32,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “O people, purchase your own souls from Allah, Mighty and Majestic. If one of you is too miserly to give his wealth to other people, then let him at least spend charitably upon himself: let him eat and clothe himself from what Allah has provided him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي في شعب الإيمان (4250)."},{"num":14997,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوْصِنِي. قَالَ: لاَ تَغْضَبْ. فَرَدَّدَ مِرَارًا، قَالَ: لاَ تَغْضَبْ."],"takhrij":"صحيح: رواه البخاري في الأدب (6161) عن يحيى بن يوسف، أخبرنا أبو بكر هو ابن عياش، عن أبي حصين، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الحذر من الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6161).","chapter_en":"Guarding against Anger","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah narrated: A man said to the Prophet ﷺ: “Advise me.” He replied: “Do not become angry.” The man repeated his request several times, and each time the Prophet ﷺ said: “Do not become angry.”"]},"intro":{"ar":["قال تعالى:","﴿وَالَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ﴾ [الشورى: ٣٧].","وقال تعالى:","﴿الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ وَاللّٰهُ يُحِبُّ الْمُحْسِنِينَ﴾ [آل عمران: ١٣٤]."],"en":["Allah, the Exalted, says:","“And those who avoid the major sins and shameful deeds, and when they become angry, they forgive.”","[Sūrat al-Shūrā 42:37]","And He, the Exalted, says:","“Those who spend in prosperity and adversity, who restrain their anger and pardon people—and Allah loves those who do good.”","[Sūrat Āl ʿImrān 3:134]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6161)."},{"num":14998,"demo":false,"sanad":"","matn":["عن جارية بن قدامة أَنَّ رَجُلًا قَالَ لَهُ: يَا رَسُولَ اللَّهِ، قُلْ لِي قَوْلًا وَأَقْلِلْ عَلَيَّ لَعَلِّي أَعْقِلُهُ، قَالَ: لَا تَغْضَبْ فَأَعَادَ عَلَيْهِ مِرَارًا كُلُّ ذَلِكَ يَقُولُ: لَا تَغْضَبْ."],"takhrij":"صحيح: رواه أحمد (15964)، وابن حبان (5690) كلاهما من حديث يحيى بن سعيد، عن هشام بن عروة، عن أبيه، عن الأحنف بن قيس، عن جارية بن قدامة فذكره. وإسناده صحيح، ووقع اختلاف طويل في إسناده، وما ذكرته هو أسلمها كما لمح ابن حجر في ترجمة من الإصابة.","grade":"صحيح","chapter_ar":"باب الحذر من الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (15964) and Ibn Ḥibbān (5690). Its chain is authentic. There is a lengthy disagreement concerning its chain, and the route cited here is the safest of them, as Ibn Ḥajar indicated in the biographical entry in al-Iṣābah.","chapter_en":"Guarding against Anger","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":33,"content":{"translation":{"en":["Jāriyah ibn Qudāmah narrated: A man said: “O Messenger of Allah, tell me something, but keep it brief so that I may understand and retain it.” He replied: “Do not become angry.” The man repeated the request several times, and every time the Prophet ﷺ said: “Do not become angry.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15964)، وابن حبان (5690). وإسناده صحيح، ووقع اختلاف طويل في إسناده، وما ذكرته هو أسلمها كما لمح ابن حجر في ترجمته في الإصابة."},{"num":14999,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَوْصِنِي؟ قَالَ: لَا تَغْضَبْ، قَالَ: قَالَ الرَّجُلُ: فَفَكَّرْتُ حِينَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا قَالَ، فَإِذَا الْغَضَبُ يَجْمَعُ الشَّرَّ كُلَّهُ.","وفي لفظ: عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ صلى الله عليه وسلم: أَخْبِرْنِي بِكَلِمَاتٍ أَعِيشُ بِهِنَّ وَلَا تُكْثِرْ عَلَيَّ فَأَنْسَى قَالَ: اجْتَنِبِ الْغَضَبَ ثُمَّ أَعَادَ عَلَيْهِ، فَقَالَ: اجْتَنِبِ الْغَضَبَ."],"takhrij":"صحيح: رواه أحمد (23171) عن عبد الرزاق- وهو في مصنفه (20286)- عن معمر، عن الزهري، عن حميد بن عبد الرحمن، عن رجل من أصحاب رسول الله صلى الله عليه وسلم فذكره. وإسناده صحيح، وجهالة الصحابي لا تضر.","grade":"صحيح","chapter_ar":"باب الحذر من الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23171) through ʿAbd al-Razzāq, and it is also in his Muṣannaf (20286). Its chain is authentic, and the anonymity of a Companion does not harm the chain.","chapter_en":"Guarding against Anger","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":33,"content":{"translation":{"en":["A man from among the Companions of the Messenger of Allah ﷺ narrated: A man said: “Advise me, O Messenger of Allah.” He replied: “Do not become angry.” The man said: “I reflected upon what the Messenger of Allah ﷺ had said and realized that anger gathers together every form of evil.”","In another wording, a man said to the Prophet ﷺ: “Tell me some words by which I may live, but do not give me too many lest I forget.” He said: “Avoid anger.” The man repeated his request, and the Prophet ﷺ again said: “Avoid anger.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23171) عن عبد الرزاق - وهو في مصنفه - (20286). وإسناده صحيح، وجهالة الصحابي لا تضر."}]);